INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86458, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "年纪小的人；儿童。", "primary_collocate": null, "pronunciation": "xiǎo hái", "ipa": "ɕiɑʊ˨˩ xaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "那个小孩在公园里玩。", "target_word": "小孩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个小孩今年三岁。", "target_word": "小孩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩喜欢吃甜的东西。", "target_word": "小孩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩哭了，妈妈马上抱起他。", "target_word": "小孩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家有两个小孩，一个男孩，一个女孩。", "target_word": "小孩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩晚上要早点睡觉。", "target_word": "小孩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师带着小孩们过马路。", "target_word": "小孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院里有很多小孩在看动画片。", "target_word": "小孩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我小时候是个爱哭的小孩。", "target_word": "小孩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小孩很聪明，学东西学得很快。", "target_word": "小孩", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小孩儿", "label": "儿化"}, {"form": "小孩子", "label": "复合"}], "register": "口语", "sense_fingerprint": "年纪小的人，儿童（泛指幼小的人）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23a80a73-35d5-4323-a9ea-7981b33b5d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小孩", "is_correct": true, "explanation": "正确：「小孩」指年纪小的人，可以在公园里玩。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是没有生命的物品，不会在公园里玩耍。"}, {"text": "石头", "is_correct": false, "explanation": "配价：「玩」需要能行动的人作主语，石头不能做它的主语。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是被玩的东西，本身不会「玩」。"}], "explanations": {"小孩": "正确：「小孩」指年纪小的人，可以在公园里玩。", "椅子": "语义：椅子是没有生命的物品，不会在公园里玩耍。", "石头": "配价：「玩」需要能行动的人作主语，石头不能做它的主语。", "玩具": "语义：玩具是被玩的东西，本身不会「玩」。"}, "sentence_index": 0, "correct_answer": "小孩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只母狗生了一窝小孩，个个都很可爱。", "explanation": "这里应该用〈小狗〉。「小孩」指人，不能用来指动物的幼崽。"}, {"text": "那个小孩是大学教授，每学期都给研究生上课。", "explanation": "「小孩」指年纪小的人，不能用来指大学教授这样的成年人。"}, {"text": "这个小孩是我的师父，教我做木工。", "explanation": "「小孩」指年纪小的人，不能用来指教我做木工的师父。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小孩", "is_correct": true, "explanation": "正确：「小孩们」指一群年纪小的孩子，可以被老师带着过马路。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能被「带着」一起过马路，句子语义不通。"}, {"text": "书本", "is_correct": false, "explanation": "语义：「书本」没有生命，不能被老师带着过马路，「们」一般也不加在它后面。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：「花朵」无法自己行走，不能被老师带着过马路，「们」一般也不加在它后面。"}], "explanations": {"小孩": "正确：「小孩们」指一群年纪小的孩子，可以被老师带着过马路。", "汽车": "语义：汽车不能被「带着」一起过马路，句子语义不通。", "书本": "语义：「书本」没有生命，不能被老师带着过马路，「们」一般也不加在它后面。", "花朵": "语义：「花朵」无法自己行走，不能被老师带着过马路，「们」一般也不加在它后面。"}, "sentence_index": 6, "correct_answer": "小孩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小孩在公司当总经理，管着三百个员工。", "explanation": "「小孩」指年纪小的人，与担任总经理、管理员工的成年人相矛盾。"}, {"text": "这个小孩是我的父亲，他今年六十岁。", "explanation": "「小孩」指年纪小的人，不能用来指父亲，更不能用于六十岁的人。"}, {"text": "这个小孩已经结婚三次了，每次都离了婚。", "explanation": "「小孩」指年纪小的人，不能用来指结过三次婚的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "广场上有三个小孩们在放风筝。", "corrected_sentence": "广场上有三个小孩在放风筝。", "error_description": "多余的复数标记：「三个」已表示确切数量，「小孩」后面不能再加「们」，应说「三个小孩」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个很聪明小孩学东西学得很快。", "corrected_sentence": "这个很聪明的小孩学东西学得很快。", "error_description": "修饰语与中心语之间漏掉「的」：「很聪明」修饰「小孩」时需要加「的」，应说「很聪明的小孩」，不能说「很聪明小孩」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86459, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "痛苦", "is_correct": true, "explanation": "反义：“痛苦”与“幸福”相对，一个是心里难受，一个是心里快乐满足。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：“聪明”说的是智力，与“幸福”所指的心理感受没有对应关系。"}, {"text": "复杂", "is_correct": false, "explanation": "无反义关系：“复杂”说事情或结构繁多，与“幸福”不构成反义。"}, {"text": "干净", "is_correct": false, "explanation": "无反义关系：“干净”说卫生状况，与“幸福”所指的生活感受无关。"}], "correct_answer": "痛苦", "explanations": {"痛苦": "反义：“痛苦”与“幸福”相对，一个是心里难受，一个是心里快乐满足。", "聪明": "无反义关系：“聪明”说的是智力，与“幸福”所指的心理感受没有对应关系。", "复杂": "无反义关系：“复杂”说事情或结构繁多，与“幸福”不构成反义。", "干净": "无反义关系：“干净”说卫生状况，与“幸福”所指的生活感受无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86459, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "痛苦", "is_correct": true, "explanation": "反义：“痛苦”与“幸福”相对，一个是心里难受，一个是心里快乐满足。"}, {"text": "漂亮", "is_correct": false, "explanation": "无反义关系：“漂亮”说外貌好看，与“幸福”所指的感受不构成反义。"}, {"text": "粗糙", "is_correct": false, "explanation": "无反义关系：“粗糙”说质地或表面，与“幸福”无关。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：“安静”说环境或状态没有声响，与“幸福”不构成反义。"}], "correct_answer": "痛苦", "explanations": {"痛苦": "反义：“痛苦”与“幸福”相对，一个是心里难受，一个是心里快乐满足。", "漂亮": "无反义关系：“漂亮”说外貌好看，与“幸福”所指的感受不构成反义。", "粗糙": "无反义关系：“粗糙”说质地或表面，与“幸福”无关。", "安静": "无反义关系：“安静”说环境或状态没有声响，与“幸福”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86459, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "幸福是心里觉得很快乐，很满足。", "primary_collocate": null, "pronunciation": "xìng fú", "ipa": "ɕiŋ˥˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "我觉得现在的生活很幸福。", "target_word": "幸福", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到孩子笑，妈妈觉得很幸福。", "target_word": "幸福", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一家人在一起，真幸福！", "target_word": "幸福", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她想到家人，心里就很幸福。", "target_word": "幸福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃着妈妈做的饭，我觉得很幸福。", "target_word": "幸福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对他来说，有朋友就是幸福。", "target_word": "幸福", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新娘脸上带着幸福的笑容。", "target_word": "幸福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说他的晚年很幸福。", "target_word": "幸福", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们结婚后，生活得很幸福。", "target_word": "幸福", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候，和奶奶在一起是最幸福的事。", "target_word": "幸福", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幸福感", "label": "复合"}], "register": "中性", "sense_fingerprint": "心里快乐又满足", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b315749-fffd-4616-ac36-54b6cb1ab5fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86459, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”说人的情绪，不能用来形容“生活”。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”指明白、分明，说“生活很清楚”没有意义，与“我觉得”所表达的感受不合。"}, {"text": "幸福", "is_correct": true, "explanation": "“幸福”形容心里快乐、满足，正符合“我觉得……很”后面的感受描述。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容物体坚实，不能修饰“生活”。"}], "explanations": {"高兴": "搭配：“高兴”说人的情绪，不能用来形容“生活”。", "清楚": "语义：“清楚”指明白、分明，说“生活很清楚”没有意义，与“我觉得”所表达的感受不合。", "幸福": "“幸福”形容心里快乐、满足，正符合“我觉得……很”后面的感受描述。", "硬": "搭配：“硬”形容物体坚实，不能修饰“生活”。"}, "sentence_index": 0, "correct_answer": "幸福"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很幸福地通过了这次考试。", "explanation": "这里应该用〈顺利〉。幸福表示心里快乐满足，不能用来形容考试通过这类事情，应用顺利。"}, {"text": "孩子们在公园里玩得很幸福。", "explanation": "这里应该用〈快乐〉。幸福表示心里满足，此处只是一时玩耍的开心，应用快乐。"}, {"text": "这次比赛输了，大家都感到很幸福。", "explanation": "这里应该用〈失望〉。幸福表示心里快乐满足，比赛失利后的心情要用失望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86459, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粗", "is_correct": false, "explanation": "搭配：“粗”说物体的粗细，不能修饰“笑容”。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”表示愤怒，和新娘脸上的笑容相矛盾。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高度或程度，不能用来形容表情。"}, {"text": "幸福", "is_correct": true, "explanation": "“幸福”形容新娘此刻的快乐与满足，与笑容相合。"}], "explanations": {"粗": "搭配：“粗”说物体的粗细，不能修饰“笑容”。", "生气": "语义：“生气”表示愤怒，和新娘脸上的笑容相矛盾。", "高": "搭配：“高”说高度或程度，不能用来形容表情。", "幸福": "“幸福”形容新娘此刻的快乐与满足，与笑容相合。"}, "sentence_index": 6, "correct_answer": "幸福"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次面试我没有被录取，我感到很幸福。", "explanation": "这里应该用〈失落〉。幸福表示心里快乐满足，落选后的心情要用失落。"}, {"text": "他摔断了腿，躺在医院里感到很幸福。", "explanation": "这里应该用〈痛苦〉。幸福表示心里快乐满足，腿伤住院时的感受要用痛苦。"}, {"text": "他被公司辞退，失业在家，感到很幸福。", "explanation": "这里应该用〈焦虑〉。幸福表示心里快乐满足，失业后的心情要用焦虑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86459, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一家人在一起，幸福得生活。", "corrected_sentence": "我们一家人在一起，幸福地生活。", "error_description": "状语标记错误：“幸福”修饰动词“生活”时，中间应用“地”，不能用“得”（“得”用于动词、形容词之后引出补语）。应为“幸福地生活”，写成“幸福得生活”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86459, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "能和爸爸一起散步，我很最幸福。", "corrected_sentence": "能和爸爸一起散步，我最幸福。", "error_description": "程度副词重复：“最”和“很”不能同时修饰“幸福”，只用“最幸福”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86460, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不幸", "is_correct": true, "explanation": "反义：“不幸”与“幸福”相对，指生活不美满、心里不舒畅。"}, {"text": "热闹", "is_correct": false, "explanation": "无反义关系：“热闹”说场面喧闹，与“幸福”所指的生活状态不构成反义。"}, {"text": "便宜", "is_correct": false, "explanation": "无反义关系：“便宜”说价钱低，与“幸福”无反义对应。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”说光线充足，与“幸福”无关。"}], "correct_answer": "不幸", "explanations": {"不幸": "反义：“不幸”与“幸福”相对，指生活不美满、心里不舒畅。", "热闹": "无反义关系：“热闹”说场面喧闹，与“幸福”所指的生活状态不构成反义。", "便宜": "无反义关系：“便宜”说价钱低，与“幸福”无反义对应。", "明亮": "无反义关系：“明亮”说光线充足，与“幸福”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86460, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不幸", "is_correct": true, "explanation": "反义：“不幸”与“幸福”相对，指生活不美满。"}, {"text": "严格", "is_correct": false, "explanation": "无反义关系：“严格”说要求或管理的程度，与“幸福”无关。"}, {"text": "清淡", "is_correct": false, "explanation": "无反义关系：“清淡”说味道或颜色淡，与“幸福”无反义对应。"}, {"text": "整齐", "is_correct": false, "explanation": "无反义关系：“整齐”说排列规整，与“幸福”不构成反义。"}], "correct_answer": "不幸", "explanations": {"不幸": "反义：“不幸”与“幸福”相对，指生活不美满。", "严格": "无反义关系：“严格”说要求或管理的程度，与“幸福”无关。", "清淡": "无反义关系：“清淡”说味道或颜色淡，与“幸福”无反义对应。", "整齐": "无反义关系：“整齐”说排列规整，与“幸福”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86460, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "生活美满，心情舒畅。", "primary_collocate": null, "pronunciation": "xìng fú", "ipa": "ɕiŋ˥˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "祝你们新婚幸福！", "target_word": "幸福", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这对夫妻过得很幸福。", "target_word": "幸福", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她有好工作，有爱她的家人，非常幸福。", "target_word": "幸福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝爷爷奶奶身体健康，生活幸福。", "target_word": "幸福", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们有房子，有孩子，日子过得幸福。", "target_word": "幸福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫁给了爱她的人，一生都很幸福。", "target_word": "幸福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望孩子将来过幸福的日子。", "target_word": "幸福", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的人民生活得很幸福。", "target_word": "幸福", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "幸福的家庭都有说有笑。", "target_word": "幸福", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的婚姻幸福，丈夫对她很好。", "target_word": "幸福", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "幸福感", "label": "复合"}], "register": "中性", "sense_fingerprint": "生活美满、心情舒畅", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b315749-fffd-4616-ac36-54b6cb1ab5fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "健康", "is_correct": false, "explanation": "搭配：“健康”多说身体状况，不能放在“新婚”后面作祝福。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年龄，与新婚祝福的内容不相干。"}, {"text": "幸福", "is_correct": true, "explanation": "“幸福”指生活美满，正符合新婚时的祝福。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”说卫生或整洁，不能用来祝福婚姻。"}], "explanations": {"健康": "搭配：“健康”多说身体状况，不能放在“新婚”后面作祝福。", "年轻": "语义：“年轻”说年龄，与新婚祝福的内容不相干。", "幸福": "“幸福”指生活美满，正符合新婚时的祝福。", "干净": "搭配：“干净”说卫生或整洁，不能用来祝福婚姻。"}, "sentence_index": 0, "correct_answer": "幸福"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对这次旅行的安排很幸福。", "explanation": "这里应该用〈满意〉。幸福指生活美满、长久舒畅，对一次安排的满意要用满意。"}, {"text": "父亲在医院病床上昏迷不醒，他觉得很幸福。", "explanation": "这里应该用〈担忧〉。幸福表示生活美满，亲人病重时的心情要用担忧。"}, {"text": "周末的野餐，我们玩得很幸福。", "explanation": "这里应该用〈快乐〉。幸福偏重长久的生活状态，一次野餐的开心要用快乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深", "is_correct": false, "explanation": "搭配：“深”说距离或颜色的深浅，不能修饰“日子”。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线明亮，与“日子”的生活状态无关。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”指明白分明，说“过清楚的日子”没有意义。"}, {"text": "幸福", "is_correct": true, "explanation": "“幸福”指生活美满，正符合“希望孩子过……的日子”的祝愿。"}], "explanations": {"深": "搭配：“深”说距离或颜色的深浅，不能修饰“日子”。", "亮": "语义：“亮”说光线明亮，与“日子”的生活状态无关。", "清楚": "语义：“清楚”指明白分明，说“过清楚的日子”没有意义。", "幸福": "“幸福”指生活美满，正符合“希望孩子过……的日子”的祝愿。"}, "sentence_index": 6, "correct_answer": "幸福"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我被老板当众批评，心里觉得很幸福。", "explanation": "这里应该用〈委屈〉。幸福表示生活美满，被批评时的心情要用委屈。"}, {"text": "他的车被偷了，他觉得很幸福。", "explanation": "这里应该用〈懊恼〉。幸福表示生活美满，车子被偷后的心情要用懊恼。"}, {"text": "这次比赛失利，他感到很幸福。", "explanation": "这里应该用〈沮丧〉。幸福表示生活美满，比赛失利后的心情要用沮丧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一家人过地很幸福。", "corrected_sentence": "我们一家人过得很幸福。", "error_description": "补语标记错误：“过得很幸福”中，“得”是引出程度补语的标记，不能写成“地”（“地”用于状语）。应为“过得很幸福”，写成“过地很幸福”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的生活比以前最幸福。", "corrected_sentence": "她的生活比以前更幸福。", "error_description": "程度副词选择错误：“比”字比较句中应用“更”表示进一步的程度，“最”表示最高级，不能与“比”同用。应为“比以前更幸福”，写成“比以前最幸福”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86463, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狭小", "is_correct": true, "explanation": "狭小：面积窄小，与「广大」意思相反。"}, {"text": "寒冷", "is_correct": false, "explanation": "寒冷指温度低，与「广大」没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "严肃指态度认真、不随便，与「广大」无关。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软指不硬，与「广大」不构成反义。"}], "correct_answer": "狭小", "explanations": {"狭小": "狭小：面积窄小，与「广大」意思相反。", "寒冷": "寒冷指温度低，与「广大」没有反义关系。", "严肃": "严肃指态度认真、不随便，与「广大」无关。", "柔软": "柔软指不硬，与「广大」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86463, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狭小", "is_correct": true, "explanation": "狭小：窄小，与「广大」意思相反。"}, {"text": "安静", "is_correct": false, "explanation": "安静指没有声音，与「广大」没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰指清楚分明，与「广大」不构成反义。"}, {"text": "轻巧", "is_correct": false, "explanation": "轻巧指分量轻，与「广大」无关。"}], "correct_answer": "狭小", "explanations": {"狭小": "狭小：窄小，与「广大」意思相反。", "安静": "安静指没有声音，与「广大」没有反义关系。", "清晰": "清晰指清楚分明，与「广大」不构成反义。", "轻巧": "轻巧指分量轻，与「广大」无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86463, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "广大是又宽又大，或者人很多。", "primary_collocate": null, "pronunciation": "guǎng dà", "ipa": "kwɑŋ˨˩˦ ta˥˩", "syllable_count": 2, "sentences": [{"text": "山的那边是广大的平原。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有广大的土地。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广大观众都在等他的新电影。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广大的天空里一朵云也没有。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广大职工都同意这个办法。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在广大的校园里迷路了。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广大的农民欢迎这个新政策。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖面很广大，一眼看不到头。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事得到了广大群众的帮助。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广大的世界里，有很多我们不知道的事。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "廣大", "label": "繁体"}], "register": "中性", "sense_fingerprint": "又宽又大，或者人很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '695a92e4-d454-4f4c-ae8a-bd5477c4b635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86463, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "广大", "is_correct": true, "explanation": "广大：面积宽阔，正好形容平原。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：「锋利」形容刀刃等，不能用来形容平原。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：「甜美」形容声音、笑容或滋味，不能形容平原。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：「陡峭」指地势起伏很大，与平原平坦的特点相矛盾。"}], "explanations": {"广大": "广大：面积宽阔，正好形容平原。", "锋利": "搭配：「锋利」形容刀刃等，不能用来形容平原。", "甜美": "搭配：「甜美」形容声音、笑容或滋味，不能形容平原。", "陡峭": "语义：「陡峭」指地势起伏很大，与平原平坦的特点相矛盾。"}, "sentence_index": 0, "correct_answer": "广大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的数学成绩很广大。", "explanation": "这里应该用〈优秀〉。广大指面积宽阔或人数众多，成绩的好坏要用优秀。"}, {"text": "这个西瓜很广大。", "explanation": "这里应该用〈甜〉。广大用于空间或人数，不能形容味道。"}, {"text": "她唱得很广大。", "explanation": "这里应该用〈好〉。广大用于空间或人数，不能用来评价唱歌的水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86463, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "广大", "is_correct": true, "explanation": "广大：人数众多，形容农民这一群体。"}, {"text": "透明", "is_correct": false, "explanation": "语义：「透明」指物体能让光透过，不能形容一群人。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：「滚烫」形容温度高的物体，不能修饰农民。"}, {"text": "碧绿", "is_correct": false, "explanation": "搭配：「碧绿」形容颜色，不能修饰农民。"}], "explanations": {"广大": "广大：人数众多，形容农民这一群体。", "透明": "语义：「透明」指物体能让光透过，不能形容一群人。", "滚烫": "搭配：「滚烫」形容温度高的物体，不能修饰农民。", "碧绿": "搭配：「碧绿」形容颜色，不能修饰农民。"}, "sentence_index": 6, "correct_answer": "广大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天很广大。", "explanation": "这里应该用〈寒冷〉。广大用于空间或人数，不能形容天气的冷暖。"}, {"text": "这次考试很广大。", "explanation": "这里应该用〈轻松〉。广大不能形容考试的难易，考试容易要用轻松。"}, {"text": "这台机器很广大。", "explanation": "这里应该用〈庞大〉。广大指面积宽阔或人数众多，形容机器的体积要用庞大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那片平原很非常广大。", "corrected_sentence": "那片平原非常广大。", "error_description": "程度副词「很」和「非常」不能同时修饰同一个形容词，应只用「非常」，说「非常广大」。这里多用了「很」，说成「很非常广大」，语法错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家广大地很。", "corrected_sentence": "这个国家广大得很。", "error_description": "表示程度的补语要用「得」连接，说「广大得很」。这里误用「地」，「地」用于修饰动词，不能接在形容词后表示程度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
