INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86465, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "是不是用来问一件事对不对。", "primary_collocate": null, "pronunciation": "shì bu shì", "ipa": "ʂʐ̩˥˩ pu ʂʐ̩˥˩", "syllable_count": 3, "sentences": [{"text": "你说得对，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你昨天去过超市，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很有意思，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天九点见面，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是你的哥哥，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天很冷，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都在家等你，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不想去，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路能到学校，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你已经吃过饭了，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "放在句末，向对方求证一件事对不对的附加问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b315749-fffd-4616-ac36-54b6cb1ab5fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86465, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "简直", "is_correct": false, "explanation": "搭配：“简直”修饰程度，不能用在句末作求证。"}, {"text": "究竟", "is_correct": false, "explanation": "语义：“究竟”用来追问到底，接在“你说得对”后面，与求证语气不合。"}, {"text": "是不是", "is_correct": true, "explanation": "“是不是”放在句末，向对方求证，正符合“你说得对”后面的语气。"}, {"text": "难道", "is_correct": false, "explanation": "语法：“难道”是反问副词，不能放在句末作附加求证。"}], "explanations": {"简直": "搭配：“简直”修饰程度，不能用在句末作求证。", "究竟": "语义：“究竟”用来追问到底，接在“你说得对”后面，与求证语气不合。", "是不是": "“是不是”放在句末，向对方求证，正符合“你说得对”后面的语气。", "难道": "语法：“难道”是反问副词，不能放在句末作附加求证。"}, "sentence_index": 0, "correct_answer": "是不是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天九点见面，我确定已经定好了，是不是没定？", "explanation": "这里应该用〈确定〉。说话人已经确定，再用“是不是没定”发问就自相矛盾，应直接陈述。"}, {"text": "我们明天九点见面，我们已经说定了，是不是没说？", "explanation": "这里应该用〈已经〉。已经说定的事，不能用“是不是没说”发问，应直接说“已经说定”。"}, {"text": "我们明天九点见面，我很确定，是不是不见？", "explanation": "这里应该用〈肯定〉。说话人已很确定，再用“是不是不见”发问就自相矛盾，应直接用“肯定”陈述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86465, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "也许", "is_correct": false, "explanation": "语义：“也许”表示推测，与句末“是不是”的求证语气相矛盾。"}, {"text": "一定", "is_correct": false, "explanation": "语义：“一定”表示肯定，与句末的求证语气相冲突。"}, {"text": "是不是", "is_correct": true, "explanation": "“是不是”放在句末，向对方求证，正合此句“他们都在家等你”的语气。"}, {"text": "恐怕", "is_correct": false, "explanation": "语域：“恐怕”多用于委婉推测或不好的消息，口语中的句末求证不这样用。"}], "explanations": {"也许": "语义：“也许”表示推测，与句末“是不是”的求证语气相矛盾。", "一定": "语义：“一定”表示肯定，与句末的求证语气相冲突。", "是不是": "“是不是”放在句末，向对方求证，正合此句“他们都在家等你”的语气。", "恐怕": "语域：“恐怕”多用于委婉推测或不好的消息，口语中的句末求证不这样用。"}, "sentence_index": 6, "correct_answer": "是不是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我亲眼看见你吃过饭了，是不是没吃？", "explanation": "这里应该用〈确定〉。说话人已亲眼看见，再用“是不是没吃”发问就自相矛盾，应直接陈述。"}, {"text": "你已经吃过饭了，我很确定，是不是没吃？", "explanation": "这里应该用〈肯定〉。说话人已很确定，再用“是不是没吃”发问就自相矛盾，应直接用“肯定”陈述。"}, {"text": "你已经吃过饭了，我很确定，是不是要再吃一次？", "explanation": "这里应该用〈确定〉。说话人已很确定，再用“是不是要再吃一次”发问就自相矛盾，应直接陈述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天天气很好，是不是吗？", "corrected_sentence": "今天天气很好，是不是？", "error_description": "“是不是”已经是句末求证的说法，后面不能再加“吗”，应为“今天天气很好，是不是？”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86465, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都喜欢这部电影，是是不是？", "corrected_sentence": "我们都喜欢这部电影，是不是？", "error_description": "“是不是”多写了一个“是”，应为句末求证的“是不是”，写成“是是不是”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
