INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86466, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "用于提问，询问某件事是否属实、是否如此。", "primary_collocate": null, "pronunciation": "shì bu shì", "ipa": "ʂʐ̩˥˩ pu ʂʐ̩˥˩", "syllable_count": 3, "sentences": [{"text": "你是不是昨天没睡好？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是不是已经回家了？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是不是忘了带钥匙？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是不是星期五？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是不是你们班的新同学？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是不是不舒服，脸色这么差？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面是不是下雨了？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是不是你的？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是不是想家了？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师是不是还在办公室？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "放在谓语前，询问事情是否属实的疑问副词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b315749-fffd-4616-ac36-54b6cb1ab5fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从来", "is_correct": false, "explanation": "语义：“从来”指一贯如此，与“昨天”这一次具体的事不合。"}, {"text": "常常", "is_correct": false, "explanation": "语义：“常常”指经常发生，与“昨天”这一天的具体情况冲突。"}, {"text": "是不是", "is_correct": true, "explanation": "“是不是”放在谓语前，用来询问事情是否属实，正符合这个问句。"}, {"text": "更", "is_correct": false, "explanation": "搭配：“更”表示程度进一步，不能修饰“昨天没睡好”这样已经发生的事，句中说不通。"}], "explanations": {"从来": "语义：“从来”指一贯如此，与“昨天”这一次具体的事不合。", "常常": "语义：“常常”指经常发生，与“昨天”这一天的具体情况冲突。", "是不是": "“是不是”放在谓语前，用来询问事情是否属实，正符合这个问句。", "更": "搭配：“更”表示程度进一步，不能修饰“昨天没睡好”这样已经发生的事，句中说不通。"}, "sentence_index": 0, "correct_answer": "是不是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我肯定地告诉你，他是不是已经回家了。", "explanation": "这里应该用〈确实〉。“是不是”用于提问，这句是在肯定地告诉对方，不能用问句。"}, {"text": "我很确定，这件事是不是发生过。", "explanation": "这里应该用〈确实〉。“是不是”用于提问，这句是在肯定一件事，不能用问句。"}, {"text": "我很确定，你是不是说得对。", "explanation": "这里应该用〈肯定〉。“是不是”用于提问，这句是在说明确定的判断，不能用问句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词或心理动词，不能直接修饰“下雨”这样的动作。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”多修饰形容词，不修饰“下雨了”这一件事。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”说长期反复的情况，与“下雨了”这一次的事实不符。"}, {"text": "是不是", "is_correct": true, "explanation": "“是不是”放在谓语前，询问下雨的事是否属实，正符合问句。"}], "explanations": {"很": "搭配：“很”修饰形容词或心理动词，不能直接修饰“下雨”这样的动作。", "格外": "搭配：“格外”多修饰形容词，不修饰“下雨了”这一件事。", "总是": "语义：“总是”说长期反复的情况，与“下雨了”这一次的事实不符。", "是不是": "“是不是”放在谓语前，询问下雨的事是否属实，正符合问句。"}, "sentence_index": 6, "correct_answer": "是不是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我亲眼看见老师在办公室，是不是他不在办公室？", "explanation": "这里应该用〈确定〉。“是不是”表示疑问，说话人已亲眼看见，再用它来问就矛盾了，应直接陈述。"}, {"text": "我亲眼看见你们已经到了，是不是还没到？", "explanation": "这里应该用〈确定〉。“是不是”表示疑问，说话人已亲眼看见，用它去问“还没到”与事实矛盾。"}, {"text": "我亲眼看见他很喜欢这个颜色，是不是不喜欢它？", "explanation": "这里应该用〈确定〉。说话人已亲眼看见，再用“是不是”发问就不合逻辑，应直接陈述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天是不是没来上课吗？", "corrected_sentence": "他今天是不是没来上课？", "error_description": "疑问语气重复：“是不是”本身已经表示提问，句末不能再加“吗”。应为“他今天是不是没来上课？”，写成“……没来上课吗？”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小王今天是是不是来了？", "corrected_sentence": "小王今天是不是来了？", "error_description": "“是不是”多写了一个“是”。这个词是三个字的整体，应为“是不是来了”，写成“是是不是来了”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
