INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86474, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "指杂志、报纸、节目等分期出版或播出物中的一次。", "primary_collocate": null, "pronunciation": "qī", "ipa": "tɕʰi˥", "syllable_count": 1, "sentences": [{"text": "这期杂志很好看。", "target_word": "期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我每期都买这本杂志。", "target_word": "期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新一期的节目今晚播出。", "target_word": "期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "上一期的内容我还记得。", "target_word": "期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本杂志每月出一期。", "target_word": "期", "complexity_tier": "T3", "furigana": "qī", "sentence_source": "generated"}, {"text": "他的文章登在第十期上。", "target_word": "期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我错过了昨天那期节目。", "target_word": "期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这期报纸有一个大新闻。", "target_word": "期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下一期会介绍北京的美食。", "target_word": "期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杂志的最后一期今天出来了。", "target_word": "期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "期：杂志、报纸、节目等分期出版或播出物中的一次，如这期杂志、上一期节目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a212e406-1a81-4898-98b4-5a623bfc2f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86474, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "期", "is_correct": true, "explanation": "期 qī（第一声）是分期出版物的量词，即本题目标词。"}, {"text": "棋", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是棋。"}, {"text": "机", "is_correct": false, "explanation": "jī 与 qī 声母不同（j 与 q），意思是机器。"}, {"text": "气", "is_correct": false, "explanation": "qì（第四声）与 qī（第一声）声调不同，意思是空气。"}], "explanations": {"期": "期 qī（第一声）是分期出版物的量词，即本题目标词。", "棋": "qí（第二声）与 qī（第一声）声调不同，意思是棋。", "机": "jī 与 qī 声母不同（j 与 q），意思是机器。", "气": "qì（第四声）与 qī（第一声）声调不同，意思是空气。"}, "sentence_index": null, "correct_answer": "期"}, "level_3": {"options": [{"text": "期", "is_correct": true, "explanation": "“期”是杂志等分期出版物的量词，“这期杂志”指这一次出版的杂志。"}, {"text": "首", "is_correct": false, "explanation": "语义：“首”用于诗歌、歌曲，杂志不按首计算。"}, {"text": "幅", "is_correct": false, "explanation": "语义：“幅”用于画作、布匹，不能用来计算杂志。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、建筑等，不能说“这座杂志”。"}], "explanations": {"期": "“期”是杂志等分期出版物的量词，“这期杂志”指这一次出版的杂志。", "首": "语义：“首”用于诗歌、歌曲，杂志不按首计算。", "幅": "语义：“幅”用于画作、布匹，不能用来计算杂志。", "座": "搭配：“座”用于山、建筑等，不能说“这座杂志”。"}, "sentence_index": 0, "correct_answer": "期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这期手机很好用。", "explanation": "这里应该用〈款〉。手机按款计算，“期”指分期出版物的一次或一段规定的时间，不能用来修饰手机。"}, {"text": "我很喜欢这期歌，每天都听。", "explanation": "这里应该用〈首〉。歌曲按首计算，“期”不用于歌曲。"}, {"text": "这期戒指很漂亮。", "explanation": "这里应该用〈枚〉。戒指按枚计算，“期”指分期出版物的一次或一段规定的时间，不能用来修饰戒指。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86474, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "期", "is_correct": true, "explanation": "期 qī（第一声）是分期出版物的量词，即本题目标词。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 qī（第一声）声调不同，意思是起来。"}, {"text": "青", "is_correct": false, "explanation": "qīng 比 qī 多一个韵尾 ng，意思是青色。"}, {"text": "去", "is_correct": false, "explanation": "qù（第四声）与 qī（第一声）声调不同，意思是去往。"}], "explanations": {"期": "期 qī（第一声）是分期出版物的量词，即本题目标词。", "起": "qǐ（第三声）与 qī（第一声）声调不同，意思是起来。", "青": "qīng 比 qī 多一个韵尾 ng，意思是青色。", "去": "qù（第四声）与 qī（第一声）声调不同，意思是去往。"}, "sentence_index": null, "correct_answer": "期"}, "level_3": {"options": [{"text": "期", "is_correct": true, "explanation": "“那期节目”指昨天播出的一期节目，符合“错过了”。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物等成对或单个的东西，节目不能用“只”计算。"}, {"text": "桌", "is_correct": false, "explanation": "搭配：“桌”用于饭菜或桌子，不能说“那桌节目”。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于纸、票等平面的东西，不能说“那张节目”。"}], "explanations": {"期": "“那期节目”指昨天播出的一期节目，符合“错过了”。", "只": "搭配：“只”用于动物等成对或单个的东西，节目不能用“只”计算。", "桌": "搭配：“桌”用于饭菜或桌子，不能说“那桌节目”。", "张": "搭配：“张”用于纸、票等平面的东西，不能说“那张节目”。"}, "sentence_index": 6, "correct_answer": "期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这期桌子很结实。", "explanation": "这里应该用〈张〉。桌子按张计算，“期”指分期出版物的一次或一段规定的时间，不能用来修饰桌子。"}, {"text": "他买了两期鞋子。", "explanation": "这里应该用〈双〉。鞋按双计算，“期”指分期出版物的一次，不能用来计算鞋。"}, {"text": "这幅画的最后一期今天完成了。", "explanation": "这里应该用〈幅〉。画作按幅计算，“期”不用于画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上个月买了一个期杂志。", "corrected_sentence": "我上个月买了一期杂志。", "error_description": "“一期杂志”中，数词“一”直接接“期”，“期”前不能再加“个”。应说“一期杂志”，不能说“一个期杂志”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买到了这个期杂志。", "corrected_sentence": "我买到了这期杂志。", "error_description": "“期”是量词，前面不能再加量词“个”。“这个期杂志”错误，应说“这期杂志”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
