INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86475, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "敢是不害怕，有胆子去做。", "primary_collocate": null, "pronunciation": "gǎn", "ipa": "kan˨˩˦", "syllable_count": 1, "sentences": [{"text": "我不敢一个人走夜路。", "target_word": "敢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你敢跟老虎玩吗？", "target_word": "敢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很大胆，什么都敢吃。", "target_word": "敢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗不敢下水。", "target_word": "敢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟怕黑，不敢关灯睡觉。", "target_word": "敢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她敢站在台上唱歌了。", "target_word": "敢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你敢不敢和我比一比？", "target_word": "敢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我从来不敢一个人坐飞机。", "target_word": "敢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不敢看那个可怕的电影。", "target_word": "敢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她敢说真话，大家都很喜欢她。", "target_word": "敢", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不敢", "label": "否定式"}, {"form": "敢于", "label": "复合"}], "register": "通用", "sense_fingerprint": "不害怕，有胆子去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23a80a73-35d5-4323-a9ea-7981b33b5d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86475, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "敢", "is_correct": true, "explanation": "敢（gǎn，第三声）：表示有胆量去做某事，是本题的目标词。"}, {"text": "干", "is_correct": false, "explanation": "干（gān，第一声）与 gǎn 声调不同，意思是做、干活或干燥，与“有胆量”无关。"}, {"text": "甘", "is_correct": false, "explanation": "甘（gān，第一声）与 gǎn 声调不同，意思是甜、甘愿。"}, {"text": "肝", "is_correct": false, "explanation": "肝（gān，第一声）与 gǎn 声调不同，意思是肝脏。"}, {"text": "港", "is_correct": false, "explanation": "港（gǎng，第三声）与 gǎn 韵尾不同（-ng 与 -n），意思是港口。"}, {"text": "砍", "is_correct": false, "explanation": "砍（kǎn，第三声）与 gǎn 声母不同（k 与 g），意思是用刀斧砍伐。"}], "explanations": {"敢": "敢（gǎn，第三声）：表示有胆量去做某事，是本题的目标词。", "干": "干（gān，第一声）与 gǎn 声调不同，意思是做、干活或干燥，与“有胆量”无关。", "甘": "甘（gān，第一声）与 gǎn 声调不同，意思是甜、甘愿。", "肝": "肝（gān，第一声）与 gǎn 声调不同，意思是肝脏。", "港": "港（gǎng，第三声）与 gǎn 韵尾不同（-ng 与 -n），意思是港口。", "砍": "砍（kǎn，第三声）与 gǎn 声母不同（k 与 g），意思是用刀斧砍伐。"}, "sentence_index": null, "correct_answer": "敢"}, "level_3": {"options": [{"text": "敢", "is_correct": true, "explanation": "正确：「不敢」表示没有胆量，与“一个人走夜路”的害怕语境相符。"}, {"text": "应", "is_correct": false, "explanation": "语义：「不应」表示劝诫不该做，句中说的是害怕而不敢，语义不合。"}, {"text": "须", "is_correct": false, "explanation": "语义：「不须」表示不必要，句中说的是害怕而不敢，语义不合。"}, {"text": "必须", "is_correct": false, "explanation": "搭配：「必须」的否定是「不必」或「不能」，不说「不必须」。"}], "explanations": {"敢": "正确：「不敢」表示没有胆量，与“一个人走夜路”的害怕语境相符。", "应": "语义：「不应」表示劝诫不该做，句中说的是害怕而不敢，语义不合。", "须": "语义：「不须」表示不必要，句中说的是害怕而不敢，语义不合。", "必须": "搭配：「必须」的否定是「不必」或「不能」，不说「不必须」。"}, "sentence_index": 0, "correct_answer": "敢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他敢听懂法语，老师很惊讶。", "explanation": "这里应该用〈能〉。「敢」表示有胆量去做某事，强调的是勇气；听懂外语是能力问题，要用「能」。"}, {"text": "我敢游泳，三岁就学会了。", "explanation": "这里应该用〈会〉。「敢」表示有胆量去做，游泳是技能，应用「会」。"}, {"text": "他敢原谅我，我很感动。", "explanation": "这里应该用〈肯〉。「敢」表示冒险去做，原谅别人并不需要冒险；表示愿意时应用「肯」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86475, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "敢", "is_correct": true, "explanation": "敢（gǎn，第三声）：表示有胆量去做某事，是本题的目标词。"}, {"text": "柑", "is_correct": false, "explanation": "柑（gān，第一声）与 gǎn 声调不同，意思是柑橘。"}, {"text": "喊", "is_correct": false, "explanation": "喊（hǎn，第三声）与 gǎn 声母不同（h 与 g），意思是大声叫。"}, {"text": "搞", "is_correct": false, "explanation": "搞（gǎo，第三声）与 gǎn 韵尾不同（-o 与 -n），意思是做、弄。"}, {"text": "坎", "is_correct": false, "explanation": "坎（kǎn，第三声）与 gǎn 声母不同（k 与 g），意思是坑洼或坎儿。"}], "explanations": {"敢": "敢（gǎn，第三声）：表示有胆量去做某事，是本题的目标词。", "柑": "柑（gān，第一声）与 gǎn 声调不同，意思是柑橘。", "喊": "喊（hǎn，第三声）与 gǎn 声母不同（h 与 g），意思是大声叫。", "搞": "搞（gǎo，第三声）与 gǎn 韵尾不同（-o 与 -n），意思是做、弄。", "坎": "坎（kǎn，第三声）与 gǎn 声母不同（k 与 g），意思是坑洼或坎儿。"}, "sentence_index": null, "correct_answer": "敢"}, "level_3": {"options": [{"text": "敢", "is_correct": true, "explanation": "正确：「你敢不敢」是询问对方有没有胆量，与句意相符。"}, {"text": "胆量", "is_correct": false, "explanation": "语法：「胆量」是名词，不能充当能愿动词，「你胆量不敢」不成立。"}, {"text": "底气", "is_correct": false, "explanation": "语法：「底气」是名词，不能充当能愿动词，「你底气不敢」不成立。"}, {"text": "胆子", "is_correct": false, "explanation": "语法：「胆子」是名词，不能充当能愿动词，「你胆子不敢」不成立。"}], "explanations": {"敢": "正确：「你敢不敢」是询问对方有没有胆量，与句意相符。", "胆量": "语法：「胆量」是名词，不能充当能愿动词，「你胆量不敢」不成立。", "底气": "语法：「底气」是名词，不能充当能愿动词，「你底气不敢」不成立。", "胆子": "语法：「胆子」是名词，不能充当能愿动词，「你胆子不敢」不成立。"}, "sentence_index": 6, "correct_answer": "敢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她敢说三种语言，大家很佩服她。", "explanation": "这里应该用〈会〉。「敢」表示有胆量去做，说几种语言是能力问题，应用「会」。"}, {"text": "这道数学题很难，他敢一分钟就算对，老师很惊讶。", "explanation": "这里应该用〈能〉。「敢」表示有胆量去做，算对题是能力问题，应用「能」。"}, {"text": "他敢记住所有人的名字，真了不起。", "explanation": "这里应该用〈能〉。记住名字是能力问题，「敢」表示的胆量在这里不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86475, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他敢了一个人去森林探险。", "corrected_sentence": "他敢一个人去森林探险。", "error_description": "「敢」是能愿动词，后面不能直接加「了」。错误形式是「敢了」，正确形式是「敢」，应去掉「了」：「他敢一个人去森林探险」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86475, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我敢会当面对老师说实话。", "corrected_sentence": "我敢当面对老师说实话。", "error_description": "「敢」是能愿动词，不能与另一个能愿动词「会」连用。错误形式是「敢会」，应去掉「会」，说「我敢当面对老师说实话」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
