INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86476, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "有胆量做某事。", "primary_collocate": null, "pronunciation": "gǎn", "ipa": "kan˨˩˦", "syllable_count": 1, "sentences": [{"text": "谁敢去那个黑房子？", "target_word": "敢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他敢一个人去山里。", "target_word": "敢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不敢告诉爸爸这件事。", "target_word": "敢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她敢向老板提出自己的想法。", "target_word": "敢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们不敢大声说话。", "target_word": "敢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他敢开这么快的车，真大胆。", "target_word": "敢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你怎么敢这样对老师说话？", "target_word": "敢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人敢先站起来。", "target_word": "敢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他敢承认自己的错误，我很佩服他。", "target_word": "敢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不敢看着我的眼睛。", "target_word": "敢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不敢", "label": "否定式"}, {"form": "敢于", "label": "复合"}], "register": "通用", "sense_fingerprint": "有胆量做某事，敢作敢为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23a80a73-35d5-4323-a9ea-7981b33b5d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86476, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "敢", "is_correct": true, "explanation": "敢（gǎn，第三声）：有胆量做某事，是本题的目标词。"}, {"text": "干", "is_correct": false, "explanation": "干（gān，第一声）与 gǎn 声调不同，意思是做、干活或干燥。"}, {"text": "肝", "is_correct": false, "explanation": "肝（gān，第一声）与 gǎn 声调不同，意思是肝脏。"}, {"text": "港", "is_correct": false, "explanation": "港（gǎng，第三声）与 gǎn 韵尾不同（-ng 与 -n），意思是港口。"}, {"text": "砍", "is_correct": false, "explanation": "砍（kǎn，第三声）与 gǎn 声母不同（k 与 g），意思是砍伐。"}], "explanations": {"敢": "敢（gǎn，第三声）：有胆量做某事，是本题的目标词。", "干": "干（gān，第一声）与 gǎn 声调不同，意思是做、干活或干燥。", "肝": "肝（gān，第一声）与 gǎn 声调不同，意思是肝脏。", "港": "港（gǎng，第三声）与 gǎn 韵尾不同（-ng 与 -n），意思是港口。", "砍": "砍（kǎn，第三声）与 gǎn 声母不同（k 与 g），意思是砍伐。"}, "sentence_index": null, "correct_answer": "敢"}, "level_3": {"options": [{"text": "敢", "is_correct": true, "explanation": "正确：「谁敢去」是问谁有胆量去那个黑房子，与句意相符。"}, {"text": "须", "is_correct": false, "explanation": "语义：「谁应去」问的是该由谁去，句中问的是有没有胆量去，语义不同。"}, {"text": "应", "is_correct": false, "explanation": "语域：「应」多见于书面语，口语中不这样问。"}, {"text": "当", "is_correct": false, "explanation": "语域：「当」作情态用法多见于书面，口语中不说「谁当去那个黑房子」。"}], "explanations": {"敢": "正确：「谁敢去」是问谁有胆量去那个黑房子，与句意相符。", "须": "语义：「谁应去」问的是该由谁去，句中问的是有没有胆量去，语义不同。", "应": "语域：「应」多见于书面语，口语中不这样问。", "当": "语域：「当」作情态用法多见于书面，口语中不说「谁当去那个黑房子」。"}, "sentence_index": 0, "correct_answer": "敢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他敢背下这本词典。", "explanation": "这里应该用〈能〉。背下整本词典是能力问题，「敢」表示的胆量在这里不成立。"}, {"text": "她敢写毛笔字，大家都夸她。", "explanation": "这里应该用〈会〉。「敢」表示有胆量去做，写毛笔字是技能，应用「会」。"}, {"text": "他敢原谅我，我很感动。", "explanation": "这里应该用〈肯〉。原谅别人不需要冒险，表示愿意时应用「肯」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86476, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "敢", "is_correct": true, "explanation": "敢（gǎn，第三声）：有胆量做某事，是本题的目标词。"}, {"text": "柑", "is_correct": false, "explanation": "柑（gān，第一声）与 gǎn 声调不同，意思是柑橘。"}, {"text": "喊", "is_correct": false, "explanation": "喊（hǎn，第三声）与 gǎn 声母不同（h 与 g），意思是大声叫。"}, {"text": "搞", "is_correct": false, "explanation": "搞（gǎo，第三声）与 gǎn 韵尾不同（-o 与 -n），意思是做、弄。"}], "explanations": {"敢": "敢（gǎn，第三声）：有胆量做某事，是本题的目标词。", "柑": "柑（gān，第一声）与 gǎn 声调不同，意思是柑橘。", "喊": "喊（hǎn，第三声）与 gǎn 声母不同（h 与 g），意思是大声叫。", "搞": "搞（gǎo，第三声）与 gǎn 韵尾不同（-o 与 -n），意思是做、弄。"}, "sentence_index": null, "correct_answer": "敢"}, "level_3": {"options": [{"text": "敢", "is_correct": true, "explanation": "正确：「你怎么敢这样对老师说话」是责备对方有胆量这样做，与句意相符。"}, {"text": "肯", "is_correct": false, "explanation": "语义：「肯」表示愿意，句中是在责备对方的胆量，与“愿不愿意”的语义不合。"}, {"text": "愿", "is_correct": false, "explanation": "语域：「愿」是书面用词，口语中不说「你怎么愿这样对老师说话」。"}, {"text": "该", "is_correct": false, "explanation": "搭配：「怎么」后接的情态多为「敢」「能」「会」，不说「你怎么该这样」。"}], "explanations": {"敢": "正确：「你怎么敢这样对老师说话」是责备对方有胆量这样做，与句意相符。", "肯": "语义：「肯」表示愿意，句中是在责备对方的胆量，与“愿不愿意”的语义不合。", "愿": "语域：「愿」是书面用词，口语中不说「你怎么愿这样对老师说话」。", "该": "搭配：「怎么」后接的情态多为「敢」「能」「会」，不说「你怎么该这样」。"}, "sentence_index": 6, "correct_answer": "敢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他敢用英语写信，大家都很佩服他。", "explanation": "这里应该用〈会〉。「敢」表示有胆量去做，用英语写信是能力问题，应用「会」。"}, {"text": "妹妹敢背九九乘法表，三岁就学会了。", "explanation": "这里应该用〈能〉。「敢」表示有胆量去做，背诵是能力问题，应用「能」。"}, {"text": "他敢游泳，三岁就学会了。", "explanation": "这里应该用〈会〉。「敢」表示有胆量去做，游泳是技能，应用「会」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
