INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86482, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门给病人诊断和治疗疾病的机构，设有医生、护士和病房。", "primary_collocate": null, "pronunciation": "yī yuàn", "ipa": "i˥ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这家医院有很多好医生。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王医生在市中心的医院工作。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里有医生、护士和病房。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所医院今年新建了一栋楼。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在医院当护士已经十年了。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院门口有一家小药店。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的急诊室很忙。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院每天都要接待很多病人。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市最大的医院就在河边。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院有内科、外科和儿科。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "所", "label": "量词"}, {"form": "儿童医院", "label": "复合"}, {"form": "醫院", "label": "繁体"}], "register": "中性", "sense_fingerprint": "诊治疾病、设有医生护士病房的医疗机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 内科 (Zipf 3.49), 外科 (Zipf 3.88), 儿科 (Zipf 3.35)']::text[], '4b315749-fffd-4616-ac36-54b6cb1ab5fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86482, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "意愿", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是心愿、愿望。"}, {"text": "医院", "is_correct": true, "explanation": "医院：专门给病人诊断和治疗疾病的机构，设有医生、护士和病房。"}, {"text": "遗愿", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是人在去世前留下的愿望。"}, {"text": "一员", "is_correct": false, "explanation": "yuán（第二声）与 yuàn（第四声）声调不同，意思是团体中的一个成员。"}, {"text": "亿元", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声），yuán（第二声）与 yuàn（第四声）声调都不同，意思是一亿元人民币。"}], "explanations": {"意愿": "yì（第四声）与 yī（第一声）声调不同，意思是心愿、愿望。", "医院": "医院：专门给病人诊断和治疗疾病的机构，设有医生、护士和病房。", "遗愿": "yí（第二声）与 yī（第一声）声调不同，意思是人在去世前留下的愿望。", "一员": "yuán（第二声）与 yuàn（第四声）声调不同，意思是团体中的一个成员。", "亿元": "yì（第四声）与 yī（第一声），yuán（第二声）与 yuàn（第四声）声调都不同，意思是一亿元人民币。"}, "sentence_index": null, "correct_answer": "医院"}, "level_3": {"options": [{"text": "超市", "is_correct": false, "explanation": "语义：超市是卖东西的地方，与“有很多好医生”的语境不相符。"}, {"text": "医院", "is_correct": true, "explanation": "医院：与“有很多好医生”相符，指专门看病的机构，量词“家”可用于医院。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：量词“家”一般不用于学校，学校通常说“所”，“这家学校”不地道。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行办理存取款等业务，与“有很多好医生”无关。"}], "explanations": {"超市": "语义：超市是卖东西的地方，与“有很多好医生”的语境不相符。", "医院": "医院：与“有很多好医生”相符，指专门看病的机构，量词“家”可用于医院。", "学校": "搭配：量词“家”一般不用于学校，学校通常说“所”，“这家学校”不地道。", "银行": "语义：银行办理存取款等业务，与“有很多好医生”无关。"}, "sentence_index": 0, "correct_answer": "医院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车没油了，我去医院加油。", "explanation": "这里应该用〈加油站〉。加油要去加油站，医院不给车加油，不能用来加油。"}, {"text": "我想当医院，帮助病人。", "explanation": "这里应该用〈医生〉。医院是场所，说要当某种职业时要用〈医生〉，不能说“当医院”。"}, {"text": "我把工资存进了医院。", "explanation": "这里应该用〈银行〉。存工资要去银行，医院是看病的地方，不能用来存钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86482, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "议院", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是国家的立法机构，如“参议院”。"}, {"text": "医院", "is_correct": true, "explanation": "医院：专门给病人诊断和治疗疾病的机构，设有医生、护士和病房。"}, {"text": "一元", "is_correct": false, "explanation": "yuán（第二声）与 yuàn（第四声）声调不同，意思是人民币的单位“元”。"}, {"text": "艺员", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声），yuán（第二声）与 yuàn（第四声）声调都不同，意思是从事表演的人。"}], "explanations": {"议院": "yì（第四声）与 yī（第一声）声调不同，意思是国家的立法机构，如“参议院”。", "医院": "医院：专门给病人诊断和治疗疾病的机构，设有医生、护士和病房。", "一元": "yuán（第二声）与 yuàn（第四声）声调不同，意思是人民币的单位“元”。", "艺员": "yì（第四声）与 yī（第一声），yuán（第二声）与 yuàn（第四声）声调都不同，意思是从事表演的人。"}, "sentence_index": null, "correct_answer": "医院"}, "level_3": {"options": [{"text": "花店", "is_correct": false, "explanation": "语义：花店经营鲜花，没有急诊室，与“急诊室很忙”不相符。"}, {"text": "学院", "is_correct": false, "explanation": "语义：学院是教学机构，一般不设急诊室，与“急诊室很忙”不相符。"}, {"text": "医院", "is_correct": true, "explanation": "医院：设有急诊室，与“急诊室很忙”相符。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店经营书籍，没有急诊室，与“急诊室很忙”不相符。"}], "explanations": {"花店": "语义：花店经营鲜花，没有急诊室，与“急诊室很忙”不相符。", "学院": "语义：学院是教学机构，一般不设急诊室，与“急诊室很忙”不相符。", "医院": "医院：设有急诊室，与“急诊室很忙”相符。", "书店": "语义：书店经营书籍，没有急诊室，与“急诊室很忙”不相符。"}, "sentence_index": 6, "correct_answer": "医院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我周末常去医院看电影。", "explanation": "这里应该用〈电影院〉。看电影要去电影院，医院是看病的地方，不能用来看电影。"}, {"text": "我今天要去医院买菜。", "explanation": "这里应该用〈超市〉。买菜要去超市或菜场，医院不卖菜。"}, {"text": "我下午去医院剪头发。", "explanation": "这里应该用〈理发店〉。剪头发要去理发店，医院不提供这项服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天医院做了检查。", "corrected_sentence": "我昨天在医院做了检查。", "error_description": "漏掉了地点介词“在”。“医院”作地点时前面要加“在”，应说“在医院做检查”，不能说“医院做检查”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张医院的护士很耐心。", "corrected_sentence": "这家医院的护士很耐心。", "error_description": "量词用错。“张”用于桌子、纸张等平面或片状的东西，不能修饰医院；医院应用量词“家”或“所”，说“这家医院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86485, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86485, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86485, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "可是用在话的中间，说前面的话和后面的话不一样。", "primary_collocate": null, "pronunciation": "kě shì", "ipa": "kʰɤ˨˩˦ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这件衣服很好看，可是太贵了。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很想去，可是今天没有时间。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会说汉语，可是不会写汉字。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很冷，可是他只穿了一件衬衫。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜看起来不好，可是味道很香。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们等了很久，可是他还没来。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很聪明，可是不太努力。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子不大，可是很干净。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道答案，可是不想说。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想帮忙，可是不知道怎么做。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "用在分句之间，前后两句意思不同的转折连词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b315749-fffd-4616-ac36-54b6cb1ab5fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86485, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "科室", "is_correct": false, "explanation": "kě（第三声）与 kē（第一声）声调不同，意思是医院或机关里按专业划分的部门。"}, {"text": "可是", "is_correct": true, "explanation": "可是：连词，用在前后两句之间，表示转折。"}, {"text": "客室", "is_correct": false, "explanation": "kě（第三声）与 kè（第四声）声调不同，意思是车厢或房间里供乘客、客人使用的空间。"}, {"text": "可数", "is_correct": false, "explanation": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是能够一个一个数出来的。"}, {"text": "可治", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是能够治好的。"}], "explanations": {"科室": "kě（第三声）与 kē（第一声）声调不同，意思是医院或机关里按专业划分的部门。", "可是": "可是：连词，用在前后两句之间，表示转折。", "客室": "kě（第三声）与 kè（第四声）声调不同，意思是车厢或房间里供乘客、客人使用的空间。", "可数": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是能够一个一个数出来的。", "可治": "shì 与 zhì 声母不同（sh 与 zh），意思是能够治好的。"}, "sentence_index": null, "correct_answer": "可是"}, "level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，“太贵”不是“好看”的原因，句子说不通。"}, {"text": "可是", "is_correct": true, "explanation": "可是：“好看”与“太贵”前后意思相反，正好用于转折。"}, {"text": "否则", "is_correct": false, "explanation": "搭配：“否则”前面要有命令或条件，不能接在陈述句“这件衣服很好看”之后。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，“好看”推不出“太贵”，逻辑不通。"}], "explanations": {"因为": "语义：“因为”表示原因，“太贵”不是“好看”的原因，句子说不通。", "可是": "可是：“好看”与“太贵”前后意思相反，正好用于转折。", "否则": "搭配：“否则”前面要有命令或条件，不能接在陈述句“这件衣服很好看”之后。", "所以": "语义：“所以”表示结果，“好看”推不出“太贵”，逻辑不通。"}, "sentence_index": 0, "correct_answer": "可是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很喜欢音乐，可是我也很喜欢跳舞。", "explanation": "这里应该用〈而且〉。两句都是并列补充，没有转折，“可是”不能用。"}, {"text": "他没来，可是他生病了。", "explanation": "这里应该用〈因为〉。表示原因要用“因为”，“可是”只表示转折，不表示原因。"}, {"text": "我先吃了饭，可是去上课了。", "explanation": "这里应该用〈然后〉。前后是先后顺序，没有转折，“可是”不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86485, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "课时", "is_correct": false, "explanation": "kè（第四声）与 kě（第三声）声调不同，shí（第二声）与 shì（第四声）声调也不同，意思是一节课的时间。"}, {"text": "可是", "is_correct": true, "explanation": "可是：连词，用在前后两句之间，表示转折。"}, {"text": "课室", "is_correct": false, "explanation": "kè（第四声）与 kě（第三声）声调不同，意思是教室。"}, {"text": "卡式", "is_correct": false, "explanation": "kǎ（第三声）与 kě（第三声）韵母不同（a 与 e），意思是磁带式的，如卡式录音机。"}], "explanations": {"课时": "kè（第四声）与 kě（第三声）声调不同，shí（第二声）与 shì（第四声）声调也不同，意思是一节课的时间。", "可是": "可是：连词，用在前后两句之间，表示转折。", "课室": "kè（第四声）与 kě（第三声）声调不同，意思是教室。", "卡式": "kǎ（第三声）与 kě（第三声）韵母不同（a 与 e），意思是磁带式的，如卡式录音机。"}, "sentence_index": null, "correct_answer": "可是"}, "level_3": {"options": [{"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示顺承或结果，“很聪明”与“不太努力”之间没有先后或因果关系。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，“很聪明”不能导致“不太努力”，句子不通。"}, {"text": "可是", "is_correct": true, "explanation": "可是：“很聪明”与“不太努力”前后意思相反，用于转折。"}, {"text": "要不然", "is_correct": false, "explanation": "搭配：“要不然”表示选择，前面要有命令或条件，不能接在陈述句“她很聪明”之后。"}], "explanations": {"于是": "语义：“于是”表示顺承或结果，“很聪明”与“不太努力”之间没有先后或因果关系。", "因此": "语义：“因此”表示结果，“很聪明”不能导致“不太努力”，句子不通。", "可是": "可是：“很聪明”与“不太努力”前后意思相反，用于转折。", "要不然": "搭配：“要不然”表示选择，前面要有命令或条件，不能接在陈述句“她很聪明”之后。"}, "sentence_index": 6, "correct_answer": "可是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一边工作，可是一边学习。", "explanation": "这里应该用〈一边……一边……〉。两件事同时进行，是并列关系，没有反差，“可是”用在这里不通。"}, {"text": "我们吃完饭以后，可是去散步了。", "explanation": "这里应该删去〈可是〉。前后是先后顺序，没有反差，“可是”是多余的。"}, {"text": "他不仅会说汉语，可是还会写汉字。", "explanation": "这里应该用〈还〉，与“不仅”搭配表示递进；“可是”只表示转折，不能用在递进结构里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店很近，但是可是东西不便宜。", "corrected_sentence": "这家店很近，可是东西不便宜。", "error_description": "“可是”与“但是”叠用，两个转折连词重复。这里只需保留“可是”，应删去“但是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想去，可是可是没有钱。", "corrected_sentence": "我想去，可是没有钱。", "error_description": "“可是”被重复写成“可是可是”。“可是”只需出现一次，这里应写作“我想去，可是没有钱。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86486, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86486, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86486, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示转折的连词，引出与前面所说相反或有出入的意思。", "primary_collocate": null, "pronunciation": "kě shì", "ipa": "kʰɤ˨˩˦ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他说今天来，可是到现在也没有来。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给他打了电话。可是没有人接。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法很简单，可是没有人想到。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学了三年汉语，可是还不敢开口说。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格便宜，可是质量不太好。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为他生气了。可是他一直在笑。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们很努力，可是结果不太好。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人很有钱，可是过得并不快乐。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪不大，可是懂得很多。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买那本书，可是书店已经关门了。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "引出与前文相反或有出入的内容的转折连词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b315749-fffd-4616-ac36-54b6cb1ab5fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86486, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "客室", "is_correct": false, "explanation": "kě（第三声）与 kè（第四声）声调不同，意思是车厢或房间里供乘客、客人使用的空间。"}, {"text": "科室", "is_correct": false, "explanation": "kě（第三声）与 kē（第一声）声调不同，意思是医院或机关里按专业划分的部门。"}, {"text": "可是", "is_correct": true, "explanation": "可是：连词，表示转折，引出与前面所说相反或有出入的意思。"}, {"text": "可数", "is_correct": false, "explanation": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是能够一个一个数出来的。"}, {"text": "可治", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是能够治好的。"}], "explanations": {"客室": "kě（第三声）与 kè（第四声）声调不同，意思是车厢或房间里供乘客、客人使用的空间。", "科室": "kě（第三声）与 kē（第一声）声调不同，意思是医院或机关里按专业划分的部门。", "可是": "可是：连词，表示转折，引出与前面所说相反或有出入的意思。", "可数": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是能够一个一个数出来的。", "可治": "shì 与 zhì 声母不同（sh 与 zh），意思是能够治好的。"}, "sentence_index": null, "correct_answer": "可是"}, "level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，“到现在也没来”不是“说今天来”的原因。"}, {"text": "可是", "is_correct": true, "explanation": "可是：“说今天来”与“到现在也没有来”前后有出入，用于转折。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示顺承或结果，与前后的反差不符。"}, {"text": "况且", "is_correct": false, "explanation": "语域：“况且”偏书面，且表示追加理由，与这里的转折不合。"}], "explanations": {"因为": "语义：“因为”表示原因，“到现在也没来”不是“说今天来”的原因。", "可是": "可是：“说今天来”与“到现在也没有来”前后有出入，用于转折。", "于是": "语义：“于是”表示顺承或结果，与前后的反差不符。", "况且": "语域：“况且”偏书面，且表示追加理由，与这里的转折不合。"}, "sentence_index": 0, "correct_answer": "可是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他迟到了，可是堵车了。", "explanation": "这里应该用〈因为〉。表示原因要用“因为”，“可是”不表示原因。"}, {"text": "我们先吃了饭，可是去散步了。", "explanation": "这里应该用〈然后〉。前后是先后顺序，没有反差，用“可是”不通。"}, {"text": "如果你来，可是我就去。", "explanation": "这里应该用〈那么〉。“如果”后面引出结果要用“那么”或直接接结果，“可是”表示转折，不能引出结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，“很努力”不能导致“结果不太好”，逻辑不通。"}, {"text": "可是", "is_correct": true, "explanation": "可是：“很努力”与“结果不太好”前后有反差，用于转折。"}, {"text": "否则", "is_correct": false, "explanation": "搭配：“否则”前面要有命令或条件，不能接在“我们很努力”这样的陈述句后面。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，“很努力”推不出“结果不太好”，句子不通。"}], "explanations": {"所以": "语义：“所以”表示结果，“很努力”不能导致“结果不太好”，逻辑不通。", "可是": "可是：“很努力”与“结果不太好”前后有反差，用于转折。", "否则": "搭配：“否则”前面要有命令或条件，不能接在“我们很努力”这样的陈述句后面。", "因此": "语义：“因此”表示结果，“很努力”推不出“结果不太好”，句子不通。"}, "sentence_index": 6, "correct_answer": "可是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很努力，可是很有礼貌。", "explanation": "这里应该用〈并且〉。前后是并列补充，没有转折，“可是”不适用。"}, {"text": "我喜欢看书，可是喜欢运动。", "explanation": "这里应该用〈而且〉。两项爱好是并列关系，没有反差，“可是”用在这里不通。"}, {"text": "为了健康，可是他每天跑步。", "explanation": "这里应该删去〈可是〉。“为了健康”后面直接接主语和动作，表示目的；“可是”只表示转折，前面没有相反的内容，所以不能用在这里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题很难，但是可是他还是做出来了。", "corrected_sentence": "这道题很难，可是他还是做出来了。", "error_description": "“可是”与“但是”叠用，两个转折连词重复。这里只需保留“可是”，应删去“但是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他身体不好，可是可是很喜欢运动。", "corrected_sentence": "他身体不好，可是很喜欢运动。", "error_description": "“可是”重复使用，两个连词叠用。这里只需保留一个“可是”，应删去多余的那个，写作“他身体不好，可是很喜欢运动。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守旧", "is_correct": true, "explanation": "守旧：坚持旧的做法，不肯改变，与「改革」意思相反。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论指交换意见，与「改革」没有反义关系。"}, {"text": "鼓励", "is_correct": false, "explanation": "鼓励指激发或支持，不是「改革」的反义词。"}, {"text": "研究", "is_correct": false, "explanation": "研究指深入探讨，与「改革」不构成反义。"}], "correct_answer": "守旧", "explanations": {"守旧": "守旧：坚持旧的做法，不肯改变，与「改革」意思相反。", "讨论": "讨论指交换意见，与「改革」没有反义关系。", "鼓励": "鼓励指激发或支持，不是「改革」的反义词。", "研究": "研究指深入探讨，与「改革」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守旧", "is_correct": true, "explanation": "守旧：坚持旧的做法，不肯改变，与「改革」意思相反。"}, {"text": "设计", "is_correct": false, "explanation": "设计指规划或绘制图样，与「改革」没有反义关系。"}, {"text": "批准", "is_correct": false, "explanation": "批准指同意，与「改革」不构成反义。"}, {"text": "登记", "is_correct": false, "explanation": "登记指记录备案，与「改革」无关。"}], "correct_answer": "守旧", "explanations": {"守旧": "守旧：坚持旧的做法，不肯改变，与「改革」意思相反。", "设计": "设计指规划或绘制图样，与「改革」没有反义关系。", "批准": "批准指同意，与「改革」不构成反义。", "登记": "登记指记录备案，与「改革」无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改革是把不好的老办法改掉，换成好办法。", "primary_collocate": null, "pronunciation": "gǎi gé", "ipa": "kai˨˩˦ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "学校改革了考试的老办法。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想改革旧的工作方法。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市正在改革公共交通的管理办法。", "target_word": "改革", "complexity_tier": "T3", "furigana": "gǎi gé", "sentence_source": "generated"}, {"text": "他们改革了老办法，大家都很高兴。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板决定改革公司不好的管理办法。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须改革这个不好的排班办法。", "target_word": "改革", "complexity_tier": "T3", "furigana": "gǎi gé", "sentence_source": "generated"}, {"text": "村里改革了种地的老办法，粮食多了。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院改革了看病的办法，病人不用排很长的队。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想把上课的老方式改革一下。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂改革以后，工人的工作轻松多了。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改革了", "label": "体标（了）"}, {"form": "改革过", "label": "体标（过）"}, {"form": "改革者", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把不好的老办法改掉，换成好办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '695a92e4-d454-4f4c-ae8a-bd5477c4b635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改革", "is_correct": true, "explanation": "改革：把不好的老办法改掉，换成好办法，符合「学校改革了考试的老办法」的语境。"}, {"text": "发明", "is_correct": false, "explanation": "语义：「发明」指创造从前没有的东西，「老办法」本来就已存在，不能说发明。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：「参观」的对象是场所或展览，不能带「办法」作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "配价：「吃」的宾语必须是可以吃的东西，「办法」不能被吃。"}], "explanations": {"改革": "改革：把不好的老办法改掉，换成好办法，符合「学校改革了考试的老办法」的语境。", "发明": "语义：「发明」指创造从前没有的东西，「老办法」本来就已存在，不能说发明。", "参观": "搭配：「参观」的对象是场所或展览，不能带「办法」作宾语。", "吃": "配价：「吃」的宾语必须是可以吃的东西，「办法」不能被吃。"}, "sentence_index": 0, "correct_answer": "改革"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个工厂改革了旧的厂房。", "explanation": "这里应该用〈改造〉。改革用于制度、办法，旧厂房这样的建筑要用改造。"}, {"text": "他改革了那个错误的答案。", "explanation": "这里应该用〈改正〉。改革用于制度、办法，错误的答案要用改正。"}, {"text": "他改革了那辆旧自行车。", "explanation": "这里应该用〈修理〉。改革用于制度、办法，自行车这样的物品要用修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改革", "is_correct": true, "explanation": "改革：去掉种地的老办法，换成新办法，粮食因此增多，符合语境。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：「驾驶」的对象是车船，不能带「办法」作宾语。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：「游览」针对风景名胜，不能说游览一种办法。"}, {"text": "喝", "is_correct": false, "explanation": "语义：「喝」只用于饮用液体，「老办法」不能被喝。"}], "explanations": {"改革": "改革：去掉种地的老办法，换成新办法，粮食因此增多，符合语境。", "驾驶": "搭配：「驾驶」的对象是车船，不能带「办法」作宾语。", "游览": "搭配：「游览」针对风景名胜，不能说游览一种办法。", "喝": "语义：「喝」只用于饮用液体，「老办法」不能被喝。"}, "sentence_index": 6, "correct_answer": "改革"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们改革了公司的规模。", "explanation": "这里应该用〈扩大〉。改革用于制度、办法，规模的增加要用扩大。"}, {"text": "他们改革了坏掉的灯泡。", "explanation": "这里应该用〈更换〉。改革用于制度、办法，坏掉的灯泡要用更换。"}, {"text": "他们改革了那场争吵。", "explanation": "这里应该用〈平息〉。改革用于制度、办法，争吵要用平息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校改革了了点名的老办法。", "corrected_sentence": "学校改革了点名的老办法。", "error_description": "动态助词「了」只用一次。这里在「改革」后重复用了两个「了」，说成「改革了了」，语法错误。正确的说法是「学校改革了点名的老办法」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把老办法改革了了。", "corrected_sentence": "他们把老办法改革了。", "error_description": "动态助词「了」在句中只用一次，应说「把老办法改革了」。这里重复用了「了」，说成「改革了了」，语法错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
