INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "相互关联、成组成套的事物。", "primary_collocate": null, "pronunciation": "xì liè", "ipa": "ɕi˥˩ lie˥˩", "syllable_count": 2, "sentences": [{"text": "这个系列的玩具我都买了。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她最喜欢这个系列的小说。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套书是一个系列，一共有八本。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里新来了一个护肤品系列。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系列的第三部电影明天上映。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥把整个系列的画册都收好了。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机公司推出了新系列，价格不贵。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系列有红色、蓝色和白色三种。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他收集了这个系列的所有卡片。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系列的书很适合小学生看。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一系列", "label": "复合"}], "register": "中性", "sense_fingerprint": "成组成套、同一类的产品或作品，如玩具系列、书的系列", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a212e406-1a81-4898-98b4-5a623bfc2f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "系列", "is_correct": true, "explanation": "“这个系列的玩具”指同一系列的玩具，符合语境。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”指住址，不是玩具的类别，不能说“这个地址的玩具”。"}, {"text": "课程", "is_correct": false, "explanation": "语义：“课程”指学习内容，与玩具不是同一类事物。"}, {"text": "信号", "is_correct": false, "explanation": "搭配：“信号”不能用来归类玩具，与“的玩具”不搭。"}], "explanations": {"系列": "“这个系列的玩具”指同一系列的玩具，符合语境。", "地址": "语义：“地址”指住址，不是玩具的类别，不能说“这个地址的玩具”。", "课程": "语义：“课程”指学习内容，与玩具不是同一类事物。", "信号": "搭配：“信号”不能用来归类玩具，与“的玩具”不搭。"}, "sentence_index": 0, "correct_answer": "系列"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "商店里新来了一只护肤品系列。", "explanation": "“系列”不能用量词“只”（“只”多用于动物等），应说“一个系列”。"}, {"text": "商店里新来了一系列问题。", "explanation": "这里的“一系列”指一件接一件的事，与商品不符，属于另一义项。"}, {"text": "商店里新来了一系列售货员。", "explanation": "“系列”多用于事物，不用于人，应说“一批售货员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "系列", "is_correct": true, "explanation": "“新系列”指新推出的一组同类产品，可以标价，符合“价格不贵”。"}, {"text": "理由", "is_correct": false, "explanation": "语义：“理由”指原因，不能有价格，与“价格不贵”不搭。"}, {"text": "句子", "is_correct": false, "explanation": "语义：“句子”是语言单位，不能标价，与“价格不贵”不搭。"}, {"text": "水源", "is_correct": false, "explanation": "搭配：“水源”指水的来源，不能说“价格不贵”。"}], "explanations": {"系列": "“新系列”指新推出的一组同类产品，可以标价，符合“价格不贵”。", "理由": "语义：“理由”指原因，不能有价格，与“价格不贵”不搭。", "句子": "语义：“句子”是语言单位，不能标价，与“价格不贵”不搭。", "水源": "搭配：“水源”指水的来源，不能说“价格不贵”。"}, "sentence_index": 6, "correct_answer": "系列"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台系列的书很适合小学生看。", "explanation": "“台”用于机器等，“系列”不能用“台”，应说“这个系列”。"}, {"text": "这个系列的老师很适合小学生看。", "explanation": "“系列”用于成组的物或事，不用于人，老师不能这样说。"}, {"text": "这一系列的学生很适合小学生看。", "explanation": "“系列”指成组成套的物品或作品，不用于人，应说“一批学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只系列的玩具很受欢迎。", "corrected_sentence": "这个系列的玩具很受欢迎。", "error_description": "“系列”前的量词应用“个”，不能用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了这个系列地书。", "corrected_sentence": "我买了这个系列的书。", "error_description": "“系列”后修饰名词“书”时应用结构助词“的”，不能用“地”（“地”用于修饰动词或形容词）。应说“这个系列的书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
