INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86499, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "竟然是没想到会这样。", "primary_collocate": null, "pronunciation": "jìng rán", "ipa": "tɕiŋ˥˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "他昨天还好好的，今天竟然生病了。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么难的题，他竟然一分钟就做完了。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没想到，你竟然会说上海话。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气这么好，今天竟然下雨了。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她只学了三个月，竟然能看懂中文报纸。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那么大的雨，他竟然没带伞。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我的好朋友，竟然忘了我的生日。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆看起来很小，菜竟然这么好吃。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找了一个小时，钥匙竟然在我的口袋里。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板平时很严，今天竟然让我们早点回家。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "竟然|副词|没想到会这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23a80a73-35d5-4323-a9ea-7981b33b5d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86499, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竟然", "is_correct": true, "explanation": "正确：「竟然」表示没想到，与“昨天还好好的，今天”的转折相符。"}, {"text": "果然", "is_correct": false, "explanation": "语义：「果然」表示与预料相符，句中却是没想到，二者语气相反。"}, {"text": "终于", "is_correct": false, "explanation": "语义：「终于」表示经过等待后才实现，不用于形容突然生病。"}, {"text": "简直", "is_correct": false, "explanation": "搭配：「简直」修饰程度或判断，不修饰“生病”这类动作变化。"}], "explanations": {"竟然": "正确：「竟然」表示没想到，与“昨天还好好的，今天”的转折相符。", "果然": "语义：「果然」表示与预料相符，句中却是没想到，二者语气相反。", "终于": "语义：「终于」表示经过等待后才实现，不用于形容突然生病。", "简直": "搭配：「简直」修饰程度或判断，不修饰“生病”这类动作变化。"}, "sentence_index": 0, "correct_answer": "竟然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早就猜到他会迟到，他竟然迟到了。", "explanation": "这里应该用〈果然〉。前文说「早就猜到」，表示已经预料，与「竟然」表示没想到的语气矛盾。"}, {"text": "我每天晚上都十点睡觉，今天竟然十点睡觉。", "explanation": "这里误用了「竟然」。前文是习惯性的作息，按惯例发生，不是没想到的事，应用〈照常〉表示惯例，「竟然」的语气不符。"}, {"text": "这是我的家，我竟然知道门在哪里。", "explanation": "这里应该用〈当然〉。在自己家里知道门在哪是理所当然的，不是意外，「竟然」不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86499, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竟然", "is_correct": true, "explanation": "正确：「竟然」表示没想到，与“是我的好朋友”的预期形成对比，句意相符。"}, {"text": "只", "is_correct": false, "explanation": "语义：「只」表示限定，句中强调的是意外，「只忘了生日」不合语境。"}, {"text": "当然", "is_correct": false, "explanation": "语义：「当然」表示理所应当，与“好朋友却忘了生日”的意外语气不合。"}, {"text": "一向", "is_correct": false, "explanation": "搭配：「一向」表示长期如此，不与一次性的“忘了生日”搭配。"}], "explanations": {"竟然": "正确：「竟然」表示没想到，与“是我的好朋友”的预期形成对比，句意相符。", "只": "语义：「只」表示限定，句中强调的是意外，「只忘了生日」不合语境。", "当然": "语义：「当然」表示理所应当，与“好朋友却忘了生日”的意外语气不合。", "一向": "搭配：「一向」表示长期如此，不与一次性的“忘了生日”搭配。"}, "sentence_index": 6, "correct_answer": "竟然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每天我照例七点起床，今天竟然七点起床。", "explanation": "这里应该用〈照常〉。每天七点起床是习惯，按惯例发生，不是意外，「竟然」的语气不符。"}, {"text": "他一定会来，这是我们约好的，他竟然会来。", "explanation": "这里应该用〈必定〉。约好的事是预料之中的，表示确定的语气应用「必定」，「竟然」表示意外，语气矛盾。"}, {"text": "他一向很准时，大家都相信他，他竟然一向很准时。", "explanation": "这里不应用「竟然」。「一向」已表示长期一贯，「竟然」表示没想到，语气冲突；删去「竟然」即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86499, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我等了很久，他很竟然没来。", "corrected_sentence": "我等了很久，他竟然没来。", "error_description": "修饰语错误：「竟然」是副词，不能再被「很」修饰，「很竟然」错误，应去掉「很」，说「他竟然没来」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86499, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么晚了，他很竟然还在看书。", "corrected_sentence": "这么晚了，他竟然还在看书。", "error_description": "修饰语错误：「竟然」是副词，不能再被「很」修饰，「很竟然」错误，应去掉「很」，说「竟然还在看书」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
