INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86500, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示出乎意料。", "primary_collocate": null, "pronunciation": "jìng rán", "ipa": "tɕiŋ˥˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "一个五岁的孩子竟然会说三种语言。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我走进房间，竟然看见了多年没见的老同学。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都迟到，今天竟然第一个到了。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么贵的手机，他竟然随便送给了朋友。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她考试前一天没复习，竟然得了第一名。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为他不喜欢吃辣，他竟然点了最辣的菜。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事这么简单，你竟然做错了。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天还很热，今天竟然下雪了。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都十二点了，他竟然还在公司工作。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个地方很远，他竟然走着去了。", "target_word": "竟然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "竟然|副词|表示出乎意料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23a80a73-35d5-4323-a9ea-7981b33b5d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竟然", "is_correct": true, "explanation": "正确：「竟然」表示出乎意料，五岁孩子会说三种语言正是意外之事。"}, {"text": "果然", "is_correct": false, "explanation": "语义：「果然」表示与预料相符，句中说的是出乎意料，二者不合。"}, {"text": "终于", "is_correct": false, "explanation": "语义：「终于」表示经过等待后才实现，句中强调的是意外，而非等待后的达成。"}, {"text": "当然", "is_correct": false, "explanation": "语义：「当然」表示理所应当，与“出乎意料”的语气不合，句中是意外而非应当。"}], "explanations": {"竟然": "正确：「竟然」表示出乎意料，五岁孩子会说三种语言正是意外之事。", "果然": "语义：「果然」表示与预料相符，句中说的是出乎意料，二者不合。", "终于": "语义：「终于」表示经过等待后才实现，句中强调的是意外，而非等待后的达成。", "当然": "语义：「当然」表示理所应当，与“出乎意料”的语气不合，句中是意外而非应当。"}, "sentence_index": 0, "correct_answer": "竟然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一定会来，这是我们约好的，他竟然会来。", "explanation": "这里应该用〈必定〉。约好的事是预料之中的，表示确定的语气应用「必定」，「竟然」表示意外，语气矛盾。"}, {"text": "每天我照例七点起床，今天竟然七点起床。", "explanation": "这里应该用〈照常〉。每天七点起床是习惯，按惯例发生，不是意外，「竟然」的语气不符。"}, {"text": "水在一百度本来就会沸腾，这是常识，水在一百度竟然会沸腾。", "explanation": "这里应该用〈自然〉。沸腾是常识，本来就会发生，不构成意外，「竟然」的语气不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竟然", "is_correct": true, "explanation": "正确：「竟然」表示没想到，与“这件事这么简单”形成对比，句意相符。"}, {"text": "只", "is_correct": false, "explanation": "语义：「只」表示限定，句中强调的是错误，「只做错了」不合语境。"}, {"text": "一向", "is_correct": false, "explanation": "搭配：「一向」表示长期习惯，不与一次性的“做错”搭配。"}, {"text": "当然", "is_correct": false, "explanation": "语义：「当然」表示理所应当，与“这件事很简单却做错了”的意外语气不合。"}], "explanations": {"竟然": "正确：「竟然」表示没想到，与“这件事这么简单”形成对比，句意相符。", "只": "语义：「只」表示限定，句中强调的是错误，「只做错了」不合语境。", "一向": "搭配：「一向」表示长期习惯，不与一次性的“做错”搭配。", "当然": "语义：「当然」表示理所应当，与“这件事很简单却做错了”的意外语气不合。"}, "sentence_index": 6, "correct_answer": "竟然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我早就猜到，他果然迟到了，我竟然没想到。", "explanation": "这里不应用「竟然」。前文说「早就猜到」，「果然」已表示预料，「竟然没想到」与之矛盾；删去「我竟然没想到」即可。"}, {"text": "这是我的家，我当然知道门在哪里，我竟然知道门在哪里。", "explanation": "这里不应用「竟然」。句中「当然」已表示理所应当，「竟然」表示没想到，语气冲突；删去「竟然」即可。"}, {"text": "他一向很准时，大家都相信他，他竟然一向很准时。", "explanation": "这里不应用「竟然」。「一向」已表示长期一贯，「竟然」表示没想到，语气冲突；删去「竟然」即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小学生竟然的解开了那道数学题。", "corrected_sentence": "这个小学生竟然解开了那道数学题。", "error_description": "「竟然」是副词，后面不能加「的」。错误形式是「竟然的」，正确形式是「竟然」，应去掉「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很竟然没来，我很意外。", "corrected_sentence": "他竟然没来，我很意外。", "error_description": "副词语序错误：「竟然」是副词，前面不能再加程度副词「很」。错误形式是「很竟然」，正确形式是「竟然」，应去掉「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
