INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86508, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "股份公司资本的基本单位；股东在公司的份额。", "primary_collocate": null, "pronunciation": "gǔ fèn", "ipa": "ku˨˩˦ fən˥˩", "syllable_count": 2, "sentences": [{"text": "他占这家公司百分之三十的股份。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股东手里的股份越多，话越有分量。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王把一半股份转给了儿子。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的股份由五个股东共同持有。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用存款买了公司的股份。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的股份一直由他们家控制。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新公司的股份，大家按出钱多少来分。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想卖掉自己在公司的股份。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司互相买了对方的股份。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的股份有一半在老板手里。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股份公司", "label": "复合"}, {"form": "股份制", "label": "复合"}], "register": "中性", "sense_fingerprint": "公司资本的基本单位，股东在公司所占的份额", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ff25525-6bcd-420e-aec5-455963bcad4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86508, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "股份", "is_correct": true, "explanation": "正确：股份（gǔ fèn）指公司资本的基本单位和股东所占的份额，这就是听到的词。"}, {"text": "鼓风", "is_correct": false, "explanation": "fēng（第一声）与 fèn（第四声）的韵母和声调都不同，意思是吹风、送风。"}, {"text": "骨粉", "is_correct": false, "explanation": "fěn（第三声）与 fèn（第四声）声调不同，意思是骨头磨成的粉。"}, {"text": "估分", "is_correct": false, "explanation": "gū 与 gǔ、fēn 与 fèn 声调都不同，意思是估计分数。"}, {"text": "古坟", "is_correct": false, "explanation": "gǔ 相同，fén（第二声）与 fèn（第四声）只有声调不同，意思是古代的坟墓。"}], "explanations": {"股份": "正确：股份（gǔ fèn）指公司资本的基本单位和股东所占的份额，这就是听到的词。", "鼓风": "fēng（第一声）与 fèn（第四声）的韵母和声调都不同，意思是吹风、送风。", "骨粉": "fěn（第三声）与 fèn（第四声）声调不同，意思是骨头磨成的粉。", "估分": "gū 与 gǔ、fēn 与 fèn 声调都不同，意思是估计分数。", "古坟": "gǔ 相同，fén（第二声）与 fèn（第四声）只有声调不同，意思是古代的坟墓。"}, "sentence_index": null, "correct_answer": "股份"}, "level_3": {"options": [{"text": "股份", "is_correct": true, "explanation": "正确：“占”后面接的是份额，“百分之三十的股份”指他占有的部分。"}, {"text": "股东", "is_correct": false, "explanation": "搭配：“占”后接的是份额，不能接人“股东”，应说“是……的股东”。"}, {"text": "股息", "is_correct": false, "explanation": "语义：股息是分得的红利，不是可以被“占”的东西，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本与这家公司无关，也不能被“占”百分之三十，句意不通。"}], "explanations": {"股份": "正确：“占”后面接的是份额，“百分之三十的股份”指他占有的部分。", "股东": "搭配：“占”后接的是份额，不能接人“股东”，应说“是……的股东”。", "股息": "语义：股息是分得的红利，不是可以被“占”的东西，句意不通。", "课本": "语义：课本与这家公司无关，也不能被“占”百分之三十，句意不通。"}, "sentence_index": 0, "correct_answer": "股份"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都给办公室的股份浇水。", "explanation": "这里应该用〈花〉。股份是公司资本的份额，不是植物，不能浇水。"}, {"text": "办理这项业务要交股份。", "explanation": "这里应该用〈手续费〉。办理业务交的是钱，股份不能用来缴纳费用。"}, {"text": "股份今天又迟到了。", "explanation": "这里应该用〈他〉。股份是份额，不是人，不能像人一样迟到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c03ac2b-b940-45f2-b535-13a9061ce403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "股份", "is_correct": true, "explanation": "正确：按出钱多少分配的是股份，指各人所占的份额。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资按劳动发放，不按出钱多少分，句意不通。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是交给学校的钱，不按出钱多少来分，句意不通。"}, {"text": "名次", "is_correct": false, "explanation": "搭配：“分”的对象是可以分配的东西，名次不能按出钱多少来分。"}], "explanations": {"股份": "正确：按出钱多少分配的是股份，指各人所占的份额。", "工资": "语义：工资按劳动发放，不按出钱多少分，句意不通。", "学费": "语义：学费是交给学校的钱，不按出钱多少来分，句意不通。", "名次": "搭配：“分”的对象是可以分配的东西，名次不能按出钱多少来分。"}, "sentence_index": 6, "correct_answer": "股份"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月我的股份增加了三公斤。", "explanation": "这里应该用〈体重〉。股份不用公斤计量，也不能说“增加了三公斤”。"}, {"text": "医生治好了股份。", "explanation": "这里应该用〈病人〉。被治好的是人，股份不是人，不能被“治好”。"}, {"text": "他的股份有一米八。", "explanation": "这里应该用〈身高〉。股份没有高度，不能用“一米八”来说明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c03ac2b-b940-45f2-b535-13a9061ce403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想把自己的一套股份转给儿子。", "corrected_sentence": "他想把自己的一部分股份转给儿子。", "error_description": "量词错误：“股份”前不能用“一套”（“套”指成组、成套的东西）。应改为“一部分股份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c03ac2b-b940-45f2-b535-13a9061ce403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老王占了公司百分之二十地股份。", "corrected_sentence": "老王占了公司百分之二十的股份。", "error_description": "结构助词错误：“百分之二十”修饰“股份”时应用“的”，不能用“地”（“地”修饰动词或形容词）。正确：“公司百分之二十的股份”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c03ac2b-b940-45f2-b535-13a9061ce403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
