INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86515, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86515, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "着地是碰到地面。", "primary_collocate": null, "pronunciation": "zhuó dì", "ipa": "ʈʂwo˧˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "跳伞的人慢慢着地了。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "降落时，飞机的轮子先着地。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从自行车上摔下来，脸着地。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨点一着地就不见了。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子从床上掉下来，屁股着地。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体操运动员落下来，双脚稳稳着地。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球一着地，裁判就吹哨了。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫从桌子上跳下，爪子刚着地就跑了。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人滑倒了，手先着地，没有受伤。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从高处跳下时，着地的时候要弯膝盖。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "着地了", "label": "体标（了）"}, {"form": "着地过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "从空中落下后碰到地面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '695a92e4-d454-4f4c-ae8a-bd5477c4b635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86515, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "着地", "is_correct": true, "explanation": "“着地”指从空中落下后碰到地面，与跳伞的语境相符。"}, {"text": "摔碎", "is_correct": false, "explanation": "语义：跳伞的人落地不会被摔碎，与“慢慢”的语境不符。"}, {"text": "咬", "is_correct": false, "explanation": "配价：“咬”是及物动词，后面要有宾语，句中没有宾语。"}, {"text": "沉没", "is_correct": false, "explanation": "搭配：“沉没”多指船只或物体没入水中，不说人慢慢沉没。"}], "explanations": {"着地": "“着地”指从空中落下后碰到地面，与跳伞的语境相符。", "摔碎": "语义：跳伞的人落地不会被摔碎，与“慢慢”的语境不符。", "咬": "配价：“咬”是及物动词，后面要有宾语，句中没有宾语。", "沉没": "搭配：“沉没”多指船只或物体没入水中，不说人慢慢沉没。"}, "sentence_index": 0, "correct_answer": "着地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆公交车在站台着地了。", "explanation": "这里应该用〈停靠〉。公交车停在站点要说停靠，着地只指物体接触地面，不能用于车辆停下。"}, {"text": "飞机在湖面上着地了。", "explanation": "这里应该用〈着水〉。飞机降落在水面要说着水，着地指落在陆地上。"}, {"text": "台风在广东着地了。", "explanation": "这里应该用〈登陆〉。台风从海上到陆地要说登陆，着地只指物体接触地面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86515, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着地", "is_correct": true, "explanation": "“着地”指球落到地面，与“裁判就吹哨了”的比赛语境相符。"}, {"text": "冒烟", "is_correct": false, "explanation": "语义：球落地不会冒烟，与语境不符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：球不会唱歌，与比赛场景不符。"}, {"text": "打开", "is_correct": false, "explanation": "配价：“打开”是及物动词，后面要有宾语，句中没有宾语。"}], "explanations": {"着地": "“着地”指球落到地面，与“裁判就吹哨了”的比赛语境相符。", "冒烟": "语义：球落地不会冒烟，与语境不符。", "唱歌": "语义：球不会唱歌，与比赛场景不符。", "打开": "配价：“打开”是及物动词，后面要有宾语，句中没有宾语。"}, "sentence_index": 6, "correct_answer": "着地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冰箱必须着地，才能保证安全。", "explanation": "这里应该用〈接地〉。冰箱要与大地相连才安全，接地是专门的说法，着地只指落到地上。"}, {"text": "他带球着地为队伍得了分。", "explanation": "这里应该用〈触地〉。橄榄球带球触地得分要说触地，着地不能用于得分。"}, {"text": "这艘货轮终于着地了，大家开始卸货。", "explanation": "这里应该用〈靠岸〉。船只靠到码头要说靠岸，着地只指物体接触地面，货轮不会着地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只狗从台阶上跳下来，前腿先着地了过。", "corrected_sentence": "那只狗从台阶上跳下来，前腿先着地了。", "error_description": "错误在于“了”和“过”不能同时用在“着地”后面，多加了“过”。正确说法是“前腿先着地了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小球一被着地就弹了起来。", "corrected_sentence": "小球一着地就弹了起来。", "error_description": "错误在于“着地”是不及物动词，不能用“被”字句。正确说法是“小球一着地就弹了起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
