INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86521, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "后来是说过了一段时间以后。", "primary_collocate": null, "pronunciation": "hòu lái", "ipa": "xoʊ˥˩ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "起初他很害羞，后来变得爱说话了。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们刚认识时不太熟，后来成了好朋友。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一开始我不喜欢这里，后来慢慢习惯了。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以前住在北京，后来搬到了上海。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开始他不说话，后来才告诉了我。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我怕狗，后来就不怕了。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王二十岁时去了美国，后来在那里工作了。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一开始雨很小，后来越下越大。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前不爱运动，后来每天都跑步。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我本来想去，后来有事没去成。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "后来的", "label": "定语形式"}], "register": "通用", "sense_fingerprint": "后来：说过了一段时间以后，多接在先前情况之后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd8ccd27-d9af-45a9-8d08-de0015174fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86521, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后来", "is_correct": true, "explanation": "后来表示过了一段时间之后，与“起初”前后呼应，符合语境。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”强调持续不变，与“起初…”所表示的变化相矛盾。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示状态没有改变，与“变得爱说话了”的变化不符。"}, {"text": "总是", "is_correct": false, "explanation": "搭配：“总是”表示经常性的习惯，与“起初”这样的一次性变化不搭配。"}], "explanations": {"后来": "后来表示过了一段时间之后，与“起初”前后呼应，符合语境。", "一直": "语义：“一直”强调持续不变，与“起初…”所表示的变化相矛盾。", "仍然": "语义：“仍然”表示状态没有改变，与“变得爱说话了”的变化不符。", "总是": "搭配：“总是”表示经常性的习惯，与“起初”这样的一次性变化不搭配。"}, "sentence_index": 0, "correct_answer": "后来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门一开，他后来就走了进来。", "explanation": "这里应该用〈立刻〉。后来表示过了一段时间，门一开就进来是紧接着发生的，要用“立刻”。"}, {"text": "他后来马上就走了。", "explanation": "这里应该用〈随即〉。后来表示过了一段时间，与“马上”的紧接意思矛盾，紧接着发生要用“随即”。"}, {"text": "我后来明天要努力学习。", "explanation": "这里应该去掉“后来”。“后来”指已过去的某时之后，与“明天”这样的将来时间矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后来", "is_correct": true, "explanation": "后来表示去美国之后的时间，与“工作了”的先后顺序一致，符合语境。"}, {"text": "本来", "is_correct": false, "explanation": "语义：“本来”表示原本的情况，与“去了美国”之后发生的事不符。"}, {"text": "几乎", "is_correct": false, "explanation": "语义：“几乎”表示差一点儿没有发生，与“去了美国”之后已完成的工作相矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示进行中，与“去了美国”这种已完成的事不搭配。"}], "explanations": {"后来": "后来表示去美国之后的时间，与“工作了”的先后顺序一致，符合语境。", "本来": "语义：“本来”表示原本的情况，与“去了美国”之后发生的事不符。", "几乎": "语义：“几乎”表示差一点儿没有发生，与“去了美国”之后已完成的工作相矛盾。", "正在": "搭配：“正在”表示进行中，与“去了美国”这种已完成的事不搭配。"}, "sentence_index": 6, "correct_answer": "后来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我后来在很小的时候很瘦。", "explanation": "这里应该用〈以前〉。后来指某个时间之后，不能用来指“很小的时候”这样更早的时间。"}, {"text": "我后来一开始就很高兴。", "explanation": "这里应该去掉“后来”。“后来”指之后的时间，与表示最初的“一开始”相矛盾。"}, {"text": "他后来是第一个到的。", "explanation": "这里应该用〈首先〉。后来表示之后，不能用于最先发生的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚学汉语时很难，就后来习惯了。", "corrected_sentence": "我刚学汉语时很难，后来习惯了。", "error_description": "副词位置错误：“就”不能放在“后来”之前，应直接说“后来习惯了”，去掉“就”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一开始很紧张，后来的慢慢放松了。", "corrected_sentence": "他一开始很紧张，后来慢慢放松了。", "error_description": "词类形式错误：“后来”是副词，不能加“的”变成定语形式“后来的”，应直接说“后来慢慢放松了”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
