INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86522, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86522, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "指过去某一时间之后的时候，只用于叙述过去的事。", "primary_collocate": null, "pronunciation": "hòu lái", "ipa": "xoʊ˥˩ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "去年春天他生病了，后来一直没上班。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那年我们搬了家，后来再也没见过他。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上大学时我们常见面，后来联系少了。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我十岁那年学游泳，后来就爱上了水。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天上午下着大雨，后来天晴了。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说要来，后来却没有来。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业以后我们去了不同的城市，后来很少见面。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候不懂这件事，后来才明白。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小店早上还开着，后来就关门了。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚到中国时我听不懂，后来慢慢懂了。", "target_word": "后来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "后来的", "label": "定语形式"}], "register": "通用", "sense_fingerprint": "后来：指过去某一时间之后，只能叙述已发生的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd8ccd27-d9af-45a9-8d08-de0015174fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86522, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后来", "is_correct": true, "explanation": "后来指过去某一时间之后，叙述已经发生的事，与“生病了”前后相接，符合语境。"}, {"text": "将要", "is_correct": false, "explanation": "语义：“将要”表示未来，与“去年春天”已发生的事件相矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "搭配：“总是”表示经常性，与“去年春天生病”这一次性事件不搭配。"}, {"text": "本来", "is_correct": false, "explanation": "语义：“本来”表示原本的情况，与“生病了”之后的情形不符。"}], "explanations": {"后来": "后来指过去某一时间之后，叙述已经发生的事，与“生病了”前后相接，符合语境。", "将要": "语义：“将要”表示未来，与“去年春天”已发生的事件相矛盾。", "总是": "搭配：“总是”表示经常性，与“去年春天生病”这一次性事件不搭配。", "本来": "语义：“本来”表示原本的情况，与“生病了”之后的情形不符。"}, "sentence_index": 0, "correct_answer": "后来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "现在我后来在学校工作。", "explanation": "这里应该去掉“后来”。后来只叙述过去的事，不能用来说现在的情况。"}, {"text": "我们后来在三天后出发。", "explanation": "这里应该用〈以后〉。后来指过去某一时间之后，三天后是将来的时间，要用“以后”。"}, {"text": "后来，他明天一直没上班。", "explanation": "这里应该去掉“后来”。后来只叙述过去的事，不能与“明天”这样的将来时间连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后来", "is_correct": true, "explanation": "后来指毕业之后的时间，叙述已经发生的事，与“很少见面”的结果相符。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示进行中，不与“很少见面”这种由过去事件形成的状态搭配。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突发，与“毕业以后”这段较长的时间不相符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示紧接着，与“毕业以后”的时间跨度不符。"}], "explanations": {"后来": "后来指毕业之后的时间，叙述已经发生的事，与“很少见面”的结果相符。", "正在": "搭配：“正在”表示进行中，不与“很少见面”这种由过去事件形成的状态搭配。", "忽然": "语义：“忽然”表示突发，与“毕业以后”这段较长的时间不相符。", "马上": "语义：“马上”表示紧接着，与“毕业以后”的时间跨度不符。"}, "sentence_index": 6, "correct_answer": "后来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我后来小时候住在北京。", "explanation": "这里应该用〈以前〉。后来指某个时间之后，不能用来指更早的“小时候”。"}, {"text": "我们后来首先去了银行。", "explanation": "这里应该去掉“后来”。“首先”表示最先，与“后来”表示之后相矛盾，不能连用。"}, {"text": "我后来刚上小学时不认字。", "explanation": "这里应该用〈最初〉。后来指之后的时间，不能指“刚上小学”这样最早的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去年去了北京，后来的又去了上海。", "corrected_sentence": "我们去年去了北京，后来又去了上海。", "error_description": "词性错误：“后来”是副词，不能加“的”变成定语形式“后来的”；正确为“后来又去了上海”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站原来很热闹，后来了慢慢安静了。", "corrected_sentence": "车站原来很热闹，后来慢慢安静了。", "error_description": "助词错误：副词“后来”后面不能直接加“了”，正确为“后来慢慢安静了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
