INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指办理公务的单位，如政府部门和各种办事机构。", "primary_collocate": null, "pronunciation": "jī guān", "ipa": "tɕi˥ kuan˥", "syllable_count": 2, "sentences": [{"text": "这个城市的机关都在市中心。", "target_word": "机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府是一个重要的机关。", "target_word": "机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机关和企业的工作方式不一样。", "target_word": "机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业后他想到机关当干部。", "target_word": "机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机关的工作人员都要遵守规定。", "target_word": "机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机关负责办理出国手续。", "target_word": "机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个机关都要为老百姓服务。", "target_word": "机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国家机关做了十年的翻译。", "target_word": "机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办理结婚手续的机关就在前面。", "target_word": "机关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机关里的文件都要保存好。", "target_word": "机关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "機關", "label": "繁体"}, {"form": "机关干部", "label": "复合"}], "register": "书面语", "sense_fingerprint": "机关|名词|办理公务的单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23a80a73-35d5-4323-a9ea-7981b33b5d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86526, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机关", "is_correct": true, "explanation": "机关指办公单位，“这个城市的机关”在市中心，语义通顺。"}, {"text": "农田", "is_correct": false, "explanation": "语义：农田多在郊外，不会都集中在市中心。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地不设在市中心，与“都在市中心”的语境冲突。"}, {"text": "桃源", "is_correct": false, "explanation": "语域：桃源是文学词，指理想中的隐居之地，与城市规划的语境不合。"}], "explanations": {"机关": "机关指办公单位，“这个城市的机关”在市中心，语义通顺。", "农田": "语义：农田多在郊外，不会都集中在市中心。", "墓地": "语义：墓地不设在市中心，与“都在市中心”的语境冲突。", "桃源": "语域：桃源是文学词，指理想中的隐居之地，与城市规划的语境不合。"}, "sentence_index": 0, "correct_answer": "机关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在一所机关读书，每天学习到很晚。", "explanation": "这里应该用〈学校〉。机关是办理公务的单位，不用于读书，学习的地方要说学校。"}, {"text": "他在销售机关工作，负责联系客户。", "explanation": "这里应该用〈部门〉。机关是办理公务的单位，企业里的销售部门不是机关。"}, {"text": "这家机关每天生产几千双鞋。", "explanation": "这里应该用〈工厂〉。机关是办理公务的单位，不生产产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机关", "is_correct": true, "explanation": "机关指办公单位，“各个机关为老百姓服务”语义通顺。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人不会为老百姓服务，与句意冲突。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有行为能力，不能为老百姓服务。"}, {"text": "蓬门", "is_correct": false, "explanation": "语域：蓬门是文言词，指简陋的门户，与现代公务语境不合。"}], "explanations": {"机关": "机关指办公单位，“各个机关为老百姓服务”语义通顺。", "敌人": "语义：敌人不会为老百姓服务，与句意冲突。", "石头": "语义：石头没有行为能力，不能为老百姓服务。", "蓬门": "语域：蓬门是文言词，指简陋的门户，与现代公务语境不合。"}, "sentence_index": 6, "correct_answer": "机关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家机关的烤鸭很有名，很多人慕名来吃。", "explanation": "这里应该用〈饭店〉。机关是办公单位，不对外营业，不会以烤鸭出名。"}, {"text": "这座机关里收藏了很多古董，每天都有很多游客。", "explanation": "这里应该用〈博物馆〉。机关是办公单位，不收藏展品供游客参观。"}, {"text": "他每天早上在一个机关排队买车票。", "explanation": "这里应该用〈车站〉。机关是办公单位，不卖车票，买车票要去车站。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的哥哥机关工作。", "corrected_sentence": "他的哥哥在机关工作。", "error_description": "介词缺失：表示工作地点要用“在”引出处所，“机关工作”应改为“在机关工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姑姑在一名机关工作。", "corrected_sentence": "我姑姑在一个机关工作。", "error_description": "量词错误：「名」用于人，「机关」是单位，应用量词「个」。错误形式是「一名机关」，正确形式是「一个机关」，应改为「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
