INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86529, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生是小宝宝从妈妈的肚子里出来。", "primary_collocate": null, "pronunciation": "shēng", "ipa": "ʂɤŋ˥", "syllable_count": 1, "sentences": [{"text": "她昨天在医院生了一个女儿。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈在北京生了我。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐想生两个孩子。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚三年，还没有生孩子。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生了一个很可爱的男孩。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王太太今年生了双胞胎。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我奶奶一共生了五个孩子。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她三十岁才生第一个孩子。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说她下个月就要生了。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥的妻子刚生完孩子，还在休息。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生了", "label": "体标"}, {"form": "生过", "label": "体标"}], "register": "中性", "sense_fingerprint": "生|动词|小宝宝从妈妈肚子里出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23a80a73-35d5-4323-a9ea-7981b33b5d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86529, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生", "is_correct": true, "explanation": "“生”是本词，shēng，指小宝宝从妈妈肚子里出来。"}, {"text": "身", "is_correct": false, "explanation": "身 shēn（第一声）与 shēng 韵母不同（-en／-eng），意思是身体。"}, {"text": "深", "is_correct": false, "explanation": "深 shēn 与 shēng 韵母不同（-en／-eng），意思是深浅的深。"}, {"text": "伤", "is_correct": false, "explanation": "伤 shāng 与 shēng 韵母不同（-ang／-eng），意思是受伤。"}, {"text": "省", "is_correct": false, "explanation": "省 shěng（第三声）与 shēng（第一声）声调不同，意思是省份。"}], "explanations": {"生": "“生”是本词，shēng，指小宝宝从妈妈肚子里出来。", "身": "身 shēn（第一声）与 shēng 韵母不同（-en／-eng），意思是身体。", "深": "深 shēn 与 shēng 韵母不同（-en／-eng），意思是深浅的深。", "伤": "伤 shāng 与 shēng 韵母不同（-ang／-eng），意思是受伤。", "省": "省 shěng（第三声）与 shēng（第一声）声调不同，意思是省份。"}, "sentence_index": null, "correct_answer": "生"}, "level_3": {"options": [{"text": "生", "is_correct": true, "explanation": "“生”指分娩，与“昨天在医院”“一个女儿”相符。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“一个女儿”作宾语。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指赠送或送走，不指分娩，与句意冲突。"}, {"text": "养", "is_correct": false, "explanation": "语义：“养”指抚养，不指分娩，与“在医院”的语境不合。"}], "explanations": {"生": "“生”指分娩，与“昨天在医院”“一个女儿”相符。", "哭": "配价：“哭”是不及物动词，不能带“一个女儿”作宾语。", "送": "语义：“送”指赠送或送走，不指分娩，与句意冲突。", "养": "语义：“养”指抚养，不指分娩，与“在医院”的语境不合。"}, "sentence_index": 0, "correct_answer": "生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她生了三个月的身孕。", "explanation": "这里应该用〈怀〉。孕期要说“怀孕”或“怀了身孕”，“生”指分娩。"}, {"text": "她每天在家生孩子，很辛苦。", "explanation": "这里应该用〈带〉。“生孩子”指分娩，每天在家照顾孩子要用“带孩子”。"}, {"text": "他生了一家新公司。", "explanation": "这里应该用〈成立〉。“生”指生育，不指创办企业，应说“成立”一家新公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86529, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生", "is_correct": true, "explanation": "“生”是本词，shēng，指小宝宝从妈妈肚子里出来。"}, {"text": "绳", "is_correct": false, "explanation": "绳 shéng（第二声）与 shēng（第一声）声调不同，意思是绳子。"}, {"text": "胜", "is_correct": false, "explanation": "胜 shèng（第四声）与 shēng（第一声）声调不同，意思是胜利。"}, {"text": "剩", "is_correct": false, "explanation": "剩 shèng（第四声）与 shēng（第一声）声调不同，意思是剩下。"}], "explanations": {"生": "“生”是本词，shēng，指小宝宝从妈妈肚子里出来。", "绳": "绳 shéng（第二声）与 shēng（第一声）声调不同，意思是绳子。", "胜": "胜 shèng（第四声）与 shēng（第一声）声调不同，意思是胜利。", "剩": "剩 shèng（第四声）与 shēng（第一声）声调不同，意思是剩下。"}, "sentence_index": null, "correct_answer": "生"}, "level_3": {"options": [{"text": "生", "is_correct": true, "explanation": "“生”指分娩，与“一共”“五个孩子”相符。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”指出售，把孩子卖掉与“生”的语境完全相反。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带“五个孩子”作宾语。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬，与“一共”“孩子”的语境不合。"}], "explanations": {"生": "“生”指分娩，与“一共”“五个孩子”相符。", "卖": "语义：“卖”指出售，把孩子卖掉与“生”的语境完全相反。", "笑": "配价：“笑”是不及物动词，不能带“五个孩子”作宾语。", "咬": "语义：“咬”指用牙齿咬，与“一共”“孩子”的语境不合。"}, "sentence_index": 6, "correct_answer": "生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这对夫妇生了一个别人家的孩子。", "explanation": "这里应该用〈收养〉。“生”指亲生，领养别人家的孩子要用“收养”。"}, {"text": "这台机器每天生一千个零件，效率很高。", "explanation": "这里应该用〈生产〉。“生”指生育或生出幼崽，机器制造零件要说“生产”。"}, {"text": "这个小镇去年生了一座大桥。", "explanation": "这里应该用〈建〉。“生”指生育，不指建造，修建大桥要说“建”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86529, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "舅妈去年冬天在老家了生一个儿子。", "corrected_sentence": "舅妈去年冬天在老家生了一个儿子。", "error_description": "体标位置错误：“了”是动词后的体标，应说“生了一个儿子”，不能放在“生”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86529, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我嫂子去年冬天下生了一个女儿。", "corrected_sentence": "我嫂子去年冬天生下了一个女儿。", "error_description": "补语位置错误：应为“生下”（动词加结果补语“下”，表示生出来）；“下生”在现代汉语中不用于普通分娩，多见于佛教等文言用语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
