INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86530, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生育；生出孩子、幼崽或蛋；也指出生。", "primary_collocate": null, "pronunciation": "shēng", "ipa": "ʂɤŋ˥", "syllable_count": 1, "sentences": [{"text": "我家的猫生了四只小猫。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只母鸡每天生一个蛋。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母狗昨晚生了三只小狗。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大熊猫很少一次生两个宝宝。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子一年能生好几次。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头牛春天生了一只小牛。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母鸡生蛋以后，会叫个不停。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生过三个孩子，很有经验。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生在北京，长在上海。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生下一个健康的男孩。", "target_word": "生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生了", "label": "体标"}, {"form": "生过", "label": "体标"}], "register": "中性", "sense_fingerprint": "生|动词|生育、生出孩子幼崽或蛋、出生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 母狗 (Zipf 3.83), 三只 (Zipf 3.5), 小狗 (Zipf 3.89)']::text[], '23a80a73-35d5-4323-a9ea-7981b33b5d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86530, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生", "is_correct": true, "explanation": "“生”是本词，shēng，指动物生出幼崽。"}, {"text": "身", "is_correct": false, "explanation": "身 shēn（第一声）与 shēng 韵母不同（-en／-eng），意思是身体。"}, {"text": "伤", "is_correct": false, "explanation": "伤 shāng 与 shēng 韵母不同（-ang／-eng），意思是受伤。"}, {"text": "省", "is_correct": false, "explanation": "省 shěng（第三声）与 shēng（第一声）声调不同，意思是省份。"}], "explanations": {"生": "“生”是本词，shēng，指动物生出幼崽。", "身": "身 shēn（第一声）与 shēng 韵母不同（-en／-eng），意思是身体。", "伤": "伤 shāng 与 shēng 韵母不同（-ang／-eng），意思是受伤。", "省": "省 shěng（第三声）与 shēng（第一声）声调不同，意思是省份。"}, "sentence_index": null, "correct_answer": "生"}, "level_3": {"options": [{"text": "生", "is_correct": true, "explanation": "“生”指动物生育，与“我家的猫”“四只小猫”相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语应是歌曲，不能说“唱小猫”。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的宾语应是字或文章，不能用于小猫。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指赠送，猫不会把自己的小猫送出去，与句意冲突。"}], "explanations": {"生": "“生”指动物生育，与“我家的猫”“四只小猫”相符。", "唱": "搭配：“唱”的宾语应是歌曲，不能说“唱小猫”。", "写": "搭配：“写”的宾语应是字或文章，不能用于小猫。", "送": "语义：“送”指赠送，猫不会把自己的小猫送出去，与句意冲突。"}, "sentence_index": 0, "correct_answer": "生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂每天生三千台电视机。", "explanation": "这里应该用〈生产〉。“生”指生育或生出幼崽，工厂制造产品要说“生产”。"}, {"text": "我在市场上生了一只小狗。", "explanation": "这里应该用〈买〉。“生”指生出幼崽，不指购买，买小狗要说“买”。"}, {"text": "她把两个孩子生大了。", "explanation": "这里应该用〈养〉。“生”指生出，不指抚养长大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86530, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生", "is_correct": true, "explanation": "“生”是本词，shēng，指动物生出幼崽。"}, {"text": "深", "is_correct": false, "explanation": "深 shēn 与 shēng 韵母不同（-en／-eng），意思是深浅的深。"}, {"text": "绳", "is_correct": false, "explanation": "绳 shéng（第二声）与 shēng（第一声）声调不同，意思是绳子。"}, {"text": "剩", "is_correct": false, "explanation": "剩 shèng（第四声）与 shēng（第一声）声调不同，意思是剩下。"}], "explanations": {"生": "“生”是本词，shēng，指动物生出幼崽。", "深": "深 shēn 与 shēng 韵母不同（-en／-eng），意思是深浅的深。", "绳": "绳 shéng（第二声）与 shēng（第一声）声调不同，意思是绳子。", "剩": "剩 shèng（第四声）与 shēng（第一声）声调不同，意思是剩下。"}, "sentence_index": null, "correct_answer": "生"}, "level_3": {"options": [{"text": "生", "is_correct": true, "explanation": "“生”指动物生育，与“母鸡”“蛋”“叫个不停”的语境相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”需要人去加工食物，母鸡不会煮蛋。"}, {"text": "绣", "is_correct": false, "explanation": "搭配：“绣”的对象是布料，不能与“蛋”搭配。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”的对象是毛线或布料，不能说“织蛋”。"}], "explanations": {"生": "“生”指动物生育，与“母鸡”“蛋”“叫个不停”的语境相符。", "煮": "语义：“煮”需要人去加工食物，母鸡不会煮蛋。", "绣": "搭配：“绣”的对象是布料，不能与“蛋”搭配。", "织": "搭配：“织”的对象是毛线或布料，不能说“织蛋”。"}, "sentence_index": 6, "correct_answer": "生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他生了一只流浪猫。", "explanation": "这里应该用〈收养〉。“生”指生出幼崽，人领养流浪动物要用“收养”。"}, {"text": "农民在地里生了很多玉米。", "explanation": "这里应该用〈种〉。“生”指生出幼崽或孩子，种植农作物要说“种”。"}, {"text": "他生了一封信给妈妈。", "explanation": "这里应该用〈写〉。“生”指生育，不指写信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只母羊去年春天出生了两只羊羔。", "corrected_sentence": "那只母羊去年春天生出了两只羊羔。", "error_description": "及物性错误：“出生”是不及物动词，表示自己降生，不能带宾语“羊羔”；应说“生出了两只羊羔”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这头母牛去年夏天生着一头小牛。", "corrected_sentence": "这头母牛去年夏天生了一头小牛。", "error_description": "体标错误：“生”指已完成的分娩，应用“了”；“着”表示持续状态，与此句不符。应改为“生了一头小牛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
