INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86547, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "局是下棋或比赛的一场。", "primary_collocate": null, "pronunciation": "jú", "ipa": "tɕy˧˥", "syllable_count": 1, "sentences": [{"text": "我和爷爷下了一局棋。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛一共打三局。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一局就赢了对手。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们再来一局，好不好？", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛分五局，谁先赢三局谁就是冠军。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这局棋下了两个小时。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我连输了两局。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后一局，他打得特别好。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想和我再下一局象棋。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一局棋还没下完，天就黑了。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "量词：下棋或比赛的一场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '695a92e4-d454-4f4c-ae8a-bd5477c4b635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86547, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "局", "is_correct": true, "explanation": "局 jú（第二声）：下棋或比赛的一场。"}, {"text": "居", "is_correct": false, "explanation": "jū（第一声）与 jú（第二声）声调不同，意思是居住。"}, {"text": "举", "is_correct": false, "explanation": "jǔ（第三声）与 jú（第二声）声调不同，意思是抬起。"}, {"text": "句", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是句子。"}, {"text": "巨", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是巨大。"}], "explanations": {"局": "局 jú（第二声）：下棋或比赛的一场。", "居": "jū（第一声）与 jú（第二声）声调不同，意思是居住。", "举": "jǔ（第三声）与 jú（第二声）声调不同，意思是抬起。", "句": "jù（第四声）与 jú（第二声）声调不同，意思是句子。", "巨": "jù（第四声）与 jú（第二声）声调不同，意思是巨大。"}, "sentence_index": null, "correct_answer": "局"}, "level_3": {"options": [{"text": "局", "is_correct": true, "explanation": "局：量词，计算下棋的一个回合，“一局棋”指一次完整的对局。"}, {"text": "件", "is_correct": false, "explanation": "搭配：“件”用于衣服、事情等，不能用来计算一次下棋。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于纸、桌子等平面的东西，不能说“一张棋”。"}, {"text": "首", "is_correct": false, "explanation": "语义：“首”用于诗歌、歌曲，与下棋无关。"}], "explanations": {"局": "局：量词，计算下棋的一个回合，“一局棋”指一次完整的对局。", "件": "搭配：“件”用于衣服、事情等，不能用来计算一次下棋。", "张": "搭配：“张”用于纸、桌子等平面的东西，不能说“一张棋”。", "首": "语义：“首”用于诗歌、歌曲，与下棋无关。"}, "sentence_index": 0, "correct_answer": "局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天看了一局电影。", "explanation": "这里应该用〈场〉。局只用于下棋、比赛中的一个回合，看电影要用场。"}, {"text": "我昨天买了一局书。", "explanation": "这里应该用〈本〉。局是计算棋局或比赛回合的量词，书要用本来计算。"}, {"text": "我昨天听了一局歌。", "explanation": "这里应该用〈首〉。局是计算棋局或比赛回合的量词，歌要用首来计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86547, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "局", "is_correct": true, "explanation": "局 jú（第二声）：下棋或比赛的一场。"}, {"text": "剧", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是戏剧。"}, {"text": "聚", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是聚集。"}, {"text": "具", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是工具。"}, {"text": "拒", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是拒绝。"}, {"text": "据", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是根据。"}], "explanations": {"局": "局 jú（第二声）：下棋或比赛的一场。", "剧": "jù（第四声）与 jú（第二声）声调不同，意思是戏剧。", "聚": "jù（第四声）与 jú（第二声）声调不同，意思是聚集。", "具": "jù（第四声）与 jú（第二声）声调不同，意思是工具。", "拒": "jù（第四声）与 jú（第二声）声调不同，意思是拒绝。", "据": "jù（第四声）与 jú（第二声）声调不同，意思是根据。"}, "sentence_index": null, "correct_answer": "局"}, "level_3": {"options": [{"text": "局", "is_correct": true, "explanation": "局：量词，计算比赛中的一个回合，“两局”指两个回合。"}, {"text": "幅", "is_correct": false, "explanation": "语义：“幅”用于字画、布匹，与比赛的输赢无关。"}, {"text": "份", "is_correct": false, "explanation": "搭配：“份”多用于饭菜、报纸，不能计算比赛的输赢。"}, {"text": "副", "is_correct": false, "explanation": "搭配：“副”用于成对或成套的东西，如眼镜、手套，不能用于输赢。"}], "explanations": {"局": "局：量词，计算比赛中的一个回合，“两局”指两个回合。", "幅": "语义：“幅”用于字画、布匹，与比赛的输赢无关。", "份": "搭配：“份”多用于饭菜、报纸，不能计算比赛的输赢。", "副": "搭配：“副”用于成对或成套的东西，如眼镜、手套，不能用于输赢。"}, "sentence_index": 6, "correct_answer": "局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "街上的局很热闹。", "explanation": "这里应该用〈场面〉。局指比赛的一场或机关部门，描述热闹的场面要用场面。"}, {"text": "他在一台局工作了二十年。", "explanation": "这里应该用〈个〉。台用于机器、电器，机关部门要用个来计算。"}, {"text": "他在一条局工作了二十年。", "explanation": "这里应该用〈个〉。条用于长的东西，如河流、裤子，机关部门要用个来计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLU