INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们昨天喝了一局茶。", "corrected_sentence": "我们昨天喝了一杯茶。", "error_description": "量词错误：「局」只用于下棋或比赛中的一个回合，计量茶要用「杯」。应说「喝了一杯茶」，这里误用「局」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们下完局棋再回家吧。", "corrected_sentence": "我们下完一局棋再回家吧。", "error_description": "数量错误：“局”不能裸用，前面须有数词（如“一局”）或“这／那／每”等限定词。“下完局棋”应补上数词，正确说法是“下完一局棋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86549, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以后", "is_correct": true, "explanation": "正确。“以前”指过去，“以后”指将来，两者是时间上的反义词。"}, {"text": "白天", "is_correct": false, "explanation": "与“以前”没有反义关系，“白天”指白昼的时段。"}, {"text": "今天", "is_correct": false, "explanation": "与“以前”没有反义关系，“今天”指当天。"}, {"text": "春天", "is_correct": false, "explanation": "与“以前”没有反义关系，“春天”指一年中的季节。"}], "correct_answer": "以后", "explanations": {"以后": "正确。“以前”指过去，“以后”指将来，两者是时间上的反义词。", "白天": "与“以前”没有反义关系，“白天”指白昼的时段。", "今天": "与“以前”没有反义关系，“今天”指当天。", "春天": "与“以前”没有反义关系，“春天”指一年中的季节。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
