INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86549, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以前是现在过去了的时候。", "primary_collocate": null, "pronunciation": "yǐ qián", "ipa": "i˨˩ t͡ɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "以前我家很小，现在大了。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前是我的同学。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里以前没有地铁。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前我不喜欢喝茶。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你以前去过那个公园吗？", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前的事，我都忘了。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶以前常给我讲故事。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以前不会游泳，现在会了。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前这条路很窄。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们以前见过面，你还记得吗？", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "单用，指现在以前的过去时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c51f155-0521-4e71-90b5-132e48d69207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86549, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以后", "is_correct": false, "explanation": "语义：「以后」指将来，与“现在大了”的对比相冲突，句意不通。"}, {"text": "以前", "is_correct": true, "explanation": "正确。「以前」指过去的时期，与“现在大了”形成对比。"}, {"text": "明天", "is_correct": false, "explanation": "语义：「明天」指次日，不能与“现在大了”构成过去的对比。"}, {"text": "未来", "is_correct": false, "explanation": "语义：「未来」指将来，而句子说的是过去的家，与“现在大了”的对比不符。"}], "explanations": {"以后": "语义：「以后」指将来，与“现在大了”的对比相冲突，句意不通。", "以前": "正确。「以前」指过去的时期，与“现在大了”形成对比。", "明天": "语义：「明天」指次日，不能与“现在大了”构成过去的对比。", "未来": "语义：「未来」指将来，而句子说的是过去的家，与“现在大了”的对比不符。"}, "sentence_index": 0, "correct_answer": "以前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我以前明年要去北京。", "explanation": "这里应该用〈以后〉。「以前」指过去，与表示将来的“明年”矛盾。"}, {"text": "我以前后天要去北京。", "explanation": "“以前”只指过去，不能与“后天”这样的将来时间搭配，此处应用〈将来〉。"}, {"text": "我们以前明天见面吧。", "explanation": "“以前”指过去，与“明天见面”的将来时间矛盾，此处应用〈将来〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86549, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昨天", "is_correct": false, "explanation": "语义：「昨天」指一天，不能与表示经常的“常”搭配，句意不通。"}, {"text": "以前", "is_correct": true, "explanation": "正确。「奶奶以前常给我讲故事」指过去的一段时期，与“常”相合。"}, {"text": "今天", "is_correct": false, "explanation": "语义：「今天」指当天，不能与“常”构成经常发生的时间，句意不通。"}, {"text": "刚才", "is_correct": false, "explanation": "搭配：「刚才」指刚过去的时点，不与表示经常的“常”搭配。"}], "explanations": {"昨天": "语义：「昨天」指一天，不能与表示经常的“常”搭配，句意不通。", "以前": "正确。「奶奶以前常给我讲故事」指过去的一段时期，与“常”相合。", "今天": "语义：「今天」指当天，不能与“常”构成经常发生的时间，句意不通。", "刚才": "搭配：「刚才」指刚过去的时点，不与表示经常的“常”搭配。"}, "sentence_index": 6, "correct_answer": "以前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们将来以前见过面，你还记得吗？", "explanation": "“以前”指过去，与“将来”矛盾，此处应去掉“将来”。"}, {"text": "我们以前马上就要见面，你还记得吗？", "explanation": "“以前”指过去，与“马上就要”的近将来矛盾，此处应去掉“以前”。"}, {"text": "我们以前后天要见面，你还记得吗？", "explanation": "“以前”指过去，与“后天要”的将来时间矛盾，此处应去掉“以前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86549, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前的学过法语。", "corrected_sentence": "我以前学过法语。", "error_description": "“以前”后面多加了“的”，变成“以前的学过法语”，不通。“以前”在句中作时间状语，直接放在动词前，应说“我以前学过法语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86549, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前了住在北京。", "corrected_sentence": "我们以前住在北京。", "error_description": "“了”不能放在“以前”和动词之间。错误形式“以前了住”不通，正确形式为“以前住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86550, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以后", "is_correct": true, "explanation": "正确。“以前”指某时之前，“以后”指某时之后，两者是时间上的反义词。"}, {"text": "白天", "is_correct": false, "explanation": "与“以前”没有反义关系，“白天”指白昼的时段。"}, {"text": "今天", "is_correct": false, "explanation": "与“以前”没有反义关系，“今天”指当天。"}, {"text": "春天", "is_correct": false, "explanation": "与“以前”没有反义关系，“春天”指一年中的季节。"}], "correct_answer": "以后", "explanations": {"以后": "正确。“以前”指某时之前，“以后”指某时之后，两者是时间上的反义词。", "白天": "与“以前”没有反义关系，“白天”指白昼的时段。", "今天": "与“以前”没有反义关系，“今天”指当天。", "春天": "与“以前”没有反义关系，“春天”指一年中的季节。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86550, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以后", "is_correct": true, "explanation": "正确。“以前”指某时之前，“以后”指某时之后，两者是时间上的反义词。"}, {"text": "上午", "is_correct": false, "explanation": "与“以前”没有反义关系，“上午”指中午以前的时段。"}, {"text": "夏天", "is_correct": false, "explanation": "与“以前”没有反义关系，“夏天”指一年中的季节。"}, {"text": "下午", "is_correct": false, "explanation": "与“以前”没有反义关系，“下午”指中午以后的时段。"}], "correct_answer": "以后", "explanations": {"以后": "正确。“以前”指某时之前，“以后”指某时之后，两者是时间上的反义词。", "上午": "与“以前”没有反义关系，“上午”指中午以前的时段。", "夏天": "与“以前”没有反义关系，“夏天”指一年中的季节。", "下午": "与“以前”没有反义关系，“下午”指中午以后的时段。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指现在或某一时间之前的时期。", "primary_collocate": null, "pronunciation": "yǐ qián", "ipa": "i˨˩ t͡ɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "十点以前，请你回家。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来中国以前，我学过一年汉语。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三年以前，他还在北京工作。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭以前，要先洗手。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以前，我每天都复习。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五年以前，这里是一片田地。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课以前，老师不让我们走。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉以前，他喜欢听音乐。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期五以前，请把作业交给我。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年以前，我们住在同一个城市。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "接在时间或动作后面，指某一时间之前的时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c51f155-0521-4e71-90b5-132e48d69207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以外", "is_correct": false, "explanation": "语义：「以外」表示范围之外，不指时间的先后，“十点以外”句意不通。"}, {"text": "以前", "is_correct": true, "explanation": "正确。「十点以前」指十点之前的时期，与“请你回家”相合。"}, {"text": "以下", "is_correct": false, "explanation": "语义：「以下」多指数量或等级，不用于时间点，“十点以下”句意不通。"}, {"text": "以南", "is_correct": false, "explanation": "搭配：「以南」是方位词，不接在时间后面，“十点以南”不通。"}], "explanations": {"以外": "语义：「以外」表示范围之外，不指时间的先后，“十点以外”句意不通。", "以前": "正确。「十点以前」指十点之前的时期，与“请你回家”相合。", "以下": "语义：「以下」多指数量或等级，不用于时间点，“十点以下”句意不通。", "以南": "搭配：「以南」是方位词，不接在时间后面，“十点以南”不通。"}, "sentence_index": 0, "correct_answer": "以前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试以前，我已经考完了。", "explanation": "这里应用〈以后〉。“考试以前”指考试之前，“已经考完了”说明考试已经结束，时间矛盾。"}, {"text": "吃饭以前已经吃饱了，要先洗手。", "explanation": "这里应用〈以后〉。“吃饭以前”指吃饭之前，“已经吃饱了”说明已经吃过，时间不符。"}, {"text": "这个会议以前，他已经讲完了。", "explanation": "这里应用〈以后〉。“以前”指某一时间之前，“已经讲完了”与会议之前的时间矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以北", "is_correct": false, "explanation": "语义：「以北」是方位，不指时间的先后，“下课以北”句意不通。"}, {"text": "以东", "is_correct": false, "explanation": "搭配：「以东」是方位词，不接在动作后面表示时间，“下课以东”不通。"}, {"text": "以前", "is_correct": true, "explanation": "正确。「下课以前」指下课之前的时期，与“老师不让我们走”相合。"}, {"text": "以西", "is_correct": false, "explanation": "语义：「以西」是方位，不指时间的先后，“下课以西”句意不通。"}], "explanations": {"以北": "语义：「以北」是方位，不指时间的先后，“下课以北”句意不通。", "以东": "搭配：「以东」是方位词，不接在动作后面表示时间，“下课以东”不通。", "以前": "正确。「下课以前」指下课之前的时期，与“老师不让我们走”相合。", "以西": "语义：「以西」是方位，不指时间的先后，“下课以西”句意不通。"}, "sentence_index": 6, "correct_answer": "以前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "十年以前，我们会在同一个城市见面。", "explanation": "“以前”指过去，与“会”表示的将来矛盾，时间不一致。"}, {"text": "十年以前，我们明天住在同一个城市。", "explanation": "“以前”指过去，与“明天”表示的将来矛盾，此处应用〈将来〉。"}, {"text": "十年以前，我们将来住在同一个城市。", "explanation": "“以前”指过去，与“将来”矛盾，此处应用〈将来〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上课的以前，他要先准备。", "corrected_sentence": "上课以前，他要先准备。", "error_description": "“以前”前面不能直接用“的”接动词短语，“上课的以前”不通，应说“上课以前”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个小时的以前，他离开了。", "corrected_sentence": "两个小时以前，他离开了。", "error_description": "“以前”前面不能直接用“的”接数量词短语，“两个小时的以前”不通，应说“两个小时以前”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
