INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86555, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示一个一个分开地做。", "primary_collocate": null, "pronunciation": "fēn bié", "ipa": "fən˥ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "我和姐姐分别去了两个城市。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师分别问了三个学生。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分别坐飞机和火车来。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们分别给爸爸妈妈打了电话。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们分别走进了考场。", "target_word": "分别", "complexity_tier": "T3", "furigana": "tóng xué men fēn bié zǒu jìn le kǎo chǎng", "sentence_source": "generated"}, {"text": "请把苹果和梨分别放在两个盘子里。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他分别买了红色和蓝色的鞋。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个人分别说出了自己的想法。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天分别去看爷爷和奶奶。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试后，老师分别和每个学生谈了话。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词，放在动词前，表示各自分开地做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c51f155-0521-4e71-90b5-132e48d69207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86555, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分别", "is_correct": true, "explanation": "正确。“分别”表示两人各自分开去不同的城市，与“两个城市”相合。"}, {"text": "独自", "is_correct": false, "explanation": "语义：“独自”指一个人单独做，而句子的主语“我和姐姐”是两个人，不能说独自。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与“不”“没”等否定词搭配，不能说“从来去了”。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与表示已完成的“去了”矛盾。"}], "explanations": {"分别": "正确。“分别”表示两人各自分开去不同的城市，与“两个城市”相合。", "独自": "语义：“独自”指一个人单独做，而句子的主语“我和姐姐”是两个人，不能说独自。", "从来": "搭配：“从来”通常与“不”“没”等否定词搭配，不能说“从来去了”。", "正在": "体貌：“正在”表示动作进行中，与表示已完成的“去了”矛盾。"}, "sentence_index": 0, "correct_answer": "分别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他分别去了北京。", "explanation": "这里应该用〈单独〉。“分别”要求两个或以上的对象各自做，只有一个人去一个地方时要说“单独”。"}, {"text": "全班分别站成一排，等老师拍照。", "explanation": "这里应该用〈整体〉。“分别”要求几个对象各自行动，“站成一排”是整体的站法，与“分别”矛盾。"}, {"text": "我们分别一起去了公园。", "explanation": "这里是把“分别”用成了〈共同〉的意思。“分别”表示各自分开去，不能表示大家共同去，所以与“一起”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86555, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分别", "is_correct": true, "explanation": "正确。“分别”表示各自分开做，与“红色和蓝色的鞋”两种颜色相合。"}, {"text": "轮流", "is_correct": false, "explanation": "语义：“轮流”需要多人依次做，而句子的主语“他”只有一个人。"}, {"text": "互相", "is_correct": false, "explanation": "语义：“互相”表示彼此对待，需要两方以上，与单一主语“他”不合。"}, {"text": "永远", "is_correct": false, "explanation": "体貌：“永远”表示持续不变，不能与表示已完成的“买了”搭配。"}], "explanations": {"分别": "正确。“分别”表示各自分开做，与“红色和蓝色的鞋”两种颜色相合。", "轮流": "语义：“轮流”需要多人依次做，而句子的主语“他”只有一个人。", "互相": "语义：“互相”表示彼此对待，需要两方以上，与单一主语“他”不合。", "永远": "体貌：“永远”表示持续不变，不能与表示已完成的“买了”搭配。"}, "sentence_index": 6, "correct_answer": "分别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把三本书分别合在一起放进了包里。", "explanation": "这里是把“分别”用成了〈合并〉的意思。“分别”表示各自分开，而“合在一起”是合为一处，两者意思相反。"}, {"text": "考试后，老师分别和全班同学集体谈了话。", "explanation": "这里是把“分别”用成了〈共同〉的意思。“分别”是逐个分开进行，与大家共同进行的做法意思相反。"}, {"text": "考试后，老师分别和班长谈了话。", "explanation": "这里是把“分别”用成了〈只、仅〉的意思。“分别”要求两个或以上的对象各自处理，这里只有班长一人，不能用“分别”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们分别分别去了两家超市。", "corrected_sentence": "我们分别去了两家超市。", "error_description": "“分别”重复使用，变成“分别分别”，不通。“分别”是副词，只用一次，放在动词“去”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位老师分别的批改了作业。", "corrected_sentence": "三位老师分别批改了作业。", "error_description": "“分别”后面多加了“的”。“分别”是副词，后面直接接动词，不能加“的”，应说“分别批改了作业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
