INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86557, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "儿子是爸爸妈妈生的男孩子。", "primary_collocate": null, "pronunciation": "ér zi", "ipa": "ɚ˧˥ tsɹ̩", "syllable_count": 2, "sentences": [{"text": "我有一个儿子，他今年五岁。", "target_word": "儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的儿子很爱踢足球。", "target_word": "儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿子每天早上七点去上学。", "target_word": "儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给儿子做了一碗面条。", "target_word": "儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸带着儿子去公园玩。", "target_word": "儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生有两个孩子，一个女儿和一个儿子。", "target_word": "儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿子生病了，妈妈很着急。", "target_word": "儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明是李老师的儿子。", "target_word": "儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿子长高了，去年的裤子已经短了。", "target_word": "儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的儿子刚学会骑自行车。", "target_word": "儿子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大儿子", "label": "复合词"}, {"form": "小儿子", "label": "复合词"}, {"form": "儿子们", "label": "复数"}, {"form": "兒子", "label": "繁体"}], "register": "口语", "sense_fingerprint": "爸爸妈妈生的男孩子，与女儿相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df74260-6b71-43b4-8f1f-e506de1537f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86557, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女儿", "is_correct": false, "explanation": "语义：“女儿”指女孩，与后面的“他”性别不符。"}, {"text": "狗", "is_correct": false, "explanation": "搭配：“狗”前的量词应为“只”，与“一个”不搭配。"}, {"text": "儿子", "is_correct": true, "explanation": "儿子：爸爸妈妈生的男孩子，与“他今年五岁”相符。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”指职业，与“他今年五岁”的人物身份不符。"}], "explanations": {"女儿": "语义：“女儿”指女孩，与后面的“他”性别不符。", "狗": "搭配：“狗”前的量词应为“只”，与“一个”不搭配。", "儿子": "儿子：爸爸妈妈生的男孩子，与“他今年五岁”相符。", "老师": "语义：“老师”指职业，与“他今年五岁”的人物身份不符。"}, "sentence_index": 0, "correct_answer": "儿子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里有二十个儿子。", "explanation": "“儿子”特指父母的男性子女，这里误当作〈男孩子〉的泛称用，教室里的男学生不都是谁的儿子。"}, {"text": "她是我的儿子，今年刚结婚。", "explanation": "“儿子”指男性子女，说女儿应用〈女儿〉，这里的“她”是女性。"}, {"text": "妈妈是我的儿子。", "explanation": "“儿子”指男性子女，这里误当作〈父母〉的意思用；“妈妈”是母亲，不可能是我的儿子，两者关系颠倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：“太阳”不是人，不能“生病”，句子说的是人的病。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”是无生命的东西，不会“生病”。"}, {"text": "儿子", "is_correct": true, "explanation": "儿子：男性子女，可以“生病”，与“妈妈很着急”相符。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“生病”要求有生命的主语，“房子”不能与之搭配。"}], "explanations": {"太阳": "语义：“太阳”不是人，不能“生病”，句子说的是人的病。", "汽车": "语义：“汽车”是无生命的东西，不会“生病”。", "儿子": "儿子：男性子女，可以“生病”，与“妈妈很着急”相符。", "房子": "搭配：“生病”要求有生命的主语，“房子”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "儿子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的儿子比我大两岁，今年也上大学了。", "explanation": "“儿子”是子女，一般比父母年纪小，这里误当作〈哥哥〉用，儿子不可能比父母大。"}, {"text": "我的儿子是一把椅子。", "explanation": "“儿子”只指人，不能指物品，这里误当作〈物件〉的泛称用。"}, {"text": "我的儿子是一个女孩，今年十岁。", "explanation": "“儿子”指男性子女，与“女孩”矛盾，应说〈女儿〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家有一只儿子，今年十岁。", "corrected_sentence": "他家有一个儿子，今年十岁。", "error_description": "量词错误：“儿子”指人，应用“个”，“只”多用于动物；应说“一个儿子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家的大儿子们已经工作了。", "corrected_sentence": "我家的大儿子已经工作了。", "error_description": "多加了“们”：“儿子们”表复数，这里只指一个儿子，“大儿子”后面不能加“们”；应说“我家的大儿子已经工作了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
