INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86563, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最近是离现在不久的这几天。", "primary_collocate": null, "pronunciation": "zuì jìn", "ipa": "tswei˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "最近天气很冷，我每天都穿厚衣服。", "target_word": "最近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近我工作很忙，没有时间看电影。", "target_word": "最近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最近身体怎么样？", "target_word": "最近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近在学做中国菜。", "target_word": "最近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近几天一直下雨，哪儿也不能去。", "target_word": "最近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最近常常睡得很晚，早上起不来。", "target_word": "最近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈最近买了一件新衣服。", "target_word": "最近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近小王看起来很高兴，是不是有好事？", "target_word": "最近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，最近大家都学得很努力。", "target_word": "最近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近的新闻你看了吗？", "target_word": "最近", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示离现在不久的这几天，指时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df74260-6b71-43b4-8f1f-e506de1537f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86563, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "最紧", "is_correct": false, "explanation": "jǐn（第三声）与 jìn（第四声）声调不同，“最紧”意思是最紧迫，与“最近”不同。"}, {"text": "最近", "is_correct": true, "explanation": "最近 zuì jìn：离现在不久的这几天，正确答案。"}, {"text": "最俊", "is_correct": false, "explanation": "jùn 与 jìn 的韵母 ü 与 i 不同，“最俊”意思是最英俊。"}, {"text": "最简", "is_correct": false, "explanation": "jiǎn 比 jìn 多出一个韵母 a，“最简”意思是最简单。"}, {"text": "最精", "is_correct": false, "explanation": "jīng 与 jìn 的韵尾 ng 与 n 不同，“最精”意思是最精明。"}], "explanations": {"最紧": "jǐn（第三声）与 jìn（第四声）声调不同，“最紧”意思是最紧迫，与“最近”不同。", "最近": "最近 zuì jìn：离现在不久的这几天，正确答案。", "最俊": "jùn 与 jìn 的韵母 ü 与 i 不同，“最俊”意思是最英俊。", "最简": "jiǎn 比 jìn 多出一个韵母 a，“最简”意思是最简单。", "最精": "jīng 与 jìn 的韵尾 ng 与 n 不同，“最精”意思是最精明。"}, "sentence_index": null, "correct_answer": "最近"}, "level_3": {"options": [{"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”指地方，不指时间段，不能作“天气很冷”的时间背景。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“眼睛”不能作时间背景，“眼睛天气很冷”不成立。"}, {"text": "最近", "is_correct": true, "explanation": "最近：离现在不久的这几天，与“天气很冷，每天穿厚衣服”的情况相符。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”不是时间词，无法与“天气很冷”组成时间背景。"}], "explanations": {"食堂": "语义：“食堂”指地方，不指时间段，不能作“天气很冷”的时间背景。", "眼睛": "搭配：“眼睛”不能作时间背景，“眼睛天气很冷”不成立。", "最近": "最近：离现在不久的这几天，与“天气很冷，每天穿厚衣服”的情况相符。", "书": "搭配：“书”不是时间词，无法与“天气很冷”组成时间背景。"}, "sentence_index": 0, "correct_answer": "最近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座房子是最近在1900年建的。", "explanation": "这里的“最近”指说话前几天，不能修饰1900年这样久远的时间，这里误当作〈以前〉用。"}, {"text": "最近下午三点他才到家。", "explanation": "这里的“最近”指这几天的一段时间，不能用于具体的时刻；表示刚过去的一点时间应说〈刚刚〉。"}, {"text": "他最近去年去了北京。", "explanation": "这里的“最近”指说话前几天，不能当作〈近年〉使用，所以不能与“去年”这样整年的时段连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86563, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“买了”这种已完成的动作冲突。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”指将来的一年，与已完成的“买了”冲突。"}, {"text": "最近", "is_correct": true, "explanation": "最近：离现在不久的这几天，与“买了一件新衣服”的已完成动作相符。"}, {"text": "下个月", "is_correct": false, "explanation": "搭配：“下个月”是将来的时间，不能与已完成的“买了”搭配。"}], "explanations": {"明天": "语义：“明天”指将来，与“买了”这种已完成的动作冲突。", "明年": "语义：“明年”指将来的一年，与已完成的“买了”冲突。", "最近": "最近：离现在不久的这几天，与“买了一件新衣服”的已完成动作相符。", "下个月": "搭配：“下个月”是将来的时间，不能与已完成的“买了”搭配。"}, "sentence_index": 6, "correct_answer": "最近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最近一小时前就到了。", "explanation": "这里的“最近”误当作〈刚刚〉用，但它只指说话前几天，不能与“一小时前”这样具体的时间点连用。"}, {"text": "我小时候最近住在农村。", "explanation": "这里的“最近”误当作〈从前〉用，但它只指说话前几天，不能与“小时候”这样久远的时段连用。"}, {"text": "我们的会议最近在明年举行。", "explanation": "这里的“最近”指说话前不久的几天，不能当作〈不久以后〉使用，所以不能与将来的“明年”连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的朋友最近的生病了，我常去医院看他。", "corrected_sentence": "我的朋友最近生病了，我常去医院看他。", "error_description": "多加了“的”：“最近”是时间状语，修饰“生病”，后面不能加“的”；应说“我的朋友最近生病了”，“最近的生病了”母语者不会这样说。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86563, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我最近的很忙，没有时间吃饭。", "corrected_sentence": "我最近很忙，没有时间吃饭。", "error_description": "多加了“的”：“最近”在这里作状语修饰“很忙”，后面不能加“的”；应说“我最近很忙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86565, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "召回", "is_correct": true, "explanation": "召回：与“派”构成反义，指把派出去的人叫回来。"}, {"text": "读", "is_correct": false, "explanation": "与“派”无反义关系，表示阅读，与派人做事无关。"}, {"text": "唱", "is_correct": false, "explanation": "与“派”无反义关系，表示歌唱。"}, {"text": "吃", "is_correct": false, "explanation": "与“派”无反义关系，表示进食。"}], "correct_answer": "召回", "explanations": {"召回": "召回：与“派”构成反义，指把派出去的人叫回来。", "读": "与“派”无反义关系，表示阅读，与派人做事无关。", "唱": "与“派”无反义关系，表示歌唱。", "吃": "与“派”无反义关系，表示进食。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c03ac2b-b940-45f2-b535-13a9061ce403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86565, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "召回", "is_correct": true, "explanation": "召回：与“派”构成反义，指把派出去的人叫回来。"}, {"text": "看", "is_correct": false, "explanation": "与“派”无反义关系，表示观看，与派人做事无关。"}, {"text": "写", "is_correct": false, "explanation": "与“派”无反义关系，表示书写。"}, {"text": "喝", "is_correct": false, "explanation": "与“派”无反义关系，表示饮用。"}], "correct_answer": "召回", "explanations": {"召回": "召回：与“派”构成反义，指把派出去的人叫回来。", "看": "与“派”无反义关系，表示观看，与派人做事无关。", "写": "与“派”无反义关系，表示书写。", "喝": "与“派”无反义关系，表示饮用。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c03ac2b-b940-45f2-b535-13a9061ce403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86565, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "派是让一个人去做一件事。", "primary_collocate": null, "pronunciation": "pài", "ipa": "pʰaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "老师派我去拿作业本。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理派小王去买东西。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈派弟弟去商店买盐。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司派他去给客人送东西。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁派你来的？", "target_word": "派", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "校长派了两个学生去帮老人。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板派我给客户打电话。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师派我们去操场拿球。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他派朋友去车站接我。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队长派人去看看前面有没有路。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "派了", "label": "体标"}, {"form": "派过", "label": "体标"}, {"form": "派去", "label": "复合"}], "register": "中性", "sense_fingerprint": "叫某人去做某件具体的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ff25525-6bcd-420e-aec5-455963bcad4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86565, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "派", "is_correct": true, "explanation": "派（pài）：叫某人去做某件具体的事。"}, {"text": "拍", "is_correct": false, "explanation": "pāi（第一声）与 pài（第四声）声调不同，意思是拍照、拍打。"}, {"text": "排", "is_correct": false, "explanation": "pái（第二声）与 pài（第四声）声调不同，意思是排列。"}, {"text": "败", "is_correct": false, "explanation": "bài 与 pài 声母不同（b 与 p），意思是失败。"}, {"text": "怕", "is_correct": false, "explanation": "pà 与 pài 韵母不同（少了 i 音），意思是害怕。"}], "explanations": {"派": "派（pài）：叫某人去做某件具体的事。", "拍": "pāi（第一声）与 pài（第四声）声调不同，意思是拍照、拍打。", "排": "pái（第二声）与 pài（第四声）声调不同，意思是排列。", "败": "bài 与 pài 声母不同（b 与 p），意思是失败。", "怕": "pà 与 pài 韵母不同（少了 i 音），意思是害怕。"}, "sentence_index": null, "correct_answer": "派"}, "level_3": {"options": [{"text": "派", "is_correct": true, "explanation": "“派”表示安排人去做具体的事，“老师派我去拿作业本”符合语境。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的宾语是物品，不能以“我”为宾语，“老师买我去拿作业本”搭配不当。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”表示进食，与老师安排我去拿作业本的意思不符。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”表示加热或焚烧，“老师烧我去拿作业本”语义荒谬。"}], "explanations": {"派": "“派”表示安排人去做具体的事，“老师派我去拿作业本”符合语境。", "买": "搭配：“买”的宾语是物品，不能以“我”为宾语，“老师买我去拿作业本”搭配不当。", "吃": "语义：“吃”表示进食，与老师安排我去拿作业本的意思不符。", "烧": "语义：“烧”表示加热或焚烧，“老师烧我去拿作业本”语义荒谬。"}, "sentence_index": 0, "correct_answer": "派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天派弟弟去学校。", "explanation": "这里应该用〈送〉。派表示有权者分派任务，每天接送弟弟上学不能用派。"}, {"text": "我派自己去学校。", "explanation": "这里应该用〈走〉。派用于分派他人去做事，自己步行去学校不能用派。"}, {"text": "我派一封信给叔叔。", "explanation": "这里应该用〈寄〉。派用于分派人去担任工作或前往某处，给叔叔寄信不能用派。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c03ac2b-b940-45f2-b535-13a9061ce403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86565, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "派", "is_correct": true, "explanation": "派（pài）：叫某人去做某件具体的事。"}, {"text": "牌", "is_correct": false, "explanation": "pái（第二声）与 pài（第四声）声调不同，意思是牌子、纸牌。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 pài 声母不同（b 与 p），意思是拜访。"}, {"text": "佩", "is_correct": false, "explanation": "pèi 与 pài 韵母不同（ei 与 ai），意思是佩戴。"}, {"text": "盼", "is_correct": false, "explanation": "pàn 与 pài 韵母不同（an 与 ai），意思是盼望。"}], "explanations": {"派": "派（pài）：叫某人去做某件具体的事。", "牌": "pái（第二声）与 pài（第四声）声调不同，意思是牌子、纸牌。", "拜": "bài 与 pài 声母不同（b 与 p），意思是拜访。", "佩": "pèi 与 pài 韵母不同（ei 与 ai），意思是佩戴。", "盼": "pàn 与 pài 韵母不同（an 与 ai），意思是盼望。"}, "sentence_index": null, "correct_answer": "派"}, "level_3": {"options": [{"text": "派", "is_correct": true, "explanation": "“派”表示安排人去做具体的事，“老板派我给客户打电话”符合语境。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“我”作宾语，“老板睡我给客户打电话”不成立。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，后面不能接“我”作宾语再接动作。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”表示饮用，“老板喝我”荒谬，与派人打电话的语境不符。"}], "explanations": {"派": "“派”表示安排人去做具体的事，“老板派我给客户打电话”符合语境。", "睡": "配价：“睡”是不及物动词，不能带“我”作宾语，“老板睡我给客户打电话”不成立。", "哭": "配价：“哭”是不及物动词，后面不能接“我”作宾语再接动作。", "喝": "语义：“喝”表示饮用，“老板喝我”荒谬，与派人打电话的语境不符。"}, "sentence_index": 6, "correct_answer": "派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我周末派爸爸去看电影。", "explanation": "这里应该用〈陪〉。派表示分派任务，陪爸爸看电影是休闲，不能用派。"}, {"text": "我派一杯水给爸爸。", "explanation": "这里应该用〈倒〉。派用于分派人去做事或前往某处，倒水不能用派。"}, {"text": "周末我派朋友来家里吃饭。", "explanation": "这里应该用〈请〉。派用于分派工作，邀请朋友来吃饭不能用派。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c03ac2b-b940-45f2-b535-13a9061ce403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校明天派了一名老师去医院送资料。", "corrected_sentence": "学校明天派一名老师去医院送资料。", "error_description": "“明天”指将来，“派”后不能加“了”。错误形式：派了；正确形式：派，应为“学校明天派一名老师去医院送资料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c03ac2b-b940-45f2-b535-13a9061ce403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理派小王仓库取文件。", "corrected_sentence": "经理派小王去仓库取文件。", "error_description": "“派”后带人去某地时，“去”不能省略。正确：经理派小王去仓库取文件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c03ac2b-b940-45f2-b535-13a9061ce403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86566, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "召回", "is_correct": true, "explanation": "召回：与“派”构成反义，指把派出去的人叫回来。"}, {"text": "听", "is_correct": false, "explanation": "与“派”无反义关系，表示听闻，与委派人员无关。"}, {"text": "笑", "is_correct": false, "explanation": "与“派”无反义关系，表示发笑。"}, {"text": "跑", "is_correct": false, "explanation": "与“派”无反义关系，表示奔跑。"}], "correct_answer": "召回", "explanations": {"召回": "召回：与“派”构成反义，指把派出去的人叫回来。", "听": "与“派”无反义关系，表示听闻，与委派人员无关。", "笑": "与“派”无反义关系，表示发笑。", "跑": "与“派”无反义关系，表示奔跑。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c03ac2b-b940-45f2-b535-13a9061ce403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
