INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86567, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "当地是说话的人正说到的那个地方。", "primary_collocate": null, "pronunciation": "dāng dì", "ipa": "taŋ˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这个小镇很美，当地的房子都是白色的。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边玩，当地的孩子教我们捡贝壳。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去日本旅游，住在当地的一户人家里。", "target_word": "当地", "complexity_tier": "T3", "furigana": "tā qù rì běn lǚ yóu, zhù zài dāng dì de yí hù rén jiā lǐ.", "sentence_source": "generated"}, {"text": "当地的冬天很长，常常下雪。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国前，我查了当地的时间。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果是当地的特产。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震发生后，当地的居民马上互相帮忙。", "target_word": "当地", "complexity_tier": "T3", "furigana": "dì zhèn fā shēng hòu, dāng dì de jū mín mǎ shàng hù xiāng bāng máng.", "sentence_source": "generated"}, {"text": "我问当地的老人，路怎么走。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在北京出生，所以很了解当地的历史。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板请我们吃了当地最有名的鱼。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说话的人正说到的那个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f80bac-fc9c-4e98-9a19-048bc01aeed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86567, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当地", "is_correct": true, "explanation": "正确：「当地」指说话人所说到的那个地方，「当地的房子」指小镇的房子，与句意相符。"}, {"text": "首都", "is_correct": false, "explanation": "语义：「首都」指国家的首都城市，与「这个小镇很美」所指的地方不一致。"}, {"text": "贵地", "is_correct": false, "explanation": "语域：「贵地」是敬称对方的地方，用来描述眼前小镇的房子不合适。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：「课本」不能修饰「房子」，「课本的房子」搭配不当。"}], "explanations": {"当地": "正确：「当地」指说话人所说到的那个地方，「当地的房子」指小镇的房子，与句意相符。", "首都": "语义：「首都」指国家的首都城市，与「这个小镇很美」所指的地方不一致。", "贵地": "语域：「贵地」是敬称对方的地方，用来描述眼前小镇的房子不合适。", "课本": "搭配：「课本」不能修饰「房子」，「课本的房子」搭配不当。"}, "sentence_index": 0, "correct_answer": "当地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司的当地在北京。", "explanation": "这里应该用〈所在地〉。当地指所说到的地方，不指机构的位置。"}, {"text": "一九九九年的当地，我还没有出生。", "explanation": "这里应该用〈当时〉。当地指地方，不指时间，「一九九九年的当地」说不通。"}, {"text": "我们家的当地很大，有一个院子。", "explanation": "这里应该用〈面积〉。当地指地方，不用来描述房子或院子的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86567, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当地", "is_correct": true, "explanation": "正确：「当地」指所说到的那个地方，「当地的居民」指那里的居民，与句意相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：「游客」指来旅游的人，不能指当地的居民，「游客的居民」说法矛盾。"}, {"text": "敌方", "is_correct": false, "explanation": "语义：「敌方」指敌对的一方，「敌方的居民」与「马上互相帮忙」矛盾。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：「昨天」是时间词，「昨天的居民」指过去的居民，不能与「地震发生后」这一当下事件搭配。"}], "explanations": {"当地": "正确：「当地」指所说到的那个地方，「当地的居民」指那里的居民，与句意相符。", "游客": "语义：「游客」指来旅游的人，不能指当地的居民，「游客的居民」说法矛盾。", "敌方": "语义：「敌方」指敌对的一方，「敌方的居民」与「马上互相帮忙」矛盾。", "昨天": "语义：「昨天」是时间词，「昨天的居民」指过去的居民，不能与「地震发生后」这一当下事件搭配。"}, "sentence_index": 6, "correct_answer": "当地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部小说有很多精彩的当地。", "explanation": "这里应该用〈地方〉（指部分、方面）。当地指某个区域或所说到的地方，不指作品中精彩的部分。"}, {"text": "他在朋友中的当地很高。", "explanation": "这里应该用〈地位〉。当地指地方，不指人在群体中的身份或位置。"}, {"text": "他陷入了困难的当地。", "explanation": "这里应该用〈境地〉。当地指地方，不指人所处的境况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我当地工作了五年。", "corrected_sentence": "我在当地工作了五年。", "error_description": "错误：「当地」前缺少介词「在」。正确形式是「在当地工作了五年」，表示工作的地点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在当地的玩得很开心。", "corrected_sentence": "我们在当地玩得很开心。", "error_description": "错误：「当地」后多加了结构助词「的」，「当地的玩」不成词组。正确形式是「在当地玩得很开心」，地点作状语直接放在动词「玩」前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "不然的话，表示如果不这样就会怎样，引出否则的结果。", "primary_collocate": null, "pronunciation": "yào bù", "ipa": "jɑʊ˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "快走吧，要不就迟到了。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多穿点儿衣服，要不会感冒的。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你得早点睡，要不明天起不来。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我得带伞，要不就要淋雨了。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点吃，要不饭就凉了。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们得快点儿，要不就赶不上车了。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好好学习，要不考试会不及格。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先给他打电话，要不他会担心。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "带上手机，要不我找不到你。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你快去买票，要不就没有了。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "要不然", "label": "复合"}], "register": "口语", "sense_fingerprint": "要不：不然的话，引出否则的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487a10cd-ac34-420d-b7b4-50a652b0befc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要不", "is_correct": true, "explanation": "正确答案。要不（yào bù）：表示不然的话，引出否则的结果。"}, {"text": "腰部", "is_correct": false, "explanation": "yāo（第一声）与 yào（第四声）声调不同，意思是腰部，不是要不。"}, {"text": "药物", "is_correct": false, "explanation": "wù 与 bù 声母不同，意思是药品，不是要不。"}, {"text": "要素", "is_correct": false, "explanation": "sù 与 bù 声母不同，意思是要素、基本成分，不是要不。"}, {"text": "药铺", "is_correct": false, "explanation": "pù 与 bù 声母不同（p 与 b），意思是卖药的店铺，不是要不。"}], "explanations": {"要不": "正确答案。要不（yào bù）：表示不然的话，引出否则的结果。", "腰部": "yāo（第一声）与 yào（第四声）声调不同，意思是腰部，不是要不。", "药物": "wù 与 bù 声母不同，意思是药品，不是要不。", "要素": "sù 与 bù 声母不同，意思是要素、基本成分，不是要不。", "药铺": "pù 与 bù 声母不同（p 与 b），意思是卖药的店铺，不是要不。"}, "sentence_index": null, "correct_answer": "要不"}, "level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "搭配：“因为”引出原因，后面需接结果，“快走吧，因为就迟到了”不成句。"}, {"text": "只要", "is_correct": false, "explanation": "语义：“只要”表示充分条件，“快走吧”并不是“迟到”的充分条件，句意说不通。"}, {"text": "要不", "is_correct": true, "explanation": "正确答案。“要不”表示不然的话，引出不利的结果，与“快走吧”和“迟到”的语境相符。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”或“却”配合表示让步，这里不能这样用。"}], "explanations": {"因为": "搭配：“因为”引出原因，后面需接结果，“快走吧，因为就迟到了”不成句。", "只要": "语义：“只要”表示充分条件，“快走吧”并不是“迟到”的充分条件，句意说不通。", "要不": "正确答案。“要不”表示不然的话，引出不利的结果，与“快走吧”和“迟到”的语境相符。", "虽然": "搭配：“虽然”要与“但是”或“却”配合表示让步，这里不能这样用。"}, "sentence_index": 0, "correct_answer": "要不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他认真复习，要不考试很容易。", "explanation": "这里应该用〈因此〉，表示因果。〈要不〉表示“不然的话”，后面要接不利的结果，不能接“考试很容易”这样的好结果。"}, {"text": "要不下雨，我就带伞。", "explanation": "这里应该用〈要是〉，引出假设条件。〈要不〉表示不然的话，引出不利的结果，不能引出假设。"}, {"text": "这个菜很好吃，要不很便宜。", "explanation": "这里应该用〈而且〉，表示递进。〈要不〉表示不然的话，后面要接不利的结果，不能接“很便宜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "要不", "is_correct": true, "explanation": "正确答案。要不（yào bù）：表示不然的话，引出否则的结果。"}, {"text": "要害", "is_correct": false, "explanation": "hài（第四声）与 bù（第四声）声母不同（h 与 b），意思是要害、关键部位，不是要不。"}, {"text": "要务", "is_correct": false, "explanation": "wù 与 bù 声母不同，意思是重要的事务，不是要不。"}, {"text": "要付", "is_correct": false, "explanation": "fù 与 bù 声母不同，意思是支付，不是要不。"}, {"text": "要路", "is_correct": false, "explanation": "lù 与 bù 声母不同，意思是重要的道路或位置，不是要不。"}], "explanations": {"要不": "正确答案。要不（yào bù）：表示不然的话，引出否则的结果。", "要害": "hài（第四声）与 bù（第四声）声母不同（h 与 b），意思是要害、关键部位，不是要不。", "要务": "wù 与 bù 声母不同，意思是重要的事务，不是要不。", "要付": "fù 与 bù 声母不同，意思是支付，不是要不。", "要路": "lù 与 bù 声母不同，意思是重要的道路或位置，不是要不。"}, "sentence_index": null, "correct_answer": "要不"}, "level_3": {"options": [{"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，“好好学习，所以考试会不及格”前后因果颠倒，不符合句意。"}, {"text": "要不", "is_correct": true, "explanation": "正确答案。“要不”表示不然的话，引出不利的结果，与“好好学习”和“考试会不及格”的语境相符。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示时间先后，“好好学习，然后考试会不及格”顺序不通，不符合句意。"}, {"text": "只有", "is_correct": false, "explanation": "语义：“只有”表示唯一条件，“好好学习”不是“考试不及格”的唯一条件，句意不通。"}], "explanations": {"所以": "语义：“所以”表示因果，“好好学习，所以考试会不及格”前后因果颠倒，不符合句意。", "要不": "正确答案。“要不”表示不然的话，引出不利的结果，与“好好学习”和“考试会不及格”的语境相符。", "然后": "语义：“然后”表示时间先后，“好好学习，然后考试会不及格”顺序不通，不符合句意。", "只有": "语义：“只有”表示唯一条件，“好好学习”不是“考试不及格”的唯一条件，句意不通。"}, "sentence_index": 6, "correct_answer": "要不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间很小，要不很安静。", "explanation": "这里应该用〈却〉，表示转折。〈要不〉表示不然的话，后面要引出不利的结果，不能接“很安静”。"}, {"text": "我以为很便宜，要不结果很贵。", "explanation": "这里应该用〈没想到〉，表示出乎意料。〈要不〉表示“不然的话”，不能表示转折或意外的结果。"}, {"text": "他每天早起，要不身体很好。", "explanation": "这里应该用〈因此〉，表示因果。〈要不〉表示不然的话，后面要引出不利的结果，不能接“身体很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天得早起，要不如果就赶不上车了。", "corrected_sentence": "明天得早起，要不就赶不上车了。", "error_description": "错误形式是“要不如果”，正确形式是“要不”。“要不”已表示不然的话，再加“如果”会造成条件连词重复，应去掉“如果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "快去拿伞，要不是就淋湿了。", "corrected_sentence": "快去拿伞，要不就淋湿了。", "error_description": "错误形式是“要不是”，正确形式是“要不”。“要不是”表示假设相反的情况，此处表示不然的话，应去掉“是”，用“要不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86572, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86572, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86572, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示如果不这样，就另有选择；用于提出另一种办法。", "primary_collocate": null, "pronunciation": "yào bù", "ipa": "jɑʊ˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "你累了吧？要不我们休息一下。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天太冷，要不明天再去吧。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆人太多，要不去那家吧。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没空，要不你去问问小李。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要不你给他打个电话吧。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢这件吗？要不再看看别的。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车太慢，要不我们走路去。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，要不你在我家住一晚。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太晚了，要不你明天早上走吧。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会做这个，要不你来试试。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "要不然", "label": "复合"}], "register": "口语", "sense_fingerprint": "要不：提出另一种办法或建议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487a10cd-ac34-420d-b7b4-50a652b0befc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86572, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要不", "is_correct": true, "explanation": "正确答案。要不（yào bù）：表示如果不这样，就另有选择，用于提出另一种办法。"}, {"text": "腰部", "is_correct": false, "explanation": "yāo（第一声）与 yào（第四声）声调不同，意思是腰部，不是要不。"}, {"text": "药物", "is_correct": false, "explanation": "wù 与 bù 声母不同，意思是药品，不是要不。"}, {"text": "要素", "is_correct": false, "explanation": "sù 与 bù 声母不同，意思是要素、基本成分，不是要不。"}, {"text": "药铺", "is_correct": false, "explanation": "pù 与 bù 声母不同（p 与 b），意思是卖药的店铺，不是要不。"}], "explanations": {"要不": "正确答案。要不（yào bù）：表示如果不这样，就另有选择，用于提出另一种办法。", "腰部": "yāo（第一声）与 yào（第四声）声调不同，意思是腰部，不是要不。", "药物": "wù 与 bù 声母不同，意思是药品，不是要不。", "要素": "sù 与 bù 声母不同，意思是要素、基本成分，不是要不。", "药铺": "pù 与 bù 声母不同（p 与 b），意思是卖药的店铺，不是要不。"}, "sentence_index": null, "correct_answer": "要不"}, "level_3": {"options": [{"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示不这样就会怎样，前面要有明确的要求或假设，不能用来在“你累了吧？”之后提出建议。"}, {"text": "要不", "is_correct": true, "explanation": "正确答案。“要不”表示如果不这样，就另有选择，此处用来提出另一种办法，与“你累了吧？”的语境相符。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”或“却”配合表示让步，此处后半句没有对应的转折，句子不成立。"}, {"text": "因为", "is_correct": false, "explanation": "搭配：“因为”要引出原因，后面需接结果，“你累了吧？因为我们休息一下”说不通。"}], "explanations": {"否则": "语义：“否则”表示不这样就会怎样，前面要有明确的要求或假设，不能用来在“你累了吧？”之后提出建议。", "要不": "正确答案。“要不”表示如果不这样，就另有选择，此处用来提出另一种办法，与“你累了吧？”的语境相符。", "虽然": "搭配：“虽然”要与“但是”或“却”配合表示让步，此处后半句没有对应的转折，句子不成立。", "因为": "搭配：“因为”要引出原因，后面需接结果，“你累了吧？因为我们休息一下”说不通。"}, "sentence_index": 0, "correct_answer": "要不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们快点走，要不就能看到日出了。", "explanation": "这里应该用〈要是〉，引出条件。〈要不〉表示“不然的话”，后面要接不利的结果，接“能看到日出”这样的好结果说不通。"}, {"text": "他昨天没来，要不今天来了。", "explanation": "这里应该用〈然后〉，表示先后顺序。〈要不〉表示提出办法或“不然的话”，不能表示时间上的先后。"}, {"text": "他很努力，要不成绩很好。", "explanation": "这里应该用〈因此〉，表示因果。〈要不〉表示“不然的话”，后面要接不利的结果，不能引出好的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86572, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "要不", "is_correct": true, "explanation": "正确答案。要不（yào bù）：表示如果不这样，就另有选择，用于提出另一种办法。"}, {"text": "要补", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充、弥补，不是要不。"}, {"text": "要务", "is_correct": false, "explanation": "wù 与 bù 声母不同，意思是重要的事务，不是要不。"}, {"text": "要付", "is_correct": false, "explanation": "fù 与 bù 声母不同，意思是支付，不是要不。"}, {"text": "要路", "is_correct": false, "explanation": "lù 与 bù 声母不同，意思是重要的道路或位置，不是要不。"}], "explanations": {"要不": "正确答案。要不（yào bù）：表示如果不这样，就另有选择，用于提出另一种办法。", "要补": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充、弥补，不是要不。", "要务": "wù 与 bù 声母不同，意思是重要的事务，不是要不。", "要付": "fù 与 bù 声母不同，意思是支付，不是要不。", "要路": "lù 与 bù 声母不同，意思是重要的道路或位置，不是要不。"}, "sentence_index": null, "correct_answer": "要不"}, "level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "搭配：“因为”要引出原因，后面需接结果，“坐车太慢，因为我们走路去”不成句，也与提议语境不合。"}, {"text": "而", "is_correct": false, "explanation": "语域：“而”是书面连词，口语中不这样接在“我们”前面，句子生硬。"}, {"text": "要不", "is_correct": true, "explanation": "正确答案。“要不”表示如果不这样，就另有选择，此处用来提出另一种办法，与“坐车太慢”的语境相符。"}, {"text": "却", "is_correct": false, "explanation": "搭配：“却”表示转折，须放在主语之后，“坐车太慢，却我们走路去”语序不通。"}], "explanations": {"因为": "搭配：“因为”要引出原因，后面需接结果，“坐车太慢，因为我们走路去”不成句，也与提议语境不合。", "而": "语域：“而”是书面连词，口语中不这样接在“我们”前面，句子生硬。", "要不": "正确答案。“要不”表示如果不这样，就另有选择，此处用来提出另一种办法，与“坐车太慢”的语境相符。", "却": "搭配：“却”表示转折，须放在主语之后，“坐车太慢，却我们走路去”语序不通。"}, "sentence_index": 6, "correct_answer": "要不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很想去，要不没有时间。", "explanation": "这里应该用〈但是〉，表示转折。〈要不〉表示提出办法或“不然的话”，不能表示转折。"}, {"text": "这个电影很长，要不很无聊。", "explanation": "这里应该用〈而且〉，表示递进。〈要不〉表示提出办法或“不然的话”，不能用来并列两个描述。"}, {"text": "他说他会来，要不现在还没到。", "explanation": "这里应该用〈却〉，表示转折。〈要不〉不表示转折，后面应接不利的结果，不能用来描述现状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "外面下雨了，很要不我们明天再出去吧。", "corrected_sentence": "外面下雨了，要不我们明天再出去吧。", "error_description": "错误形式：“很要不”；正确形式：“要不”。“很”只能修饰形容词等，不能修饰连词“要不”，应直接用“要不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天下雨，要不是我们改天再去吧。", "corrected_sentence": "明天下雨，要不我们改天再去吧。", "error_description": "错误形式是“要不是”，正确形式是“要不”。“要不是”表示假设相反的情况，后面要接结论；这里是提出办法，应去掉“是”，用“要不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
