INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86581, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "介绍是把一个人或一样东西说给别人听，让别人认识。", "primary_collocate": null, "pronunciation": "jiè shào", "ipa": "tɕjɛ˥˩ ʂɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我来给你们介绍一下，这是我的同学。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新同事介绍给了大家。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师向我们介绍了一位中国作家。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先介绍一下自己吧。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给我介绍过一位很好的医生。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把自己的家人介绍给女朋友。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在给客人介绍我的弟弟。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能给我介绍一个新朋友吗？", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先介绍一下，这位是王老师。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家轮流介绍自己的名字。", "target_word": "介绍", "complexity_tier": "T3", "furigana": "jiè shào", "sentence_source": "generated"}], "morphological_forms": [{"form": "介绍了", "label": "体标"}, {"form": "介绍过", "label": "体标"}, {"form": "介绍着", "label": "体标"}, {"form": "介绍介绍", "label": "重叠"}, {"form": "自我介绍", "label": "复合"}, {"form": "介紹", "label": "繁体"}], "register": "通用", "sense_fingerprint": "动词：把人或物说给别人听，让别人认识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '695a92e4-d454-4f4c-ae8a-bd5477c4b635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86581, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "介绍", "is_correct": true, "explanation": "介绍：把人或东西说给别人听，让别人认识，“介绍一下”引出同学。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器或物品，不能用于把人引见给别人。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理卫生，与“这是我的同学”的引见无关。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指指出错误，不能用来引出同学。"}], "explanations": {"介绍": "介绍：把人或东西说给别人听，让别人认识，“介绍一下”引出同学。", "修理": "搭配：“修理”的对象是机器或物品，不能用于把人引见给别人。", "打扫": "语义：“打扫”指清理卫生，与“这是我的同学”的引见无关。", "批评": "语义：“批评”指指出错误，不能用来引出同学。"}, "sentence_index": 0, "correct_answer": "介绍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙介绍给了门。", "explanation": "这里应该用〈插〉。介绍是把人或事物说给别人听、让别人认识，把钥匙插进门锁要用插。"}, {"text": "他把杯子介绍到了桌上。", "explanation": "这里应该用〈放〉。介绍是把人或事物说给别人听、让别人认识，把杯子放到桌上要用放。"}, {"text": "我们介绍了三年。", "explanation": "这里应该用〈认识〉。介绍不表示相识的时长，表示认识多久要用认识。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "介绍", "is_correct": true, "explanation": "介绍：把人说给别人认识，“给客人介绍弟弟”指向客人引见。"}, {"text": "训练", "is_correct": false, "explanation": "语义：“训练”指有计划地教导或锻炼，不能用来引见某人。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象通常是衣物或身体，不能用来让客人认识弟弟。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”指给人或动物送食物，与引见无关。"}], "explanations": {"介绍": "介绍：把人说给别人认识，“给客人介绍弟弟”指向客人引见。", "训练": "语义：“训练”指有计划地教导或锻炼，不能用来引见某人。", "洗": "搭配：“洗”的对象通常是衣物或身体，不能用来让客人认识弟弟。", "喂": "语义：“喂”指给人或动物送食物，与引见无关。"}, "sentence_index": 6, "correct_answer": "介绍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这笔钱介绍给了朋友。", "explanation": "这里应该用〈借〉。介绍是把人或事物说给别人认识，借钱给朋友要用借。"}, {"text": "这道菜介绍了三十块钱。", "explanation": "这里应该用〈花〉。介绍是说给别人听或让人认识，花钱要用花。"}, {"text": "他把车介绍到了停车场。", "explanation": "这里应该用〈开〉。介绍是把人或事物说给别人听、让别人认识，把车开到停车场要用开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我想把女朋友介绍父母。", "corrected_sentence": "周末我想把女朋友介绍给父母。", "error_description": "补语缺失：把人介绍给另一方时要用“介绍给”，漏掉“给”就不成立。正确的说法是“介绍给父母”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师已经介绍过这位新同学过。", "corrected_sentence": "老师已经介绍过这位新同学了。", "error_description": "体标错误：“介绍过”中已有“过”，句末应用“了”，不能再用“过”。正确的说法是“介绍过这位新同学了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
