INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86582, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "介绍是对情况、事物的内容加以说明，让别人了解。", "primary_collocate": null, "pronunciation": "jiè shào", "ipa": "tɕjɛ˥˩ ʂɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "导游给我们介绍了这座古城的历史。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里介绍了很多中国菜的做法。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先介绍了这次比赛的规则。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章介绍了北京的变化。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理向客人介绍公司的情况。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展板上介绍了这种陶器的历史。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明书介绍了这台机器的使用方法。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你介绍一下这个手机的用法。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站上介绍着这本书的内容。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告里介绍过这种茶的好处。", "target_word": "介绍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "介绍了", "label": "体标"}, {"form": "介绍过", "label": "体标"}, {"form": "介绍着", "label": "体标"}, {"form": "介绍介绍", "label": "重叠"}, {"form": "介绍信", "label": "复合"}, {"form": "介紹", "label": "繁体"}], "register": "通用", "sense_fingerprint": "动词：说明情况或事物的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '695a92e4-d454-4f4c-ae8a-bd5477c4b635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "介绍", "is_correct": true, "explanation": "介绍：说明情况或事物的内容，“介绍了历史”指讲解古城的历史。"}, {"text": "修复", "is_correct": false, "explanation": "搭配：“修复”的对象是损坏的东西，不能说“修复历史”。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑或设施，与导游的讲解不符。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”指使事物遭受损害，与导游的讲解不符。"}], "explanations": {"介绍": "介绍：说明情况或事物的内容，“介绍了历史”指讲解古城的历史。", "修复": "搭配：“修复”的对象是损坏的东西，不能说“修复历史”。", "拆除": "语义：“拆除”指拆掉建筑或设施，与导游的讲解不符。", "破坏": "语义：“破坏”指使事物遭受损害，与导游的讲解不符。"}, "sentence_index": 0, "correct_answer": "介绍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人介绍了那根坏掉的水管。", "explanation": "这里应该用〈修理〉。介绍是说明情况或让人认识，修理坏掉的东西要用修理。"}, {"text": "他和她介绍很久了。", "explanation": "这里应该用〈认识〉。介绍不表示相识的时长，表示认识多久要用认识。"}, {"text": "这次考试他介绍了三十分。", "explanation": "这里应该用〈得〉。介绍不表示得分，得分要用得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "介绍", "is_correct": true, "explanation": "介绍：说明情况或事物的内容，“介绍了使用方法”指讲解机器怎么用。"}, {"text": "监督", "is_correct": false, "explanation": "语义：“监督”指督促检查，与讲解机器的用法无关。"}, {"text": "照顾", "is_correct": false, "explanation": "搭配：“照顾”后面接需要关心的人，不能接“使用方法”。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示热情接待，不能用于说明书的内容。"}], "explanations": {"介绍": "介绍：说明情况或事物的内容，“介绍了使用方法”指讲解机器怎么用。", "监督": "语义：“监督”指督促检查，与讲解机器的用法无关。", "照顾": "搭配：“照顾”后面接需要关心的人，不能接“使用方法”。", "欢迎": "语义：“欢迎”表示热情接待，不能用于说明书的内容。"}, "sentence_index": 6, "correct_answer": "介绍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把门介绍开了。", "explanation": "这里应该用〈打开〉。介绍是说给别人听或让人认识，开门要用打开。"}, {"text": "他介绍好了那件衬衫。", "explanation": "这里应该用〈洗〉。介绍是说明情况或让人认识，把衣服弄干净要用洗。"}, {"text": "我每天都介绍一次牙。", "explanation": "这里应该用〈刷〉。介绍是说明或让人认识，每天清洁牙齿要用刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告介绍给了今年的收入情况。", "corrected_sentence": "这份报告介绍了今年的收入情况。", "error_description": "补语误用：“介绍给”的宾语应是受介绍的人，这里把“收入情况”当作了受介绍的对象。说明内容直接用“介绍了”，正确的说法是“介绍了今年的收入情况”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的产品介绍地很清楚。", "corrected_sentence": "这家公司的产品介绍得很清楚。", "error_description": "补语标记错误：动词后接补语时应用“得”，不能用“地”。正确的说法是“介绍得很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b70a2b9d-7fc4-4d8b-bdd3-617b9c4ca8c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
