INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86584, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "对人或事物作出某种判断，多指后来发现并不符合实际的想法。", "primary_collocate": null, "pronunciation": "yǐ wéi", "ipa": "i˨˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "我以为门锁好了，可是小偷进来了。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以为自己做对了，老师却说不对。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为他很年轻，其实他五十岁了。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你以为我不知道吗？", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以为我没听见，就小声说了话。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为这家商店关门了，结果还开着。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟以为蛋糕是给他的，高兴地吃了。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都以为比赛会取消，可是下午还是开始了。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别以为我不会做饭，我做得很好。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为她是老师，后来才知道她是学生。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "以為", "label": "繁体"}], "register": "中性", "sense_fingerprint": "作出判断，后来发现不符合实际", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f80bac-fc9c-4e98-9a19-048bc01aeed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86584, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以为", "is_correct": true, "explanation": "正确答案：以为（yǐ wéi），指作出判断，后来发现不符合实际。"}, {"text": "以外", "is_correct": false, "explanation": "wéi（第二声）与 wài（第四声）韵母不同，意思是“以外”。"}, {"text": "意味", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，wéi 与 wèi 声调也不同，意思是“意味”。"}, {"text": "一位", "is_correct": false, "explanation": "yǐ 与 yí、wéi 与 wèi 声调不同，意思是“一位”（一个人）。"}, {"text": "意为", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是“表示……的意思”。"}], "explanations": {"以为": "正确答案：以为（yǐ wéi），指作出判断，后来发现不符合实际。", "以外": "wéi（第二声）与 wài（第四声）韵母不同，意思是“以外”。", "意味": "yǐ（第三声）与 yì（第四声）声调不同，wéi 与 wèi 声调也不同，意思是“意味”。", "一位": "yǐ 与 yí、wéi 与 wèi 声调不同，意思是“一位”（一个人）。", "意为": "yǐ（第三声）与 yì（第四声）声调不同，意思是“表示……的意思”。"}, "sentence_index": null, "correct_answer": "以为"}, "level_3": {"options": [{"text": "以为", "is_correct": true, "explanation": "正确：以为表示认为门锁好了，但实际并非如此，与“小偷进来了”相合。"}, {"text": "吃惊", "is_correct": false, "explanation": "语法：「吃惊」是不及物动词，后面不能直接接「门锁好了」这样的小句。"}, {"text": "感到", "is_correct": false, "explanation": "配价：“感到”后接的是感受或情绪，不能接“门锁好了”这样的事实判断。"}, {"text": "反对", "is_correct": false, "explanation": "搭配：「反对」需要带一件事或一种做法作宾语，不能直接接「门锁好了」这样的状态，句意不通。"}], "explanations": {"以为": "正确：以为表示认为门锁好了，但实际并非如此，与“小偷进来了”相合。", "吃惊": "语法：「吃惊」是不及物动词，后面不能直接接「门锁好了」这样的小句。", "感到": "配价：“感到”后接的是感受或情绪，不能接“门锁好了”这样的事实判断。", "反对": "搭配：「反对」需要带一件事或一种做法作宾语，不能直接接「门锁好了」这样的状态，句意不通。"}, "sentence_index": 0, "correct_answer": "以为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我以为昨天是星期三，这一点我绝对不会记错。", "explanation": "这里应该用〈确定〉。以为表示没有把握，与「绝对不会记错」的语气矛盾。"}, {"text": "法官以为他有罪，证据很充分。", "explanation": "这里应该用〈判定〉。以为是个人的猜想，不能用于法官的正式裁决。"}, {"text": "经理以为我们今天下班前交报告，这是命令。", "explanation": "这里应该用〈吩咐〉。以为只表示猜测，不能用于下达明确的指令；“这是命令”说明这是确定的吩咐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以为", "is_correct": true, "explanation": "正确：以为表示误以为蛋糕是给他的，与后面“高兴地吃了”相合。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”与后面“高兴地吃了”矛盾，不会既讨厌又高兴地吃。"}, {"text": "通知", "is_correct": false, "explanation": "配价：“通知”要带接收的人，不能只接“蛋糕是给他的”这样的小句。"}, {"text": "叫", "is_correct": false, "explanation": "搭配：“叫”不能接“蛋糕是给他的”这种判断，搭配不当。"}], "explanations": {"以为": "正确：以为表示误以为蛋糕是给他的，与后面“高兴地吃了”相合。", "讨厌": "语义：“讨厌”与后面“高兴地吃了”矛盾，不会既讨厌又高兴地吃。", "通知": "配价：“通知”要带接收的人，不能只接“蛋糕是给他的”这样的小句。", "叫": "搭配：“叫”不能接“蛋糕是给他的”这种判断，搭配不当。"}, "sentence_index": 6, "correct_answer": "以为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我以为下个月搬家，房子已经找好了。", "explanation": "这里应该用〈计划〉。以为是对情况的判断，不能用来说自己的安排；“房子已经找好了”说明这是有准备的计划。"}, {"text": "我以为这次一定按时交作业，这一点我向你保证。", "explanation": "这里应该用〈保证〉。以为只表示判断，不能用来向对方许诺；「向你保证」说明这是确定的承诺。"}, {"text": "我以为你早点休息，别熬夜了。", "explanation": "这里应该用〈劝〉。以为后面接的是判断，不能接“别熬夜了”这样的劝告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以为了他已经走了。", "corrected_sentence": "我以为他已经走了。", "error_description": "错误：“以为了”。正确：“以为”后不加“了”。“了”表示完成或变化，而“以为”是心理判断，不能带“了”，应为“我以为他已经走了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都以为到比赛会取消。", "corrected_sentence": "大家都以为比赛会取消。", "error_description": "错误：“以为到”。正确：“以为”后直接接小句，不能带结果补语“到”，应为“大家都以为比赛会取消”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
