INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86585, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "啥是什么的另一种说法。", "primary_collocate": null, "pronunciation": "shá", "ipa": "ʂa˧˥", "syllable_count": 1, "sentences": [{"text": "你说啥？", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你在看啥？", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他啥也不想吃。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个字是啥意思？", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你昨天买了啥？", "target_word": "啥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上吃啥？我饿死了。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我没听清，不知道他说啥。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你想喝点啥？我去买。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他今天啥都没做。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个菜叫啥名字？", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "啥：“什么”的口语说法，用于询问事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fddb6c7-4338-4064-af81-9ba45978fdd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86585, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "啥", "is_correct": true, "explanation": "啥（shá，第二声）：口语疑问代词，相当于“什么”。"}, {"text": "傻", "is_correct": false, "explanation": "shǎ（第三声）与 shá（第二声）声调不同，意思是“笨”。"}, {"text": "沙", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“沙子”。"}, {"text": "杀", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“杀”。"}, {"text": "蛇", "is_correct": false, "explanation": "shé 与 shá 韵母不同（e/a），意思是“蛇”。"}], "explanations": {"啥": "啥（shá，第二声）：口语疑问代词，相当于“什么”。", "傻": "shǎ（第三声）与 shá（第二声）声调不同，意思是“笨”。", "沙": "shā（第一声）与 shá（第二声）声调不同，意思是“沙子”。", "杀": "shā（第一声）与 shá（第二声）声调不同，意思是“杀”。", "蛇": "shé 与 shá 韵母不同（e/a），意思是“蛇”。"}, "sentence_index": null, "correct_answer": "啥"}, "level_3": {"options": [{"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问地点，“你说哪儿”不通，这里问的是说的内容。"}, {"text": "啥", "is_correct": true, "explanation": "啥：口语疑问代词，相当于“什么”，问说的内容。“你说啥？”自然。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“说”后接话语内容，不接“大家”这样的人群，“你说大家”不通。"}, {"text": "哪", "is_correct": false, "explanation": "语域：“哪”单用偏书面，口语里“你说哪”不成句。"}], "explanations": {"哪儿": "语义：“哪儿”问地点，“你说哪儿”不通，这里问的是说的内容。", "啥": "啥：口语疑问代词，相当于“什么”，问说的内容。“你说啥？”自然。", "大家": "搭配：“说”后接话语内容，不接“大家”这样的人群，“你说大家”不通。", "哪": "语域：“哪”单用偏书面，口语里“你说哪”不成句。"}, "sentence_index": 0, "correct_answer": "啥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家在啥？", "explanation": "这里应该用〈哪儿〉。问处所要用“哪儿”，“啥”问的是事物，不能问地点。"}, {"text": "那个人是啥？", "explanation": "这里应该用〈谁〉。问人的身份要用“谁”，“啥”只问事物，不能用来问人。"}, {"text": "你是啥国人？", "explanation": "这里应该用〈哪国〉。问国籍要用“哪国”，“啥”只问事物，不能用来问国别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86585, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "啥", "is_correct": true, "explanation": "啥（shá，第二声）：口语疑问代词，相当于“什么”。"}, {"text": "沙", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“沙子”。"}, {"text": "纱", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“纱布”。"}, {"text": "鲨", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“鲨鱼”。"}], "explanations": {"啥": "啥（shá，第二声）：口语疑问代词，相当于“什么”。", "沙": "shā（第一声）与 shá（第二声）声调不同，意思是“沙子”。", "纱": "shā（第一声）与 shá（第二声）声调不同，意思是“纱布”。", "鲨": "shā（第一声）与 shá（第二声）声调不同，意思是“鲨鱼”。"}, "sentence_index": null, "correct_answer": "啥"}, "level_3": {"options": [{"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”问地点，“不知道他说哪里”不通，这里问的是说的内容。"}, {"text": "啥", "is_correct": true, "explanation": "啥：口语疑问代词，相当于“什么”。“不知道他说啥”指不清楚他说了什么。"}, {"text": "大伙", "is_correct": false, "explanation": "搭配：“说”后接话语内容，不接“大伙”这样的人群，“他说大伙”不通。"}, {"text": "那", "is_correct": false, "explanation": "语域：“那”作指示词，单用时不能作“说”的宾语，“说那”不成句。"}], "explanations": {"哪里": "语义：“哪里”问地点，“不知道他说哪里”不通，这里问的是说的内容。", "啥": "啥：口语疑问代词，相当于“什么”。“不知道他说啥”指不清楚他说了什么。", "大伙": "搭配：“说”后接话语内容，不接“大伙”这样的人群，“他说大伙”不通。", "那": "语域：“那”作指示词，单用时不能作“说”的宾语，“说那”不成句。"}, "sentence_index": 6, "correct_answer": "啥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的作者是啥？", "explanation": "这里应该用〈谁〉。问人要用“谁”，“啥”只问事物，不能用来问作者这样的人。"}, {"text": "这件事你要啥样办？", "explanation": "这里应该用〈怎样〉。问办法要用“怎样”，“啥样”只问事物的样子，不能用来问办事的方式。"}, {"text": "他啥哭了一天。", "explanation": "这里应该用〈为什么〉。问原因要用“为什么”，“啥”只问事物，不能用来问哭的原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86585, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他啥不想听。", "corrected_sentence": "他啥也不想听。", "error_description": "错误：“啥”表示任何事物时，否定句要说“啥也不”，中间缺少“也”。正确：“啥也不想听”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86585, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你在忙啥吗？", "corrected_sentence": "你在忙啥呢？", "error_description": "错误：句子已有疑问代词“啥”，不能再用疑问语气词“吗”，应该用“呢”。正确：“你在忙啥呢？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
