INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86586, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，什么（口语）。", "primary_collocate": null, "pronunciation": "shá", "ipa": "ʂa˧˥", "syllable_count": 1, "sentences": [{"text": "你找啥呢？", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这玩意儿是啥？", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你笑啥？这么高兴。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在吵啥？声音真大。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "快说，你到底想要啥？", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "啥？你再说一遍。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天吃点啥，你来定吧。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这儿没啥好看的。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你昨天去哪儿了，干了点啥？", "target_word": "啥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你手里拿的是啥？", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "啥：疑问代词，口语里相当于“什么”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fddb6c7-4338-4064-af81-9ba45978fdd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86586, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "啥", "is_correct": true, "explanation": "啥（shá，第二声）：口语疑问代词，相当于“什么”。"}, {"text": "傻", "is_correct": false, "explanation": "shǎ（第三声）与 shá（第二声）声调不同，意思是“笨”。"}, {"text": "鲨", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“鲨鱼”。"}, {"text": "蛇", "is_correct": false, "explanation": "shé 与 shá 韵母不同（e/a），意思是“蛇”。"}], "explanations": {"啥": "啥（shá，第二声）：口语疑问代词，相当于“什么”。", "傻": "shǎ（第三声）与 shá（第二声）声调不同，意思是“笨”。", "鲨": "shā（第一声）与 shá（第二声）声调不同，意思是“鲨鱼”。", "蛇": "shé 与 shá 韵母不同（e/a），意思是“蛇”。"}, "sentence_index": null, "correct_answer": "啥"}, "level_3": {"options": [{"text": "这样", "is_correct": false, "explanation": "配价：“找”要带事物或人作宾语，“这样”是指示方式，不能作“找”的宾语。"}, {"text": "啥", "is_correct": true, "explanation": "啥：口语疑问代词，相当于“什么”。“你找啥呢？”问的是要找的东西。"}, {"text": "怎样", "is_correct": false, "explanation": "搭配：“怎样”问方式，不能作“找”的宾语，“找怎样”不成搭配。"}, {"text": "那样", "is_correct": false, "explanation": "搭配：“那样”指示方式，“找那样”不成搭配，不能说明找的对象。"}], "explanations": {"这样": "配价：“找”要带事物或人作宾语，“这样”是指示方式，不能作“找”的宾语。", "啥": "啥：口语疑问代词，相当于“什么”。“你找啥呢？”问的是要找的东西。", "怎样": "搭配：“怎样”问方式，不能作“找”的宾语，“找怎样”不成搭配。", "那样": "搭配：“那样”指示方式，“找那样”不成搭配，不能说明找的对象。"}, "sentence_index": 0, "correct_answer": "啥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "是啥在找你？", "explanation": "这里应该用〈谁〉。问人要用“谁”，“啥”只问事物，不能用来问在找你的人。"}, {"text": "图书馆在啥？", "explanation": "这里应该用〈哪儿〉。问处所要用“哪儿”，“啥”只问事物，不能用来问地点。"}, {"text": "你是啥国人？", "explanation": "这里应该用〈哪国〉。问国籍要用“哪国”，“啥”只问事物，不能用来问国别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86586, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "啥", "is_correct": true, "explanation": "啥（shá，第二声）：口语疑问代词，相当于“什么”。"}, {"text": "沙", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“沙子”。"}, {"text": "纱", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“纱布”。"}, {"text": "杀", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“杀”。"}], "explanations": {"啥": "啥（shá，第二声）：口语疑问代词，相当于“什么”。", "沙": "shā（第一声）与 shá（第二声）声调不同，意思是“沙子”。", "纱": "shā（第一声）与 shá（第二声）声调不同，意思是“纱布”。", "杀": "shā（第一声）与 shá（第二声）声调不同，意思是“杀”。"}, "sentence_index": null, "correct_answer": "啥"}, "level_3": {"options": [{"text": "谁", "is_correct": false, "explanation": "语义：“谁”问人，“吃点谁”不通，这里问的是食物。"}, {"text": "啥", "is_correct": true, "explanation": "啥：口语疑问代词，相当于“什么”。“明天吃点啥”问的是吃什么。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问地点，“吃点哪儿”不通，这里问的是食物。"}, {"text": "大家", "is_correct": false, "explanation": "配价：“吃”要接食物作宾语，“大家”是人群，不能作“吃点”的宾语。"}], "explanations": {"谁": "语义：“谁”问人，“吃点谁”不通，这里问的是食物。", "啥": "啥：口语疑问代词，相当于“什么”。“明天吃点啥”问的是吃什么。", "哪儿": "语义：“哪儿”问地点，“吃点哪儿”不通，这里问的是食物。", "大家": "配价：“吃”要接食物作宾语，“大家”是人群，不能作“吃点”的宾语。"}, "sentence_index": 6, "correct_answer": "啥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一共有啥多少钱？", "explanation": "这里应该用〈多少〉。问数量要用“多少”，“啥”不能与“多少”并用来问钱数。"}, {"text": "这件事你要啥样办？", "explanation": "这里应该用〈怎样〉。问办事的方式要用“怎样”，“啥样”只问事物的样子。"}, {"text": "他啥哭了一天。", "explanation": "这里应该用〈为什么〉。问原因要用“为什么”，“啥”只问事物，不能用来问哭的原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors,