INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事我啥不知道。", "corrected_sentence": "这件事我啥也不知道。", "error_description": "错误：“啥”表示任何事物时，否定句要说“啥也不”，中间缺少“也”。正确：“啥也不知道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
