INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86589, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "基于是因为有这个，所以才这样做。", "primary_collocate": null, "pronunciation": "jī yú", "ipa": "tɕi˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "基于安全的考虑，公司关了后门。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基于家庭的需要，她放弃了工作。", "target_word": "基于", "complexity_tier": "T3", "furigana": "jī yú jiā tíng de xū yào, tā fàng qì le gōng zuò.", "sentence_source": "generated"}, {"text": "基于天气的原因，我们改了时间。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基于大家的要求，老师多讲了一课。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基于健康的原因，爷爷不再喝酒了。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基于以前的经验，他选了这条路。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基于价格的考虑，我没有买那辆车。", "target_word": "基于", "complexity_tier": "T3", "furigana": "jī yú jià gé de kǎo lǜ, wǒ méi yǒu mǎi nà liàng chē.", "sentence_source": "generated"}, {"text": "基于你的表现，我把钥匙交给了你。", "target_word": "基于", "complexity_tier": "T3", "furigana": "jī yú nǐ de biǎo xiàn, wǒ bǎ yào shi jiāo gěi le nǐ.", "sentence_source": "generated"}, {"text": "基于环境的变化，学校换了新办法。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基于朋友的建议，她决定去北京工作。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "基於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "介词：因为有某个原因或考虑，所以才这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad0f857-5768-4f5a-8c22-94fa3d0f839d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86589, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "基于", "is_correct": true, "explanation": "正确答案。听到的就是“基于”（jī yú）。"}, {"text": "机遇", "is_correct": false, "explanation": "机遇（jī yù）与基于的第二个音节声调不同（yù 第四声，yú 第二声），意思是机会。"}, {"text": "急于", "is_correct": false, "explanation": "急于（jí yú）与基于的第一个音节声调不同（jí 第二声，jī 第一声），意思是迫切想要。"}, {"text": "之于", "is_correct": false, "explanation": "之于（zhī yú）与基于的第一个音节声母不同（zh 与 j），韵母和声调相同，意思是对于。"}, {"text": "低于", "is_correct": false, "explanation": "低于（dī yú）与基于的第一个音节声母不同（d 与 j），声调相同，意思是比……低。"}], "explanations": {"基于": "正确答案。听到的就是“基于”（jī yú）。", "机遇": "机遇（jī yù）与基于的第二个音节声调不同（yù 第四声，yú 第二声），意思是机会。", "急于": "急于（jí yú）与基于的第一个音节声调不同（jí 第二声，jī 第一声），意思是迫切想要。", "之于": "之于（zhī yú）与基于的第一个音节声母不同（zh 与 j），韵母和声调相同，意思是对于。", "低于": "低于（dī yú）与基于的第一个音节声母不同（d 与 j），声调相同，意思是比……低。"}, "sentence_index": null, "correct_answer": "基于"}, "level_3": {"options": [{"text": "基于", "is_correct": true, "explanation": "正确。基于表示以某种考虑为原因，这里说明公司关后门的原因。"}, {"text": "除了", "is_correct": false, "explanation": "语义：“除了”表示排除其他情况，不能引出关后门的原因。"}, {"text": "与", "is_correct": false, "explanation": "配价：“与”引出的是并列或相关的对象，不能直接作关后门的原因。"}, {"text": "向", "is_correct": false, "explanation": "搭配：“向”引出方向或对象，不能接“安全的考虑”作为原因。"}], "explanations": {"基于": "正确。基于表示以某种考虑为原因，这里说明公司关后门的原因。", "除了": "语义：“除了”表示排除其他情况，不能引出关后门的原因。", "与": "配价：“与”引出的是并列或相关的对象，不能直接作关后门的原因。", "向": "搭配：“向”引出方向或对象，不能接“安全的考虑”作为原因。"}, "sentence_index": 0, "correct_answer": "基于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇报道基于三位专家的意见。", "explanation": "这里“基于”表示以某事物为根据或来源，属于另一个义项，不表示“因为有这个原因，所以才这样做”。"}, {"text": "这个结论基于三年的研究。", "explanation": "这里“基于”表示以某事物为根据或来源，属于另一个义项，不表示“因为有这个原因，所以才这样做”。"}, {"text": "他基于父母的收入生活。", "explanation": "这里应该用〈依靠〉。基于表示以某种考虑为前提做出行动，不表示靠别人的钱维持生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86589, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "基于", "is_correct": true, "explanation": "正确答案。听到的就是“基于”（jī yú）。"}, {"text": "机油", "is_correct": false, "explanation": "机油（jī yóu）与基于的第二个音节韵母不同（yóu 与 yú），声调相同，意思是润滑用的油。"}, {"text": "寄语", "is_correct": false, "explanation": "寄语（jì yǔ）两个音节的声调都与基于不同，意思是给人的话。"}, {"text": "急雨", "is_correct": false, "explanation": "急雨（jí yǔ）两个音节的声调都与基于不同，意思是突然下的大雨。"}, {"text": "利于", "is_correct": false, "explanation": "利于（lì yú）与基于的第一个音节声母和声调都不同（l 与 j，第四声），意思是有益于。"}], "explanations": {"基于": "正确答案。听到的就是“基于”（jī yú）。", "机油": "机油（jī yóu）与基于的第二个音节韵母不同（yóu 与 yú），声调相同，意思是润滑用的油。", "寄语": "寄语（jì yǔ）两个音节的声调都与基于不同，意思是给人的话。", "急雨": "急雨（jí yǔ）两个音节的声调都与基于不同，意思是突然下的大雨。", "利于": "利于（lì yú）与基于的第一个音节声母和声调都不同（l 与 j，第四声），意思是有益于。"}, "sentence_index": null, "correct_answer": "基于"}, "level_3": {"options": [{"text": "基于", "is_correct": true, "explanation": "正确。基于表示以某种考虑为原因，这里说明没买车的原因。"}, {"text": "跟", "is_correct": false, "explanation": "配价：“跟”引出共同行动的对象，“价格的考虑”不能作为对象，句子说不通。"}, {"text": "随着", "is_correct": false, "explanation": "语义：“随着”表示伴随某种变化，不能表示没买车的原因。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替某人做事，不能表示没买车的理由。"}], "explanations": {"基于": "正确。基于表示以某种考虑为原因，这里说明没买车的原因。", "跟": "配价：“跟”引出共同行动的对象，“价格的考虑”不能作为对象，句子说不通。", "随着": "语义：“随着”表示伴随某种变化，不能表示没买车的原因。", "替": "语义：“替”表示代替某人做事，不能表示没买车的理由。"}, "sentence_index": 6, "correct_answer": "基于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "基于这个问题，我们有不同的看法。", "explanation": "这里应该用〈关于〉。基于表示以某种依据为前提，不表示谈论的对象。"}, {"text": "他基于桌子写作业。", "explanation": "这里应该用〈在〉。基于表示根据，不表示动作发生的地点，应说“在桌子上写作业”。"}, {"text": "他基于筷子吃饭。", "explanation": "这里应该用〈用〉。基于表示根据，不表示用什么工具做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "基于了成本的考虑，我们推迟了计划。", "corrected_sentence": "基于成本的考虑，我们推迟了计划。", "error_description": "错误在“基于”后面加了“了”。基于是介词，不能带“了”，应改为“基于成本的考虑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "基于着天气的考虑，学校取消了活动。", "corrected_sentence": "基于天气的考虑，学校取消了活动。", "error_description": "错误在“基于”后面加了“着”。基于是介词，不能带“着”，应改为“基于天气的考虑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
