INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86590, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，以……为根据。", "primary_collocate": null, "pronunciation": "jī yú", "ipa": "tɕi˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "这个故事基于一件真实的事。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告基于大量的数据。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的看法基于多年的经验。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影基于一本有名的小说。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的计划基于今年的成绩。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的话基于检查的结果。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏基于中国的老故事。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的判断基于这些照片。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店的价格基于成本来定。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个结论基于三年的研究。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "基於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "介词：以某事物为根据或基础", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad0f857-5768-4f5a-8c22-94fa3d0f839d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
