LUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86590, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "基于", "is_correct": true, "explanation": "正确答案。听到的就是“基于”（jī yú）。"}, {"text": "急雨", "is_correct": false, "explanation": "急雨（jí yǔ）两个音节的声调都与基于不同，意思是突然下的雨。"}, {"text": "之于", "is_correct": false, "explanation": "之于（zhī yú）与基于的第一个音节声母不同（zh 与 j），声调相同，意思是对于。"}, {"text": "机遇", "is_correct": false, "explanation": "机遇（jī yù）与基于的第二个音节声调不同（yù 第四声，yú 第二声），意思是机会。"}, {"text": "利于", "is_correct": false, "explanation": "利于（lì yú）与基于的第一个音节声母和声调都不同（l 与 j，第四声），意思是有益于。"}], "explanations": {"基于": "正确答案。听到的就是“基于”（jī yú）。", "急雨": "急雨（jí yǔ）两个音节的声调都与基于不同，意思是突然下的雨。", "之于": "之于（zhī yú）与基于的第一个音节声母不同（zh 与 j），声调相同，意思是对于。", "机遇": "机遇（jī yù）与基于的第二个音节声调不同（yù 第四声，yú 第二声），意思是机会。", "利于": "利于（lì yú）与基于的第一个音节声母和声调都不同（l 与 j，第四声），意思是有益于。"}, "sentence_index": null, "correct_answer": "基于"}, "level_3": {"options": [{"text": "基于", "is_correct": true, "explanation": "正确。基于表示以某事物为根据或来源，这里说明游戏的来源。"}, {"text": "与", "is_correct": false, "explanation": "配价：“与”引出相关的对象，后面要有谓语说明关系，这里句子缺少谓语。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替某人做事，不能表示游戏的来源。"}, {"text": "随着", "is_correct": false, "explanation": "语义：“随着”表示伴随某种变化，不能表示游戏的来源。"}], "explanations": {"基于": "正确。基于表示以某事物为根据或来源，这里说明游戏的来源。", "与": "配价：“与”引出相关的对象，后面要有谓语说明关系，这里句子缺少谓语。", "替": "语义：“替”表示代替某人做事，不能表示游戏的来源。", "随着": "语义：“随着”表示伴随某种变化，不能表示游戏的来源。"}, "sentence_index": 6, "correct_answer": "基于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我基于地板睡觉。", "explanation": "这里应该用〈在〉。基于表示根据，不表示人躺或睡在什么地方，应说“在地板上睡觉”。"}, {"text": "孩子基于沙发躺着。", "explanation": "这里应该用〈躺在〉。基于表示根据，不能用来说明人躺在什么地方。"}, {"text": "我基于地铁上班。", "explanation": "这里应该用〈乘〉。基于表示根据，不表示乘坐某种交通工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇文章被基于一次真实的采访。", "corrected_sentence": "这篇文章基于一次真实的采访。", "error_description": "错误在“基于”前面加了“被”。基于是介词，不能用在“被”字句中，应去掉“被”，说“这篇文章基于一次真实的采访”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次调查的基于三百份问卷。", "corrected_sentence": "这次调查基于三百份问卷。", "error_description": "错误在“基于”前面加了“的”。“的”应接在名词或形容词后面，基于是介词，前面不能加“的”，应改为“这次调查基于三百份问卷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86595, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "反义：“少数”与“大多数”相对，指占总数很小的一部分。"}, {"text": "时间", "is_correct": false, "explanation": "“时间”是名词，但与“大多数”并非反义词。"}, {"text": "方法", "is_correct": false, "explanation": "“方法”是名词，但与“大多数”并非反义词。"}, {"text": "窗户", "is_correct": false, "explanation": "“窗户”是名词，但与“大多数”并非反义词。"}], "correct_answer": "少数", "explanations": {"少数": "反义：“少数”与“大多数”相对，指占总数很小的一部分。", "时间": "“时间”是名词，但与“大多数”并非反义词。", "方法": "“方法”是名词，但与“大多数”并非反义词。", "窗户": "“窗户”是名词，但与“大多数”并非反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86595, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "反义：“少数”与“大多数”相对，指占总数很小的一部分。"}, {"text": "地区", "is_correct": false, "explanation": "“地区”是名词，但与“大多数”并非反义词。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”是名词，但与“大多数”并非反义词。"}, {"text": "天气", "is_correct": false, "explanation": "“天气”是名词，但与“大多数”并非反义词。"}], "correct_answer": "少数", "explanations": {"少数": "反义：“少数”与“大多数”相对，指占总数很小的一部分。", "地区": "“地区”是名词，但与“大多数”并非反义词。", "桌子": "“桌子”是名词，但与“大多数”并非反义词。", "天气": "“天气”是名词，但与“大多数”并非反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86595, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大多数是超过一半，很多很多。", "primary_collocate": null, "pronunciation": "dà duō shù", "ipa": "ta˥˩ two˥ ʂu˥˩", "syllable_count": 3, "sentences": [{"text": "大多数人都喜欢周末。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的大多数朋友住在北京。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里大多数学生会说汉语。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数员工坐地铁上班。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数商店九点开门。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里大多数人不开车。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数孩子爱吃甜的东西。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看过大多数中国电影。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数同学今天都来了。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数老人早上六点就起床了。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大多數", "label": "繁体"}], "register": "通用", "sense_fingerprint": "名词：超过一半的、很多的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad0f857-5768-4f5a-8c22-94fa3d0f839d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86595, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大多数", "is_correct": true, "explanation": "正确。大多数修饰“人”，表示超过一半的人。"}, {"text": "东西", "is_correct": false, "explanation": "语义：“东西”不能喜欢周末，与“人都喜欢”不搭。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”不是人，不能喜欢周末。"}, {"text": "动物", "is_correct": false, "explanation": "搭配：“动物人”不成词，动物不包括人，与“人都喜欢”不搭。"}], "explanations": {"大多数": "正确。大多数修饰“人”，表示超过一半的人。", "东西": "语义：“东西”不能喜欢周末，与“人都喜欢”不搭。", "汽车": "语义：“汽车”不是人，不能喜欢周末。", "动物": "搭配：“动物人”不成词，动物不包括人，与“人都喜欢”不搭。"}, "sentence_index": 0, "correct_answer": "大多数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯牛奶大多数都喝掉了。", "explanation": "这里“大多数”表示占比例的部分，属于另一个义项（比例），不能用来指计数的人或事物。"}, {"text": "班里的大多数同学一个人也没来。", "explanation": "这里“大多数”表示超过一半的人，与“一个人也没来”矛盾。"}, {"text": "班里大多数同学就是全班同学。", "explanation": "这里“大多数”表示超过一半但不是全部，不能用来表示全部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86595, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大多数", "is_correct": true, "explanation": "正确。大多数修饰“孩子”，表示超过一半的孩子。"}, {"text": "老人", "is_correct": false, "explanation": "搭配：“老人孩子”不成词，“老人”与“孩子”不能并列修饰，句子不通。"}, {"text": "书本", "is_correct": false, "explanation": "语义：“书本”不会爱吃甜的东西。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”不会爱吃甜的东西，这句话的主语必须是人。"}], "explanations": {"大多数": "正确。大多数修饰“孩子”，表示超过一半的孩子。", "老人": "搭配：“老人孩子”不成词，“老人”与“孩子”不能并列修饰，句子不通。", "书本": "语义：“书本”不会爱吃甜的东西。", "蔬菜": "语义：“蔬菜”不会爱吃甜的东西，这句话的主语必须是人。"}, "sentence_index": 6, "correct_answer": "大多数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些钱的大多数正好一半。", "explanation": "这里“大多数”表示超过一半，不能用来表示正好一半。"}, {"text": "这块蛋糕大多数被我一个人吃了。", "explanation": "这里“大多数”表示占比例的部分，不能用来指计数的人或事物。"}, {"text": "这本书的大多数全部是空白。", "explanation": "这里“大多数”表示超过一半但不是全部，与“全部是空白”的说法不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86595, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多大多数同学都同意这个办法。", "corrected_sentence": "大多数同学都同意这个办法。", "error_description": "错误在“大多数”前面多加了“很多”。两者都表示数量多，重复使用，应删去“很多”，说“大多数同学都同意这个办法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86595, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很大多数学生晚上十点就睡觉了。", "corrected_sentence": "大多数学生晚上十点就睡觉了。", "error_description": "错误在“大多数”前面加了“很”。“很”修饰形容词或动词，不能修饰名词“大多数”，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
