INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "占总数中很大比例的部分。", "primary_collocate": null, "pronunciation": "dà duō shù", "ipa": "ta˥˩ two˥ ʂu˥˩", "syllable_count": 3, "sentences": [{"text": "公司大多数的钱花在了工资上。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数的票已经卖完了。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数的问题都不难。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布料大多数用来做了窗帘。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数的学生同意老师的看法。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把大多数时间用在学习上。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投票的结果是，大多数选了第二个。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数赞成明天去公园。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书，大多数是我买的。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书大多数内容都很有趣。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大多數", "label": "繁体"}], "register": "通用", "sense_fingerprint": "名词：占总数很大比例的那一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad0f857-5768-4f5a-8c22-94fa3d0f839d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大多数", "is_correct": true, "explanation": "正确。大多数表示公司钱中占很大比例的部分，与“的钱”搭配。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”不属于公司，“公司学生的钱”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不会有钱，“窗户的钱”说不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间”不能作为“公司”的所属，“公司时间的钱”不成词组。"}], "explanations": {"大多数": "正确。大多数表示公司钱中占很大比例的部分，与“的钱”搭配。", "学生": "语义：“学生”不属于公司，“公司学生的钱”说不通。", "窗户": "语义：“窗户”不会有钱，“窗户的钱”说不通。", "时间": "搭配：“时间”不能作为“公司”的所属，“公司时间的钱”不成词组。"}, "sentence_index": 0, "correct_answer": "大多数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些钱大多数全部都花光了。", "explanation": "这里“大多数”表示很大比例但不是全部，与“全部都花光了”矛盾。"}, {"text": "这份文件的大多数只有一页。", "explanation": "这里“大多数”表示很大比例的部分，不能用来描述只有一页的很小数量。"}, {"text": "这些钱的大多数正好一半。", "explanation": "这里“大多数”表示很大比例，不表示正好一半。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大多数", "is_correct": true, "explanation": "正确。大多数表示投票中占很大比例的人，作主语。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：“小狗”不能投票，“选了第二个”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“石头选了”不搭，“选”的主语一般是人。"}, {"text": "树", "is_correct": false, "explanation": "语义：“树”不能投票，与“投票的结果是”不搭。"}], "explanations": {"大多数": "正确。大多数表示投票中占很大比例的人，作主语。", "小狗": "语义：“小狗”不能投票，“选了第二个”说不通。", "石头": "搭配：“石头选了”不搭，“选”的主语一般是人。", "树": "语义：“树”不能投票，与“投票的结果是”不搭。"}, "sentence_index": 6, "correct_answer": "大多数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的大多数全部是空白。", "explanation": "这里“大多数”表示很大比例但不是全部，与“全部是空白”矛盾。"}, {"text": "这箱苹果的大多数只剩一个。", "explanation": "这里“大多数”表示很大比例，与“只剩一个”的数量矛盾。"}, {"text": "全班大多数正好一半没有意见。", "explanation": "这里“大多数”表示很大比例，不表示正好一半。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很大多数人都喜欢这门课。", "corrected_sentence": "大多数人都喜欢这门课。", "error_description": "错误形式是「很大多数人」，正确形式是「大多数人」。「大多数」表示占很大比例的部分，本身已含程度意义，不能再受程度副词「很」修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "投票的结果是，最大多数同意这个方案。", "corrected_sentence": "投票的结果是，大多数同意这个方案。", "error_description": "错误形式是「最大多数」，正确形式是「大多数」。「大多数」本身表示占很大比例的部分，不能再受表示最高级的「最」修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86599, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "空", "is_correct": true, "explanation": "正确：空与实构成反义，指里面没有东西，与“里面满满的”相对。"}, {"text": "甜", "is_correct": false, "explanation": "甜：形容词，指味道，与“实”不构成反义。"}, {"text": "快", "is_correct": false, "explanation": "快：形容词，指速度，与“实”的里面充满与否无关，不构成反义。"}, {"text": "长", "is_correct": false, "explanation": "长：形容词，指距离或时间，与“实”不构成反义。"}], "correct_answer": "空", "explanations": {"空": "正确：空与实构成反义，指里面没有东西，与“里面满满的”相对。", "甜": "甜：形容词，指味道，与“实”不构成反义。", "快": "快：形容词，指速度，与“实”的里面充满与否无关，不构成反义。", "长": "长：形容词，指距离或时间，与“实”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
