INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街角那位店每天早上七点开门。", "corrected_sentence": "街角那家店每天早上七点开门。", "error_description": "错误形式是“那位店”，正确形式是“那家店”。量词错误：“位”用于人，店应用“家”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他妈妈在学校门口开一条店，生意很好。", "corrected_sentence": "他妈妈在学校门口开一家店，生意很好。", "error_description": "错误形式是“一条店”，正确形式是“一家店”。量词错误：“条”用于长条形的东西，店应用“家”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
