INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86602, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "出售商品或提供服务的场所。", "primary_collocate": null, "pronunciation": "diàn", "ipa": "tjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "我家旁边有一家店。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的面包很好吃。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个店几点关门？", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上有很多店。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开了一家店，卖手机。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店今天不开门。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去那家店吃饭吧。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在店里买了一件衣服。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里人很多，我们等一会儿。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个店的老板很客气。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "书店", "label": "复合"}, {"form": "商店", "label": "复合"}], "register": "中性", "sense_fingerprint": "店：出售商品或提供服务的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487a10cd-ac34-420d-b7b4-50a652b0befc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86602, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "店", "is_correct": true, "explanation": "正确答案。店（diàn）：出售商品或提供服务的场所。"}, {"text": "点", "is_correct": false, "explanation": "diǎn（第三声）与 diàn（第四声）声调不同，意思是点、小点，不是店。"}, {"text": "断", "is_correct": false, "explanation": "duàn 与 diàn 韵母不同（uan 与 ian），意思是断开，不是店。"}, {"text": "变", "is_correct": false, "explanation": "biàn 与 diàn 声母不同（b 与 d），意思是改变，不是店。"}, {"text": "念", "is_correct": false, "explanation": "niàn 与 diàn 声母不同（n 与 d），意思是朗读，不是店。"}], "explanations": {"店": "正确答案。店（diàn）：出售商品或提供服务的场所。", "点": "diǎn（第三声）与 diàn（第四声）声调不同，意思是点、小点，不是店。", "断": "duàn 与 diàn 韵母不同（uan 与 ian），意思是断开，不是店。", "变": "biàn 与 diàn 声母不同（b 与 d），意思是改变，不是店。", "念": "niàn 与 diàn 声母不同（n 与 d），意思是朗读，不是店。"}, "sentence_index": null, "correct_answer": "店"}, "level_3": {"options": [{"text": "桥", "is_correct": false, "explanation": "搭配：量词“家”只用于店铺、公司等，“桥”要用“座”，不能说“一家桥”。"}, {"text": "店", "is_correct": true, "explanation": "正确答案。“店”指出售商品或提供服务的场所，与“一家”和“旁边”的语境相符。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园不是出售商品或提供服务的场所，与“一家”所指的店铺不合。"}, {"text": "树", "is_correct": false, "explanation": "搭配：量词“家”不能用于树，树要用“棵”，不能说“一家树”。"}], "explanations": {"桥": "搭配：量词“家”只用于店铺、公司等，“桥”要用“座”，不能说“一家桥”。", "店": "正确答案。“店”指出售商品或提供服务的场所，与“一家”和“旁边”的语境相符。", "公园": "语义：公园不是出售商品或提供服务的场所，与“一家”所指的店铺不合。", "树": "搭配：量词“家”不能用于树，树要用“棵”，不能说“一家树”。"}, "sentence_index": 0, "correct_answer": "店"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条街上有很多店在吃饭。", "explanation": "这里应该用〈人〉，指能吃饭的人。〈店〉指场所，不能做“吃饭”这样的动作。"}, {"text": "学生们在这条街的店里上课。", "explanation": "这里应该用〈教室〉，指上课的地方。〈店〉指售卖商品的场所，不能用来上课。"}, {"text": "他是这条街上最有名的店。", "explanation": "这里应该用〈店主〉，指经营店铺的人。〈店〉指场所，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86602, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "店", "is_correct": true, "explanation": "正确答案。店（diàn）：出售商品或提供服务的场所。"}, {"text": "段", "is_correct": false, "explanation": "duàn 与 diàn 韵母不同（uan 与 ian），意思是段落、一段，不是店。"}, {"text": "片", "is_correct": false, "explanation": "piàn 与 diàn 声母不同（p 与 d），意思是片子、片儿，不是店。"}, {"text": "典", "is_correct": false, "explanation": "diǎn 与 diàn 声调不同，意思是典范、典礼，属于书面词，不是店。"}], "explanations": {"店": "正确答案。店（diàn）：出售商品或提供服务的场所。", "段": "duàn 与 diàn 韵母不同（uan 与 ian），意思是段落、一段，不是店。", "片": "piàn 与 diàn 声母不同（p 与 d），意思是片子、片儿，不是店。", "典": "diǎn 与 diàn 声调不同，意思是典范、典礼，属于书面词，不是店。"}, "sentence_index": null, "correct_answer": "店"}, "level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：教室不是吃饭的地方，与“吃饭”不合。"}, {"text": "草地", "is_correct": false, "explanation": "搭配：量词“家”不用于草地，草地应说“片”，“那家草地”不成立。"}, {"text": "店", "is_correct": true, "explanation": "正确答案。“店”指出售商品或提供服务的场所，与“那家”和“吃饭”的语境相符。"}, {"text": "卧室", "is_correct": false, "explanation": "语义：卧室是睡觉休息的地方，不能去那里吃饭。"}], "explanations": {"教室": "语义：教室不是吃饭的地方，与“吃饭”不合。", "草地": "搭配：量词“家”不用于草地，草地应说“片”，“那家草地”不成立。", "店": "正确答案。“店”指出售商品或提供服务的场所，与“那家”和“吃饭”的语境相符。", "卧室": "语义：卧室是睡觉休息的地方，不能去那里吃饭。"}, "sentence_index": 6, "correct_answer": "店"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的店是老师。", "explanation": "这里说的是人的职业，〈店〉指场所，不能用来表示人的身份或职业。"}, {"text": "我每天去店里学游泳。", "explanation": "这里应该用〈游泳馆〉，指学游泳的地方。〈店〉指售卖商品的场所，不能用来学游泳。"}, {"text": "这个店太重了，搬不动。", "explanation": "这里应该用〈箱子〉，指可以搬动的东西。〈店〉指经营的场所，不能被搬动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只店今天打折，我们快去吧。", "corrected_sentence": "这家店今天打折，我们快去吧。", "error_description": "错误形式是“这只店”，正确形式是“这家店”。量词错误：“店”应用“家”计量，“只”多用于动物或成对的小东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
