INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86603, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "忘是以前记得，现在想不起来了。", "primary_collocate": null, "pronunciation": "wàng", "ipa": "wɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这个字我以前会写，现在忘了。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的名字我忘了，想不起来。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "十年没见，我差点忘了她的样子。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那首歌的歌词，我都忘了。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候学的英语，早就忘了。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘了他住在哪儿，只记得是一条小街。", "target_word": "忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把过去的事都忘了。", "target_word": "忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次旅行很美，我一直没忘。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路我走过，现在忘了怎么走了。", "target_word": "忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了自己的电话号码。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "忘了", "label": "体标"}, {"form": "忘过", "label": "体标"}, {"form": "忘记", "label": "复合"}], "register": "口语", "sense_fingerprint": "忘：以前记得的事现在想不起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f80bac-fc9c-4e98-9a19-048bc01aeed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86603, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忘", "is_correct": true, "explanation": "正确答案。忘（wàng）表示以前记得的事现在想不起来。"}, {"text": "万", "is_correct": false, "explanation": "万（wàn）与忘（wàng）只差韵尾 ng 和 n，意思是「一万」。"}, {"text": "网", "is_correct": false, "explanation": "网（wǎng）与忘（wàng）声调不同：网是第三声，忘是第四声，意思是「网」。"}, {"text": "放", "is_correct": false, "explanation": "放（fàng）与忘（wàng）声母不同：f 与 w，意思是「放置」。"}, {"text": "王", "is_correct": false, "explanation": "王（wáng）与忘（wàng）声调不同：王是第二声，意思是「国王」。"}], "explanations": {"忘": "正确答案。忘（wàng）表示以前记得的事现在想不起来。", "万": "万（wàn）与忘（wàng）只差韵尾 ng 和 n，意思是「一万」。", "网": "网（wǎng）与忘（wàng）声调不同：网是第三声，忘是第四声，意思是「网」。", "放": "放（fàng）与忘（wàng）声母不同：f 与 w，意思是「放置」。", "王": "王（wáng）与忘（wàng）声调不同：王是第二声，意思是「国王」。"}, "sentence_index": null, "correct_answer": "忘"}, "level_3": {"options": [{"text": "忘", "is_correct": true, "explanation": "正确。「以前会写，现在忘了」表示以前记得，现在想不起来。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：「扔」要接具体物品，不能接「字」这种记忆对象。"}, {"text": "放", "is_correct": false, "explanation": "配价：「放」要求处所宾语，「放了」不能用来说明字的记忆状态。"}, {"text": "丢", "is_correct": false, "explanation": "语义：「丢」是东西不见了，与「以前会写」所说的能力不符。"}], "explanations": {"忘": "正确。「以前会写，现在忘了」表示以前记得，现在想不起来。", "扔": "搭配：「扔」要接具体物品，不能接「字」这种记忆对象。", "放": "配价：「放」要求处所宾语，「放了」不能用来说明字的记忆状态。", "丢": "语义：「丢」是东西不见了，与「以前会写」所说的能力不符。"}, "sentence_index": 0, "correct_answer": "忘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都认真忘那首歌的歌词。", "explanation": "这里应该用〈学〉。「忘」表示想不起来，不表示学习的过程。"}, {"text": "他有了名气就忘了本，不再回老家。", "explanation": "这里的「忘」是「忘本」，指发达后不念旧，不是「想不起来」。"}, {"text": "他高兴得忘了形，抱着箱子在屋里乱跑。", "explanation": "这里的「忘」是「忘形」，形容高兴得不顾形象，不是「想不起来」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86603, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "忘", "is_correct": true, "explanation": "正确答案。忘（wàng）表示以前记得的事现在想不起来。"}, {"text": "往", "is_correct": false, "explanation": "往（wǎng）与忘（wàng）声调不同：往是第三声，意思是「朝、向」。"}, {"text": "汪", "is_correct": false, "explanation": "汪（wāng）与忘（wàng）声调不同：汪是第一声，常见于「汪汪」。"}, {"text": "亡", "is_correct": false, "explanation": "亡（wáng）与忘（wàng）声调不同：亡是第二声，意思是「死亡」。"}], "explanations": {"忘": "正确答案。忘（wàng）表示以前记得的事现在想不起来。", "往": "往（wǎng）与忘（wàng）声调不同：往是第三声，意思是「朝、向」。", "汪": "汪（wāng）与忘（wàng）声调不同：汪是第一声，常见于「汪汪」。", "亡": "亡（wáng）与忘（wàng）声调不同：亡是第二声，意思是「死亡」。"}, "sentence_index": null, "correct_answer": "忘"}, "level_3": {"options": [{"text": "忘", "is_correct": true, "explanation": "正确。「老人把过去的事都忘了」表示过去记得的事现在想不起来。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」要接食物，「把过去的事都吃了」不成搭配。"}, {"text": "跑", "is_correct": false, "explanation": "配价：「跑」是不及物动词，不能带「过去的事」作宾语。"}, {"text": "卖", "is_correct": false, "explanation": "语义：「卖」指出售，与「过去的事」的记忆无关。"}], "explanations": {"忘": "正确。「老人把过去的事都忘了」表示过去记得的事现在想不起来。", "吃": "搭配：「吃」要接食物，「把过去的事都吃了」不成搭配。", "跑": "配价：「跑」是不及物动词，不能带「过去的事」作宾语。", "卖": "语义：「卖」指出售，与「过去的事」的记忆无关。"}, "sentence_index": 6, "correct_answer": "忘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天认真忘生词，所以学得很快。", "explanation": "这里应该用〈记〉。「忘」表示想不起来，不能用来表示记忆的努力。"}, {"text": "我每天都忘你，好想你。", "explanation": "这里应该用〈想〉。「忘」表示以前记得、现在想不起来，思念某人要说「想」，「忘你」与句意矛盾。"}, {"text": "他工作得很投入，忘我地干到深夜。", "explanation": "这里的「忘」是「忘我」，指投入到忘记自身，不是「想不起来」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些词我都忘了光。", "corrected_sentence": "这些词我都忘光了。", "error_description": "错误形式是「忘了光」，正确形式是「忘光了」。结果补语「光」应紧跟在「忘」后面，「了」放在句尾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年我从没忘了过她。", "corrected_sentence": "这些年我从没忘过她。", "error_description": "错误形式是「忘了过」，同时出现了「了」和「过」两个动态助词。正确形式只用「过」，表示经历过的动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86604, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "记住", "is_correct": true, "explanation": "反义：「忘」（没有记住）与「记住」（记在心里）相对。"}, {"text": "完成", "is_correct": false, "explanation": "「完成」指做完某件事，与「忘」没有反义关系。"}, {"text": "打开", "is_correct": false, "explanation": "「打开」指使门、盒子等不再关闭，与「忘」没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "「搬运」指移动物品，与「忘」没有反义关系。"}], "correct_answer": "记住", "explanations": {"记住": "反义：「忘」（没有记住）与「记住」（记在心里）相对。", "完成": "「完成」指做完某件事，与「忘」没有反义关系。", "打开": "「打开」指使门、盒子等不再关闭，与「忘」没有反义关系。", "搬运": "「搬运」指移动物品，与「忘」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86604, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "记得", "is_correct": true, "explanation": "反义：「忘」（没有记住）与「记得」（记在心里）相对。"}, {"text": "煮", "is_correct": false, "explanation": "「煮」指用水加热做熟食物，与「忘」没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "「跑」指快速移动，与「忘」没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "「唱」指发出乐音，与「忘」没有反义关系。"}], "correct_answer": "记得", "explanations": {"记得": "反义：「忘」（没有记住）与「记得」（记在心里）相对。", "煮": "「煮」指用水加热做熟食物，与「忘」没有反义关系。", "跑": "「跑」指快速移动，与「忘」没有反义关系。", "唱": "「唱」指发出乐音，与「忘」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86604, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没有记住该做的事或该带的东西。", "primary_collocate": null, "pronunciation": "wàng", "ipa": "wɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我忘了带钥匙，进不了家。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她忘了关灯，就出门了。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别忘了明天要交作业。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他忘了给妈妈打电话。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今天忘带伞，淋湿了。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘了今天要开会，所以迟到了。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门前我忘了锁门，又回去了。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是忘带手机，同事都笑他。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你忘了吃药吗？医生说一天三次。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我怕忘，所以把事写在本子上。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "忘了", "label": "体标"}, {"form": "忘过", "label": "体标"}, {"form": "忘记", "label": "复合"}], "register": "口语", "sense_fingerprint": "忘：没记住该做的事或该带的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f80bac-fc9c-4e98-9a19-048bc01aeed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86604, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忘", "is_correct": true, "explanation": "正确答案。忘（wàng）表示没有记住该做的事。"}, {"text": "万", "is_correct": false, "explanation": "万（wàn）与忘（wàng）只差韵尾 ng 和 n，意思是「一万」。"}, {"text": "网", "is_correct": false, "explanation": "网（wǎng）与忘（wàng）声调不同：网是第三声，忘是第四声，意思是「网」。"}, {"text": "放", "is_correct": false, "explanation": "放（fàng）与忘（wàng）声母不同：f 与 w，意思是「放置」。"}, {"text": "王", "is_correct": false, "explanation": "王（wáng）与忘（wàng）声调不同：王是第二声，意思是「国王」。"}], "explanations": {"忘": "正确答案。忘（wàng）表示没有记住该做的事。", "万": "万（wàn）与忘（wàng）只差韵尾 ng 和 n，意思是「一万」。", "网": "网（wǎng）与忘（wàng）声调不同：网是第三声，忘是第四声，意思是「网」。", "放": "放（fàng）与忘（wàng）声母不同：f 与 w，意思是「放置」。", "王": "王（wáng）与忘（wàng）声调不同：王是第二声，意思是「国王」。"}, "sentence_index": null, "correct_answer": "忘"}, "level_3": {"options": [{"text": "忘", "is_correct": true, "explanation": "正确。「忘了带钥匙」表示没记住要带钥匙，正好解释了后面的「进不了家」。"}, {"text": "记", "is_correct": false, "explanation": "语义：「记」是记得，记得带钥匙就不会进不了家，与后面的结果矛盾。"}, {"text": "放", "is_correct": false, "explanation": "配价：「放」要求带处所的宾语（放在某处），不能直接接「带钥匙」。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：「拿」后面要接具体物品，「拿了带钥匙」不成搭配。"}], "explanations": {"忘": "正确。「忘了带钥匙」表示没记住要带钥匙，正好解释了后面的「进不了家」。", "记": "语义：「记」是记得，记得带钥匙就不会进不了家，与后面的结果矛盾。", "放": "配价：「放」要求带处所的宾语（放在某处），不能直接接「带钥匙」。", "拿": "搭配：「拿」后面要接具体物品，「拿了带钥匙」不成搭配。"}, "sentence_index": 0, "correct_answer": "忘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他发财后忘了本，再也不回老家看看。", "explanation": "这里的「忘」是「忘本」的意思，指发达后不念旧、忘了根本，不是「没有记住」。"}, {"text": "他高兴得忘形了，在街上又唱又跳。", "explanation": "这里的「忘」是「忘形」，形容高兴得不顾形象，不是「没有记住」。"}, {"text": "妈妈仔细忘了我的作业，然后说没有问题。", "explanation": "这里应该用〈检查〉。「忘」表示没有记住，不能表示查看、核对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86604, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "忘", "is_correct": true, "explanation": "正确答案。忘（wàng）表示没有记住该做的事。"}, {"text": "往", "is_correct": false, "explanation": "往（wǎng）与忘（wàng）声调不同：往是第三声，意思是「朝、向」。"}, {"text": "汪", "is_correct": false, "explanation": "汪（wāng）与忘（wàng）声调不同：汪是第一声，常见于「汪汪」。"}, {"text": "亡", "is_correct": false, "explanation": "亡（wáng）与忘（wàng）声调不同：亡是第二声，意思是「死亡」。"}], "explanations": {"忘": "正确答案。忘（wàng）表示没有记住该做的事。", "往": "往（wǎng）与忘（wàng）声调不同：往是第三声，意思是「朝、向」。", "汪": "汪（wāng）与忘（wàng）声调不同：汪是第一声，常见于「汪汪」。", "亡": "亡（wáng）与忘（wàng）声调不同：亡是第二声，意思是「死亡」。"}, "sentence_index": null, "correct_answer": "忘"}, "level_3": {"options": [{"text": "忘", "is_correct": true, "explanation": "正确。「忘了锁门」表示没有记住锁门，所以又回去了。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：「完成」要接任务、工作等，不能接「锁门」这类日常动作，「完成了锁门」不成搭配。"}, {"text": "关", "is_correct": false, "explanation": "搭配：「关」后接的是「门」，不能接「锁门」这种动作短语。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：「欣赏」指赏玩美好的事物，与「锁门」这种日常防范动作意思不合。"}], "explanations": {"忘": "正确。「忘了锁门」表示没有记住锁门，所以又回去了。", "完成": "搭配：「完成」要接任务、工作等，不能接「锁门」这类日常动作，「完成了锁门」不成搭配。", "关": "搭配：「关」后接的是「门」，不能接「锁门」这种动作短语。", "欣赏": "语义：「欣赏」指赏玩美好的事物，与「锁门」这种日常防范动作意思不合。"}, "sentence_index": 6, "correct_answer": "忘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上都认真忘单词，希望明天能考好。", "explanation": "这里应该用〈背〉。「忘」指没有记住，不表示记忆的努力；学单词要说「背」。"}, {"text": "我在门口忘你，你快来吧。", "explanation": "这里应该用〈等〉。「忘」指没有记住，不表示在某处等候某人。"}, {"text": "我一直忘着家乡，好想回去看看。", "explanation": "这里应该用〈想〉。「忘」指不记得，思念家乡要说「想」，「忘着家乡」与句意矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很快就掉忘了明天的会议。", "corrected_sentence": "他很快就忘掉了明天的会议。", "error_description": "错误形式是「掉忘」，结果补语「掉」应紧跟在动词「忘」后面，写作「忘掉」，「了」放在句尾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天忘了了交表。", "corrected_sentence": "我今天忘了交表。", "error_description": "错误形式是「忘了了交表」，动态助词「了」重复出现。正确形式只保留一个「了」，即「忘了交表」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
