INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86605, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86605, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "恐怖是让人非常害怕。", "primary_collocate": null, "pronunciation": "kǒng bù", "ipa": "kʰʊŋ˨˩˦ pu˥˩", "syllable_count": 2, "sentences": [{"text": "这个电影太恐怖了，我晚上不敢一个人睡。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚的梦很恐怖，我醒来后还在发抖。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑夜里的森林看起来很恐怖。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了一个恐怖的故事，大家都不说话了。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震时的情景真恐怖。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座旧房子又黑又静，让人觉得恐怖。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最怕看恐怖的电影。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到那个恐怖的声音，孩子哭了起来。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里突然没有灯，气氛变得很恐怖。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的最后一页特别恐怖。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恐怖片", "label": "复合词"}, {"form": "恐怖故事", "label": "复合词"}, {"form": "恐怖电影", "label": "复合词"}], "register": "中性", "sense_fingerprint": "让人非常害怕的，形容情景、气氛或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df74260-6b71-43b4-8f1f-e506de1537f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86605, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恐怖", "is_correct": true, "explanation": "正确：「恐怖」表示让人非常害怕，与“我晚上不敢一个人睡”的情境相符。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：「高兴」指人的心情，不能用来形容电影，句子也与后半句的害怕情绪不符。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：「无聊」不会让人不敢一个人睡，与后半句表达的害怕矛盾。"}, {"text": "好笑", "is_correct": false, "explanation": "语义：「好笑」会让人发笑，与“不敢一个人睡”的恐惧心理相矛盾。"}], "explanations": {"恐怖": "正确：「恐怖」表示让人非常害怕，与“我晚上不敢一个人睡”的情境相符。", "高兴": "搭配：「高兴」指人的心情，不能用来形容电影，句子也与后半句的害怕情绪不符。", "无聊": "语义：「无聊」不会让人不敢一个人睡，与后半句表达的害怕矛盾。", "好笑": "语义：「好笑」会让人发笑，与“不敢一个人睡”的恐惧心理相矛盾。"}, "sentence_index": 0, "correct_answer": "恐怖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只刚出生的小猫很恐怖。", "explanation": "这里应该用〈可爱〉。恐怖表示让人非常害怕，形容讨人喜欢的小猫要用可爱。"}, {"text": "我对蛇很恐怖。", "explanation": "这里应该用〈害怕〉。恐怖形容使人害怕的人或事物，不能用来说明人自己怕什么，应说「我很害怕蛇」。"}, {"text": "这位新娘今天很恐怖。", "explanation": "这里应该用〈漂亮〉。恐怖指让人害怕，赞美新娘的外貌时不能用恐怖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86605, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恐怖", "is_correct": true, "explanation": "正确：「恐怖的电影」指让人害怕的电影，与「最怕看」的心理一致。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：「整齐」形容排列有序，不能用来形容电影。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：「辣」指味道，电影不能说辣，句子不通。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：「寒冷」指温度低，与「最怕看」的心理不相符，句子意思说不通。"}], "explanations": {"恐怖": "正确：「恐怖的电影」指让人害怕的电影，与「最怕看」的心理一致。", "整齐": "搭配：「整齐」形容排列有序，不能用来形容电影。", "辣": "搭配：「辣」指味道，电影不能说辣，句子不通。", "寒冷": "语义：「寒冷」指温度低，与「最怕看」的心理不相符，句子意思说不通。"}, "sentence_index": 6, "correct_answer": "恐怖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个冬天的阳光很恐怖。", "explanation": "这里应该用〈温暖〉。恐怖表示让人害怕，不能用来形容阳光的暖和。"}, {"text": "这碗汤很恐怖。", "explanation": "这里应该用〈可口〉。恐怖形容让人害怕的事物，不能用来形容汤好喝。"}, {"text": "这件首饰很恐怖。", "explanation": "这里应该用〈精致〉。恐怖指让人害怕，不能用来形容首饰做工细巧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个鬼屋恐怖，孩子们都不敢进去。", "corrected_sentence": "那个鬼屋很恐怖，孩子们都不敢进去。", "error_description": "「恐怖」作谓语时前面要加程度副词「很」，说「那个鬼屋恐怖」不完整，应说「那个鬼屋很恐怖」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部小说太恐怖过了，我看到一半就不看了。", "corrected_sentence": "这部小说太恐怖了，我看到一半就不看了。", "error_description": "错误形式是「太恐怖过了」，正确形式是「太恐怖了」。「过」表示经历过某种动作，形容词后不能加「过」；形容词后应用「了」表示感叹语气。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
