INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86609, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "取得是经过努力，得到了想要的东西。", "primary_collocate": null, "pronunciation": "qǔ dé", "ipa": "tɕʰy˨˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他努力学习，取得了好成绩。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一年的练习，她取得了第一名。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们取得了比赛的胜利。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起努力，才能取得成功。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工作中取得了很大的进步。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，他取得了第二名。", "target_word": "取得", "complexity_tier": "T3", "furigana": "zhè cì bǐ sài, tā qǔ dé le dì èr míng.", "sentence_source": "generated"}, {"text": "要取得好成绩，每天都要认真学习。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国队取得了冠军。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们很努力，所以取得了成功。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她取得过很多好成绩。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "取得了", "label": "完成体"}, {"form": "取得过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "经过努力得到想要的结果，如成绩、胜利、成功", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3410f726-dd8b-4348-a976-24df9c72ab9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86609, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "取得", "is_correct": true, "explanation": "取得 qǔdé：经过努力得到成绩、胜利等，是正确答案。"}, {"text": "去得", "is_correct": false, "explanation": "qù（第四声）与 qǔ（第三声）声调不同，去得是「能去、去得了」的意思，与「得到」无关。"}, {"text": "举得", "is_correct": false, "explanation": "jǔ 与 qǔ 声母不同（j 与 q），都是第三声，举得是「能举起」的意思。"}, {"text": "处得", "is_correct": false, "explanation": "chǔ 与 qǔ 声母不同（ch 与 q），处得意思是「相处」，如「处得来」。"}], "explanations": {"取得": "取得 qǔdé：经过努力得到成绩、胜利等，是正确答案。", "去得": "qù（第四声）与 qǔ（第三声）声调不同，去得是「能去、去得了」的意思，与「得到」无关。", "举得": "jǔ 与 qǔ 声母不同（j 与 q），都是第三声，举得是「能举起」的意思。", "处得": "chǔ 与 qǔ 声母不同（ch 与 q），处得意思是「相处」，如「处得来」。"}, "sentence_index": null, "correct_answer": "取得"}, "level_3": {"options": [{"text": "取得", "is_correct": true, "explanation": "取得：经过努力得到好成绩，与「努力学习」的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能和「成绩」搭配，不能说吃成绩。"}, {"text": "扔", "is_correct": false, "explanation": "语义：「扔」与「努力学习」的语境相反，扔掉成绩说不通。"}, {"text": "练", "is_correct": false, "explanation": "搭配：「练」的对象是技能，成绩不能用练得到。"}], "explanations": {"取得": "取得：经过努力得到好成绩，与「努力学习」的语境相符。", "吃": "搭配：「吃」不能和「成绩」搭配，不能说吃成绩。", "扔": "语义：「扔」与「努力学习」的语境相反，扔掉成绩说不通。", "练": "搭配：「练」的对象是技能，成绩不能用练得到。"}, "sentence_index": 0, "correct_answer": "取得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从超市取得了一瓶水。", "explanation": "这里应该用〈拿到〉。取得多用于成绩、成果、资格等抽象事物，买或拿具体的东西不用取得。"}, {"text": "在新学校，他取得了很多朋友。", "explanation": "这里应该用〈交到〉。取得用于成绩、成果、权利，结交朋友要用〈交到〉。"}, {"text": "他在公司工作，取得了很多笑容。", "explanation": "这里应该用〈收获〉。取得用于成绩、成果、资格等可以争取到的东西，笑容是情感的流露，要用〈收获〉或〈赢得〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86609, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取得", "is_correct": true, "explanation": "取得：要想得到好成绩，需要认真学习，与语境相符。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：「撕」不能和「成绩」搭配，撕成绩说不通。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：「踢」的对象是球类，不能和「成绩」搭配。"}, {"text": "砸", "is_correct": false, "explanation": "语义：「砸」与「认真学习」的要求相反，砸掉成绩说不通。"}], "explanations": {"取得": "取得：要想得到好成绩，需要认真学习，与语境相符。", "撕": "搭配：「撕」不能和「成绩」搭配，撕成绩说不通。", "踢": "搭配：「踢」的对象是球类，不能和「成绩」搭配。", "砸": "语义：「砸」与「认真学习」的要求相反，砸掉成绩说不通。"}, "sentence_index": 6, "correct_answer": "取得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为迟到，取得了老师的批评。", "explanation": "这里应该用〈受到〉。取得用于正面的成果、资格，受到批评要用〈受到〉。"}, {"text": "我们昨天取得了一次会议。", "explanation": "这里应该用〈召开〉。取得用于成果、资格，会议这类活动要用〈召开〉。"}, {"text": "班里取得了一位新同学。", "explanation": "这里应该用〈转来〉。取得用于成绩、成果、资格、许可等，人员到来要用〈转来〉，不用取得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在比赛中取得过了很好的成绩。", "corrected_sentence": "她在比赛中取得了很好的成绩。", "error_description": "「取得过了」应为「取得了」。“过”表示经历，与“了”同用会重复体标记，取得的完成只用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在比赛中取得着很好的名次。", "corrected_sentence": "他们在比赛中取得了很好的名次。", "error_description": "「取得着」应为「取得了」。已完成的结果要用“了”，“着”表示持续状态，与“取得”的完成义矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
