INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86610, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经过努力而得到（成绩、成果、权利、同意等）。", "primary_collocate": null, "pronunciation": "qǔ dé", "ipa": "tɕʰy˨˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他取得了老师的同意。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先要取得父母的同意。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组取得了重要的研究成果。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她取得了在这里工作的权利。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们取得了休息的权利。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过多年研究，他取得了重要成果。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要用这个房间，先取得经理的同意。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店取得了经营许可。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的工作取得了很大的成绩。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还没取得大家的同意。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "取得了", "label": "完成体"}, {"form": "取得过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "经过努力或手续而得到成果、权利、同意、许可等抽象的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3410f726-dd8b-4348-a976-24df9c72ab9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86610, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "取得", "is_correct": true, "explanation": "取得 qǔdé：经过手续或努力得到许可、权利等，是正确答案。"}, {"text": "去得", "is_correct": false, "explanation": "qù（第四声）与 qǔ（第三声）声调不同，去得是「能去、去得了」的意思，与「得到许可」无关。"}, {"text": "举得", "is_correct": false, "explanation": "jǔ 与 qǔ 声母不同（j 与 q），都是第三声，举得是「能举起」的意思。"}, {"text": "处得", "is_correct": false, "explanation": "chǔ 与 qǔ 声母不同（ch 与 q），处得意思是「相处」，如「处得来」。"}], "explanations": {"取得": "取得 qǔdé：经过手续或努力得到许可、权利等，是正确答案。", "去得": "qù（第四声）与 qǔ（第三声）声调不同，去得是「能去、去得了」的意思，与「得到许可」无关。", "举得": "jǔ 与 qǔ 声母不同（j 与 q），都是第三声，举得是「能举起」的意思。", "处得": "chǔ 与 qǔ 声母不同（ch 与 q），处得意思是「相处」，如「处得来」。"}, "sentence_index": null, "correct_answer": "取得"}, "level_3": {"options": [{"text": "取得", "is_correct": true, "explanation": "取得：得到老师的同意，同意是可以取得的东西，与语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能和「同意」搭配，不能说吃同意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔掉老师的同意说不通，与「同意」的含义相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：「拒绝」与「同意」意思相反，拒绝同意说不通。"}], "explanations": {"取得": "取得：得到老师的同意，同意是可以取得的东西，与语境相符。", "吃": "搭配：「吃」不能和「同意」搭配，不能说吃同意。", "扔": "语义：扔掉老师的同意说不通，与「同意」的含义相反。", "拒绝": "语义：「拒绝」与「同意」意思相反，拒绝同意说不通。"}, "sentence_index": 0, "correct_answer": "取得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他取得了一份礼物。", "explanation": "这里应该用〈收到〉。取得用于权利、许可等抽象事物，收到礼物要用〈收到〉。"}, {"text": "他取得了很多眼泪。", "explanation": "这里应该用〈流〉。取得只用于得到，眼泪是自然流出的，要用〈流〉。"}, {"text": "夏天到了，天上取得了一场大雨。", "explanation": "这里应该用〈下〉。取得用于成绩、成果、权利等，天气现象要用〈下〉，取得不指天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86610, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取得", "is_correct": true, "explanation": "取得：先得到经理的同意，才能使用房间，与语境相符。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：「撕」不能和「同意」搭配，撕同意说不通。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：「摔」的对象是具体的东西，不能和「同意」搭配。"}, {"text": "踩", "is_correct": false, "explanation": "语义：「踩」与「使用房间」的语境无关，踩同意说不通。"}], "explanations": {"取得": "取得：先得到经理的同意，才能使用房间，与语境相符。", "撕": "搭配：「撕」不能和「同意」搭配，撕同意说不通。", "摔": "搭配：「摔」的对象是具体的东西，不能和「同意」搭配。", "踩": "语义：「踩」与「使用房间」的语境无关，踩同意说不通。"}, "sentence_index": 6, "correct_answer": "取得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为迟到，取得了老板的批评。", "explanation": "这里应该用〈受到〉。取得用于正面的成果、资格，受到批评要用〈受到〉。"}, {"text": "我在超市取得了新鲜的水果。", "explanation": "这里应该用〈买到〉。取得不用于买来的商品，买到水果要用〈买到〉。"}, {"text": "他取得了一个错误。", "explanation": "这里应该用〈犯〉。取得只用于正面的结果，犯错误要用〈犯〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于把取得了律师的执业资格。", "corrected_sentence": "他终于取得了律师的执业资格。", "error_description": "「把取得了」应为「取得了」。“取得”没有处置义，不能用“把”；这里的“把”多余，宾语应放在“取得了”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于取得着老板的批准。", "corrected_sentence": "他终于取得了老板的批准。", "error_description": "「取得着」应为「取得了」。已完成的结果要用“了”，“着”表示持续状态，与“终于取得”的完成义矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
