INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86612, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用武器装备人或军队。", "primary_collocate": null, "pronunciation": "wǔ zhuāng", "ipa": "u˨˩˦ ʈʂwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "国家用新武器武装了军队。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们武装了村里的年轻人。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队要用最好的装备武装自己。", "target_word": "武装", "complexity_tier": "T3", "furigana": "jūn duì yào yòng zuì hǎo de zhuāng bèi wǔ zhuāng zì jǐ 。", "sentence_source": "generated"}, {"text": "这支小队已经武装好了。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定武装边境的士兵。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用枪武装起来，守住了路口。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家没有钱武装更多的军队。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们武装起来，保护自己的家。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人武装了几百个人。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要武装好士兵，再出发。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "武裝", "label": "繁体"}, {"form": "武装力量", "label": "复合"}], "register": "书面", "sense_fingerprint": "动词：用武器装备人或军队", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad0f857-5768-4f5a-8c22-94fa3d0f839d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86612, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "武装", "is_correct": true, "explanation": "wǔ zhuāng，指用武器装备人或军队，正确答案。"}, {"text": "组装", "is_correct": false, "explanation": "zǔ 与 wǔ 声母不同，意思是把零件拼装起来，不是用武器装备。"}, {"text": "古装", "is_correct": false, "explanation": "gǔ 与 wǔ 声母不同，意思是古代的服装。"}, {"text": "补妆", "is_correct": false, "explanation": "bǔ 与 wǔ 声母不同，意思是补上化妆。"}, {"text": "无妆", "is_correct": false, "explanation": "wú（第二声）与 wǔ（第三声）声调不同，意思是没有化妆。"}], "explanations": {"武装": "wǔ zhuāng，指用武器装备人或军队，正确答案。", "组装": "zǔ 与 wǔ 声母不同，意思是把零件拼装起来，不是用武器装备。", "古装": "gǔ 与 wǔ 声母不同，意思是古代的服装。", "补妆": "bǔ 与 wǔ 声母不同，意思是补上化妆。", "无妆": "wú（第二声）与 wǔ（第三声）声调不同，意思是没有化妆。"}, "sentence_index": null, "correct_answer": "武装"}, "level_3": {"options": [{"text": "武装", "is_correct": true, "explanation": "用武器装备军队，填入后符合句意。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：「讨论」的对象是问题或事情，不说「讨论军队」。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：武器不能用来欺骗军队，句意不通。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：用新武器赞美军队，武器与赞美无关，句意不通。"}], "explanations": {"武装": "用武器装备军队，填入后符合句意。", "讨论": "搭配：「讨论」的对象是问题或事情，不说「讨论军队」。", "欺骗": "语义：武器不能用来欺骗军队，句意不通。", "赞美": "语义：用新武器赞美军队，武器与赞美无关，句意不通。"}, "sentence_index": 0, "correct_answer": "武装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把自己武装得很漂亮。", "explanation": "这里应该用〈打扮〉。武装指用武器装备人或军队，不用于衣着或外貌。"}, {"text": "我们想武装一下这间屋子。", "explanation": "这里应该用〈装修〉。武装只用于武器装备人或军队，不用于房屋。"}, {"text": "这家饭店武装了新的菜单。", "explanation": "这里应该用〈设计〉。「武装」用于装备人或军队，不用于菜单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86612, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "武装", "is_correct": true, "explanation": "wǔ zhuāng，指用武器装备人或军队，正确答案。"}, {"text": "雨装", "is_correct": false, "explanation": "yǔ 与 wǔ 声母不同，意思是雨衣一类的服装。"}, {"text": "五张", "is_correct": false, "explanation": "zhāng 与 zhuāng 只差介音 u，意思是五张，是数量词组。"}, {"text": "五双", "is_correct": false, "explanation": "shuāng 与 zhuāng 声母不同（sh 与 zh），意思是五双，是数量词组。"}], "explanations": {"武装": "wǔ zhuāng，指用武器装备人或军队，正确答案。", "雨装": "yǔ 与 wǔ 声母不同，意思是雨衣一类的服装。", "五张": "zhāng 与 zhuāng 只差介音 u，意思是五张，是数量词组。", "五双": "shuāng 与 zhuāng 声母不同（sh 与 zh），意思是五双，是数量词组。"}, "sentence_index": null, "correct_answer": "武装"}, "level_3": {"options": [{"text": "武装", "is_correct": true, "explanation": "用武器装备军队，填入后符合句意。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：没有钱与嘲笑军队之间没有逻辑关系，句意不通。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：「没有钱」与「感谢军队」之间没有逻辑关系，句意不通。"}, {"text": "批评", "is_correct": false, "explanation": "语义：没有钱却去批评更多的军队，句意说不通。"}], "explanations": {"武装": "用武器装备军队，填入后符合句意。", "嘲笑": "语义：没有钱与嘲笑军队之间没有逻辑关系，句意不通。", "感谢": "语义：「没有钱」与「感谢军队」之间没有逻辑关系，句意不通。", "批评": "语义：没有钱却去批评更多的军队，句意说不通。"}, "sentence_index": 6, "correct_answer": "武装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们想武装好这份礼物。", "explanation": "这里应该用〈包装〉。武装指用武器装备，不用于包装礼物。"}, {"text": "她每天花很久武装好房间。", "explanation": "这里应该用〈布置〉。武装指用武器装备，不用于布置房间。"}, {"text": "他们武装好了这张桌子。", "explanation": "这里应该用〈收拾〉。武装指用武器装备，不用于整理桌子等物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支小队很快就武装了好。", "corrected_sentence": "这支小队很快就武装好了。", "error_description": "错误形式是「武装了好」，正确形式是「武装好了」。结果补语「好」要紧跟动词，「了」放在补语之后，不能插在动词和补语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村民们很快武装下来了。", "corrected_sentence": "村民们很快武装起来了。", "error_description": "错误形式是「武装下来」，正确形式是「武装起来」。「起来」表示动作开始并持续，「下来」在这个意思上不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
