INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86619, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "爆炸是东西突然炸开，发出很大的声音。", "primary_collocate": null, "pronunciation": "bào zhà", "ipa": "pau̯˥˩ ʈʂa˥˩", "syllable_count": 2, "sentences": [{"text": "炸弹突然爆炸，声音很大。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烟花在天上爆炸，真好看。", "target_word": "爆炸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂里的机器突然爆炸了。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到爆炸的声音，大家都很害怕。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果火碰到汽油，汽油就会爆炸。", "target_word": "爆炸", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "昨天夜里，远处爆炸过一次。", "target_word": "爆炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车起火后突然爆炸，火很大。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把炸药放好，等它爆炸。", "target_word": "爆炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家检查后说，这种炸弹不会再爆炸了。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鞭炮一点着就爆炸，声音像打雷。", "target_word": "爆炸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爆炸了", "label": "体标"}, {"form": "爆炸过", "label": "体标"}, {"form": "爆炸声", "label": "复合"}], "register": "中性", "sense_fingerprint": "炸弹、烟花等东西突然炸开并发出巨响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c51f155-0521-4e71-90b5-132e48d69207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86619, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爆炸", "is_correct": true, "explanation": "正确。“爆炸”指炸弹突然炸开并发出巨响，与“突然……声音很大”相合。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或光灭掉，与“声音很大”的情境不合。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体遇热变成液体，炸弹不会融化。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”只用于生物，不能说炸弹生长。"}], "explanations": {"爆炸": "正确。“爆炸”指炸弹突然炸开并发出巨响，与“突然……声音很大”相合。", "熄灭": "语义：“熄灭”指火或光灭掉，与“声音很大”的情境不合。", "融化": "语义：“融化”指固体遇热变成液体，炸弹不会融化。", "生长": "搭配：“生长”只用于生物，不能说炸弹生长。"}, "sentence_index": 0, "correct_answer": "爆炸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场战争突然爆炸了，很多人都逃走了。", "explanation": "这里应该用〈爆发〉。“爆炸”指东西突然炸开并发出巨响，战争、矛盾等抽象的事情要用“爆发”。"}, {"text": "这块冰在太阳下突然爆炸了，水流了一地。", "explanation": "这里应该用〈融化〉。冰受热变成水，不会炸开并发出巨响；“爆炸”指物体突然炸开，这里要用“融化”。"}, {"text": "他的腿突然爆炸了，疼得厉害。", "explanation": "这里应该用〈抽筋〉。“爆炸”指物体突然炸开，腿部突然剧痛要用“抽筋”，人的身体不能用“爆炸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86619, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爆炸", "is_correct": true, "explanation": "正确。“爆炸”指汽车起火后突然炸开，与“火很大”相合。"}, {"text": "开花", "is_correct": false, "explanation": "语义：“开花”指植物开放，汽车起火后不能开花。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：“凝固”指液体变成固体，与“起火”“火很大”的燃烧情境矛盾。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“出生”只用于人或动物，不能用于汽车。"}], "explanations": {"爆炸": "正确。“爆炸”指汽车起火后突然炸开，与“火很大”相合。", "开花": "语义：“开花”指植物开放，汽车起火后不能开花。", "凝固": "语义：“凝固”指液体变成固体，与“起火”“火很大”的燃烧情境矛盾。", "出生": "搭配：“出生”只用于人或动物，不能用于汽车。"}, "sentence_index": 6, "correct_answer": "爆炸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的病突然爆炸了，只好躺在床上。", "explanation": "这里应该用〈发作〉。“爆炸”指东西炸开，疾病突然加重要用“发作”。"}, {"text": "锅里的水开了，突然爆炸了。", "explanation": "这里应该用〈沸腾〉。水受热冒泡要用“沸腾”，不会突然炸开并发出巨响。"}, {"text": "这棵老树突然爆炸了，把路都堵住了。", "explanation": "这里应该用〈倒下〉。老树因朽烂或被风吹而倒下，要用“倒下”，不能说“爆炸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86619, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那座仓库被爆炸了，附近的人都很害怕。", "corrected_sentence": "那座仓库爆炸了，附近的人都很害怕。", "error_description": "错误：“爆炸”是不及物动词，不能用“被”字句。正确：应说“那座仓库爆炸了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86619, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汽油桶在阳光下突然把爆炸了。", "corrected_sentence": "汽油桶在阳光下突然爆炸了。", "error_description": "错误：“爆炸”是不及物动词，不能带“把”字结构。正确：应说“汽油桶在阳光下突然爆炸了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
