INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体突然破裂，并发出巨响。", "primary_collocate": null, "pronunciation": "bào zhà", "ipa": "pau̯˥˩ ʈʂa˥˩", "syllable_count": 2, "sentences": [{"text": "鸡蛋放进微波炉里会爆炸。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煤气罐在厨房突然爆炸，声音很响。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个锅炉太旧，用的时候容易爆炸。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "瓶子里的气太多，就会爆炸。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他听见砰的一声，原来是电池爆炸了。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个旧油罐爆炸过，现在没人敢靠近。", "target_word": "爆炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把罐头放在火上烤，罐头会爆炸。", "target_word": "爆炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加油站的油罐如果着火，就会爆炸。", "target_word": "爆炸", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "手机电池太热时可能会爆炸。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室里的玻璃瓶爆炸了，老师赶快关门。", "target_word": "爆炸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爆炸了", "label": "体标"}, {"form": "爆炸过", "label": "体标"}, {"form": "爆炸声", "label": "复合"}], "register": "中性", "sense_fingerprint": "煤气罐、电池等容器因压力或受热突然破裂并发出巨响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c51f155-0521-4e71-90b5-132e48d69207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爆炸", "is_correct": true, "explanation": "正确。“爆炸”指鸡蛋放进微波炉后容器内压力增大而炸开，与“微波炉”相合。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”要求能行走的生物，鸡蛋不会走路。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”指温度降低，与微波炉加热的情境相反。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”用于生物的成长，不能用于放进微波炉的鸡蛋。"}], "explanations": {"爆炸": "正确。“爆炸”指鸡蛋放进微波炉后容器内压力增大而炸开，与“微波炉”相合。", "散步": "语义：“散步”要求能行走的生物，鸡蛋不会走路。", "结冰": "语义：“结冰”指温度降低，与微波炉加热的情境相反。", "生长": "搭配：“生长”用于生物的成长，不能用于放进微波炉的鸡蛋。"}, "sentence_index": 0, "correct_answer": "爆炸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "杯子从桌上掉下来，突然爆炸了。", "explanation": "这里应该用〈破裂〉。玻璃杯摔碎不需要压力或受热，应说“破裂”；“爆炸”要求容器因压力或受热突然炸开并发出巨响。"}, {"text": "这支铅笔我一按，突然爆炸了。", "explanation": "这里应该用〈折断〉。铅笔被按断要用“折断”，不会炸开并发出巨响，不能说“爆炸”。"}, {"text": "这座桥因为洪水突然爆炸了。", "explanation": "这里应该用〈倒塌〉。桥被洪水冲毁应说“倒塌”，不是因压力或受热而炸开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爆炸", "is_correct": true, "explanation": "正确。“爆炸”指罐头受热后突然炸开，与“放在火上烤”相合。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：“凝固”指液体冷却变成固体，与“火上烤”的加热情境相反。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”只用于种子或植物，罐头不能发芽。"}, {"text": "散架", "is_correct": false, "explanation": "搭配：“散架”指器物结构松散，不能用于形容罐头。"}], "explanations": {"爆炸": "正确。“爆炸”指罐头受热后突然炸开，与“放在火上烤”相合。", "凝固": "语义：“凝固”指液体冷却变成固体，与“火上烤”的加热情境相反。", "发芽": "搭配：“发芽”只用于种子或植物，罐头不能发芽。", "散架": "搭配：“散架”指器物结构松散，不能用于形容罐头。"}, "sentence_index": 6, "correct_answer": "爆炸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的哮喘突然爆炸了，赶快去医院。", "explanation": "这里应该用〈发作〉。疾病的突然加重要用“发作”，“爆炸”只用于物体。"}, {"text": "烧开的牛奶突然爆炸了，溅了一地。", "explanation": "这里应该用〈沸腾〉。牛奶受热冒泡要用“沸腾”，不会突然炸开并发出巨响。"}, {"text": "这块饼干放久了，突然爆炸了。", "explanation": "这里应该用〈变软〉。饼干受潮后会变软，不会炸开并发出巨响，不能说“爆炸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个罐子装得太满，加热时会被爆炸。", "corrected_sentence": "这个罐子装得太满，加热时会爆炸。", "error_description": "错误：“爆炸”是不及物动词，不能用“被”字句。正确：应说“加热时会爆炸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "煤气罐爆炸的很厉害，屋子里全是烟。", "corrected_sentence": "煤气罐爆炸得很厉害，屋子里全是烟。", "error_description": "错误：补语标记用错，应用“得”，不用“的”。正确：应说“爆炸得很厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86621, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "随便", "is_correct": true, "explanation": "与「正式」相对，符合「不随便」的释义，「做事很正式」与「做事很随便」构成反义。"}, {"text": "快速", "is_correct": false, "explanation": "与「正式」没有反义关系，指速度快。"}, {"text": "明亮", "is_correct": false, "explanation": "与「正式」没有反义关系，指光线充足。"}, {"text": "安静", "is_correct": false, "explanation": "与「正式」没有反义关系，指没有声音。"}], "correct_answer": "随便", "explanations": {"随便": "与「正式」相对，符合「不随便」的释义，「做事很正式」与「做事很随便」构成反义。", "快速": "与「正式」没有反义关系，指速度快。", "明亮": "与「正式」没有反义关系，指光线充足。", "安静": "与「正式」没有反义关系，指没有声音。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86621, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "随便", "is_correct": true, "explanation": "与「正式」相对，符合「不随便」的释义，「随便地介绍自己」与「正式地介绍自己」构成反义。"}, {"text": "宽广", "is_correct": false, "explanation": "与「正式」没有反义关系，指面积大。"}, {"text": "温暖", "is_correct": false, "explanation": "与「正式」没有反义关系，指气温或感情暖和。"}, {"text": "辛苦", "is_correct": false, "explanation": "与「正式」没有反义关系，指劳累、艰难。"}], "correct_answer": "随便", "explanations": {"随便": "与「正式」相对，符合「不随便」的释义，「随便地介绍自己」与「正式地介绍自己」构成反义。", "宽广": "与「正式」没有反义关系，指面积大。", "温暖": "与「正式」没有反义关系，指气温或感情暖和。", "辛苦": "与「正式」没有反义关系，指劳累、艰难。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86621, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "正式是认真的、大家都承认的，不是随便的。", "primary_collocate": null, "pronunciation": "zhèng shì", "ipa": "tʂəŋ˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "这次比赛是正式的，不是练习。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿得很正式，像要去开会。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说话的方式很正式。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事很正式，每件事都认真准备。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友聚会不用这么正式。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一次正式的比赛，大家都很紧张。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次见客人，说话特别正式。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的会议很正式，请不要迟到。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回答问题很正式，一句玩笑都没有。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你正式地向大家介绍自己。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "非正式", "label": "否定"}, {"form": "正式工", "label": "复合"}], "register": "中性", "sense_fingerprint": "认真的、大家都承认的、不随便的，如正式比赛、说话很正式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad0f857-5768-4f5a-8c22-94fa3d0f839d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86621, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正式", "is_correct": true, "explanation": "zhèng shì，指认真的、大家承认的、不随便的，正确答案。"}, {"text": "证实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是证实。"}, {"text": "正史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是正式的史书。"}, {"text": "政治", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是政治。"}], "explanations": {"正式": "zhèng shì，指认真的、大家承认的、不随便的，正确答案。", "证实": "shí（第二声）与 shì（第四声）声调不同，意思是证实。", "正史": "shǐ（第三声）与 shì（第四声）声调不同，意思是正式的史书。", "政治": "zhì 与 shì 声母不同（zh 与 sh），意思是政治。"}, "sentence_index": null, "correct_answer": "正式"}, "level_3": {"options": [{"text": "正式", "is_correct": true, "explanation": "修饰「比赛」，表示正式的比赛，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」形容味道，不能用来形容比赛。"}, {"text": "湿", "is_correct": false, "explanation": "语义：「湿」形容含水的状态，不能用来形容比赛。"}, {"text": "厚", "is_correct": false, "explanation": "体貌：「厚」描写物体的厚度，比赛不能是厚的。"}], "explanations": {"正式": "修饰「比赛」，表示正式的比赛，符合句意。", "甜": "语义：「甜」形容味道，不能用来形容比赛。", "湿": "语义：「湿」形容含水的状态，不能用来形容比赛。", "厚": "体貌：「厚」描写物体的厚度，比赛不能是厚的。"}, "sentence_index": 0, "correct_answer": "正式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正式迟到。", "explanation": "这里应该用〈经常〉。「正式」指认真、大家承认的，不用于表示次数或频率。"}, {"text": "她用很正式的声音哄孩子睡觉。", "explanation": "这里应该用〈温柔〉。「正式」不用于形容声音的柔和。"}, {"text": "孩子们正式地在操场上玩耍。", "explanation": "这里应该用〈快乐〉。「正式」不用于描写玩耍时的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86621, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正式", "is_correct": true, "explanation": "zhèng shì，指认真的、大家承认的、不随便的，正确答案。"}, {"text": "整式", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是数学中的整式。"}, {"text": "仗势", "is_correct": false, "explanation": "zhàng 与 zhèng 韵母不同（ang 与 eng），意思是依仗权势。"}, {"text": "阵式", "is_correct": false, "explanation": "zhèn 与 zhèng 韵母不同（n 与 ng），意思是阵形。"}], "explanations": {"正式": "zhèng shì，指认真的、大家承认的、不随便的，正确答案。", "整式": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是数学中的整式。", "仗势": "zhàng 与 zhèng 韵母不同（ang 与 eng），意思是依仗权势。", "阵式": "zhèn 与 zhèng 韵母不同（n 与 ng），意思是阵形。"}, "sentence_index": null, "correct_answer": "正式"}, "level_3": {"options": [{"text": "正式", "is_correct": true, "explanation": "修饰「说话」，表示说话郑重、讲究礼节，符合句意。"}, {"text": "蓝", "is_correct": false, "explanation": "语义：「蓝」形容颜色，不能用来形容说话的方式，句意荒谬。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」描写人或物的体型，不能用来形容说话。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：「柔软」形容质地，不能用来形容说话的方式。"}], "explanations": {"正式": "修饰「说话」，表示说话郑重、讲究礼节，符合句意。", "蓝": "语义：「蓝」形容颜色，不能用来形容说话的方式，句意荒谬。", "高大": "体貌：「高大」描写人或物的体型，不能用来形容说话。", "柔软": "语义：「柔软」形容质地，不能用来形容说话的方式。"}, "sentence_index": 6, "correct_answer": "正式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我最正式的朋友。", "explanation": "这里应该用〈好〉。「正式」指认真、不随便，不用于形容人际关系。"}, {"text": "他在教室里正式地大声喊叫。", "explanation": "这里应该用〈大声〉。「正式」不形容声音的大小，这里要说「大声地喊叫」。"}, {"text": "运动员正式地飞快跑过终点。", "explanation": "这里应该用〈飞快〉。「正式」不用于描写动作的速度，这里要说「飞快地跑」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86621, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一场正式地会议，请大家准时到场。", "corrected_sentence": "这是一场正式的会议，请大家准时到场。", "error_description": "错误形式是「正式地会议」，正确形式是「正式的会议」。「正式」修饰名词「会议」时要用「的」，「地」用于修饰动词，不能用来修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86621, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正式的向大家道歉了。", "corrected_sentence": "他正式地向大家道歉了。", "error_description": "错误形式是「正式的向大家道歉」，正确形式是「正式地向大家道歉」。修饰动词的形容词作状语要用「地」，不用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86622, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "非正式", "is_correct": true, "explanation": "与「正式」相对，指不合手续、不郑重，构成反义关系。"}, {"text": "快速", "is_correct": false, "explanation": "与「正式」没有反义关系，指速度快。"}, {"text": "明亮", "is_correct": false, "explanation": "与「正式」没有反义关系，指光线充足。"}, {"text": "安静", "is_correct": false, "explanation": "与「正式」没有反义关系，指没有声音。"}], "correct_answer": "非正式", "explanations": {"非正式": "与「正式」相对，指不合手续、不郑重，构成反义关系。", "快速": "与「正式」没有反义关系，指速度快。", "明亮": "与「正式」没有反义关系，指光线充足。", "安静": "与「正式」没有反义关系，指没有声音。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
