INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86624, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "等级；按照高低、深浅分成的层次，也指学校里的年级。", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi˧˥", "syllable_count": 1, "sentences": [{"text": "我哥哥比我高一级。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今年升了一级。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛分成三级。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王和我是同一级的学生。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的职称升了一级。", "target_word": "级", "complexity_tier": "T3", "furigana": "jí", "sentence_source": "generated"}, {"text": "上一级领导明天来学校。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶分好几级，价钱不一样。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一级的同学在楼下上课。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在考试后再升一级。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种证书分几级？", "target_word": "级", "complexity_tier": "T3", "furigana": "jí", "sentence_source": "generated"}], "morphological_forms": [{"form": "年级", "label": "复合词"}, {"form": "等级", "label": "复合词"}, {"form": "級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "等级、年级的一层，常说高一级、升一级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df74260-6b71-43b4-8f1f-e506de1537f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86624, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "级", "is_correct": true, "explanation": "正确答案：级（jí），表示等级、年级。"}, {"text": "机", "is_correct": false, "explanation": "机（jī）与 jí 声调不同（第一声），意思是机器。"}, {"text": "几", "is_correct": false, "explanation": "几（jǐ）与 jí 声调不同（第三声），意思是“多少”。"}, {"text": "季", "is_correct": false, "explanation": "季（jì）与 jí 声调不同（第四声），意思是季节。"}, {"text": "棋", "is_correct": false, "explanation": "棋（qí）与 jí 声母不同（q 与 j），意思是棋类。"}, {"text": "习", "is_correct": false, "explanation": "习（xí）与 jí 声母不同（x 与 j），意思是学习、练习。"}], "explanations": {"级": "正确答案：级（jí），表示等级、年级。", "机": "机（jī）与 jí 声调不同（第一声），意思是机器。", "几": "几（jǐ）与 jí 声调不同（第三声），意思是“多少”。", "季": "季（jì）与 jí 声调不同（第四声），意思是季节。", "棋": "棋（qí）与 jí 声母不同（q 与 j），意思是棋类。", "习": "习（xí）与 jí 声母不同（x 与 j），意思是学习、练习。"}, "sentence_index": null, "correct_answer": "级"}, "level_3": {"options": [{"text": "级", "is_correct": true, "explanation": "正确：「高一级」表示比对方高一个年级或等级，与句意相符。"}, {"text": "年", "is_correct": false, "explanation": "语义：「年」是时间单位，不能表示年级或等级的高低，句子意思不自然。"}, {"text": "次", "is_correct": false, "explanation": "搭配：「次」用于次数或动作，不能表示年级或等级的高低。"}, {"text": "段", "is_correct": false, "explanation": "语义：「段」指一段路程或一段时间，不能表示年级或等级的高低。"}], "explanations": {"级": "正确：「高一级」表示比对方高一个年级或等级，与句意相符。", "年": "语义：「年」是时间单位，不能表示年级或等级的高低，句子意思不自然。", "次": "搭配：「次」用于次数或动作，不能表示年级或等级的高低。", "段": "语义：「段」指一段路程或一段时间，不能表示年级或等级的高低。"}, "sentence_index": 0, "correct_answer": "级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座楼一共有十级。", "explanation": "这里应该用〈层〉。楼的高度按层计算，级用于台阶或等级，不用来数楼层。"}, {"text": "这把椅子有四级，我坐上去很舒服。", "explanation": "这里应该用〈条〉（「椅子有四条腿」）。级只表示台阶的一层、等级或年级，不能用来计量椅子。"}, {"text": "他的成绩排在班里第三级。", "explanation": "这里应该用〈名次〉。级指等级或年级，排名的位置要说名次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86624, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "级", "is_correct": true, "explanation": "正确答案：级（jí），表示等级、年级。"}, {"text": "鸡", "is_correct": false, "explanation": "鸡（jī）与 jí 声调不同（第一声），意思是家禽。"}, {"text": "寄", "is_correct": false, "explanation": "寄（jì）与 jí 声调不同（第四声），意思是邮寄。"}, {"text": "挤", "is_correct": false, "explanation": "挤（jǐ）与 jí 声调不同（第三声），意思是拥挤。"}, {"text": "齐", "is_correct": false, "explanation": "齐（qí）与 jí 声母不同（q 与 j），意思是整齐。"}, {"text": "席", "is_correct": false, "explanation": "席（xí）与 jí 声母不同（x 与 j），意思是座位。"}], "explanations": {"级": "正确答案：级（jí），表示等级、年级。", "鸡": "鸡（jī）与 jí 声调不同（第一声），意思是家禽。", "寄": "寄（jì）与 jí 声调不同（第四声），意思是邮寄。", "挤": "挤（jǐ）与 jí 声调不同（第三声），意思是拥挤。", "齐": "齐（qí）与 jí 声母不同（q 与 j），意思是整齐。", "席": "席（xí）与 jí 声母不同（x 与 j），意思是座位。"}, "sentence_index": null, "correct_answer": "级"}, "level_3": {"options": [{"text": "级", "is_correct": true, "explanation": "正确：「分好几级」指把茶叶分成几个等级，价钱随之不同。"}, {"text": "只", "is_correct": false, "explanation": "搭配：「只」用于动物，不能用来量茶叶。"}, {"text": "座", "is_correct": false, "explanation": "搭配：「座」用于山、楼等大型建筑，不用来量茶叶。"}, {"text": "寸", "is_correct": false, "explanation": "语义：「寸」是长度单位，茶叶不能按寸分开，句子不通。"}], "explanations": {"级": "正确：「分好几级」指把茶叶分成几个等级，价钱随之不同。", "只": "搭配：「只」用于动物，不能用来量茶叶。", "座": "搭配：「座」用于山、楼等大型建筑，不用来量茶叶。", "寸": "语义：「寸」是长度单位，茶叶不能按寸分开，句子不通。"}, "sentence_index": 6, "correct_answer": "级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行一共有五级。", "explanation": "这里应该用〈段〉。级是等级或台阶的单位，不能用来计量旅行的行程，应说「五段行程」。"}, {"text": "晚会的级很精彩。", "explanation": "这里应该用〈节目〉。级指等级或年级，不能用来形容节目。"}, {"text": "这张级是三天前买的。", "explanation": "这里应该用〈车票〉。级指等级或年级，不能用来计量或指代车票。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐和我不在同一级，她比我一高级。", "corrected_sentence": "姐姐和我不在同一级，她比我高一级。", "error_description": "错误形式是「一高级」，正确形式是「高一级」。数词「一」要放在「级」前面，应说「高一级」，不能把数词放在形容词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他考了第一名，直接升了级两。", "corrected_sentence": "他考了第一名，直接升了两级。", "error_description": "错误形式是「升了级两」，正确形式是「升了两级」。数词「两」应放在量词「级」前面，「升了两级」才是正确语序，不能颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
