INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86625, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "等待是在一个地方不动，直到想见的人或事来到。", "primary_collocate": null, "pronunciation": "děng dài", "ipa": "təŋ˨˩˦ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "她站在路口等待男朋友。", "target_word": "等待", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在学校门口等待妈妈来接我。", "target_word": "等待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐在椅子上等待面试。", "target_word": "等待", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人每天在车站等待儿子回家。", "target_word": "等待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在咖啡店里等待老朋友。", "target_word": "等待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在门口等待爸爸下班。", "target_word": "等待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在雨中等待了很久，终于看到了她。", "target_word": "等待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在机场等待着客人到来。", "target_word": "等待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直在原地等待，哪儿也没去。", "target_word": "等待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在桥边等待你，不见不散。", "target_word": "等待", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "等待着", "label": "体标"}, {"form": "等待了", "label": "体标"}, {"form": "等待过", "label": "体标"}], "register": "中性", "sense_fingerprint": "等待：留在原地，直到想见的人或事来到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f80bac-fc9c-4e98-9a19-048bc01aeed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86625, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等待", "is_correct": true, "explanation": "正确。「她站在路口等待男朋友」表示留在原地，直到想见的人到来。"}, {"text": "检查", "is_correct": false, "explanation": "语义：「检查」指查看、核对，与「站在路口」的情境不符。"}, {"text": "设计", "is_correct": false, "explanation": "搭配：「设计」的对象不能是人，「设计男朋友」不成搭配。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」的对象应是有故障的物品，不能指人。"}], "explanations": {"等待": "正确。「她站在路口等待男朋友」表示留在原地，直到想见的人到来。", "检查": "语义：「检查」指查看、核对，与「站在路口」的情境不符。", "设计": "搭配：「设计」的对象不能是人，「设计男朋友」不成搭配。", "修理": "搭配：「修理」的对象应是有故障的物品，不能指人。"}, "sentence_index": 0, "correct_answer": "等待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在公园里逛了一圈，觉得花园很美，于是在花园里等待了它一会儿。", "explanation": "这里应该用〈欣赏〉。「等待」指盼望某人或事到来，不能用于对景物的欣赏。"}, {"text": "老人每天在家里打扫卫生，等待卫生干净。", "explanation": "这里应该用〈打扫〉。「等待」的对象应是某人或某事，不能指对卫生的清理动作。"}, {"text": "孩子们在操场上等待沙子，玩得很开心。", "explanation": "这里应该用〈玩〉。「等待」是盼望某人或事出现，不能用于玩沙子这类活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86625, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等待", "is_correct": true, "explanation": "正确。「他在雨中等待了很久」表示留在原地，直到想见的人出现。"}, {"text": "睡", "is_correct": false, "explanation": "语义：「睡」是睡觉，雨中睡觉不合情理，也无法说明「终于看到了她」。"}, {"text": "读", "is_correct": false, "explanation": "搭配：「读」需要书报等对象，「雨中读了很久」与情境不符。"}, {"text": "写", "is_correct": false, "explanation": "配价：「写」要求书写的对象，不能与「雨中」和「看到了她」搭配。"}], "explanations": {"等待": "正确。「他在雨中等待了很久」表示留在原地，直到想见的人出现。", "睡": "语义：「睡」是睡觉，雨中睡觉不合情理，也无法说明「终于看到了她」。", "读": "搭配：「读」需要书报等对象，「雨中读了很久」与情境不符。", "写": "配价：「写」要求书写的对象，不能与「雨中」和「看到了她」搭配。"}, "sentence_index": 6, "correct_answer": "等待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在河边等待衣服，一直洗到天黑。", "explanation": "这里应该用〈洗〉。「等待」的对象应是将要到来的人或事，不能表示洗衣服这一动作。"}, {"text": "我在商店里逛了一下午，等待了很多价格。", "explanation": "这里应该用〈比较〉。「等待」指盼望某人或事到来，不能用于比较价格。"}, {"text": "老师在教室里等待黑板，一直讲到下课。", "explanation": "这里应该用〈面对〉。「等待」指盼望某人或事到来，黑板是静止的物体，不会「到来」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86625, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在路口等待了着朋友。", "corrected_sentence": "她在路口等待着朋友。", "error_description": "错误形式是「等待了着朋友」，「了」和「着」同时出现在动词后。正确形式只用「着」，表示动作正在进行，应是「等待着朋友」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86625, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我曾在这里等待你过。", "corrected_sentence": "我曾在这里等待过你。", "error_description": "错误形式是「等待你过」，「过」放在了宾语后面。正确形式应是「等待过你」，「过」紧跟在动词后面，表示曾经发生的动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d25b25-74fb-4574-9d5a-dedbe92b8e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
