INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86629, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "些是说不多的几个，或者一点点。", "primary_collocate": null, "pronunciation": "xiē", "ipa": "ɕjɛ˥", "syllable_count": 1, "sentences": [{"text": "桌子上有一些水果。", "target_word": "些", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想买一些牛奶和面包。", "target_word": "些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请再给我一些时间。", "target_word": "些", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他有一些问题想问老师。", "target_word": "些", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个汤有点淡，再放一些盐吧。", "target_word": "些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨天看了一些书，觉得很有意思。", "target_word": "些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有一些人在跳舞。", "target_word": "些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今天吃了一些药，好多了。", "target_word": "些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教了我们一些新的字。", "target_word": "些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气冷了，你多穿一些衣服。", "target_word": "些", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一些", "label": "复合"}, {"form": "有些", "label": "复合"}], "register": "中性", "sense_fingerprint": "一些：表示少量、不多的数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c51f155-0521-4e71-90b5-132e48d69207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86629, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "些", "is_correct": true, "explanation": "些 xiē（第一声）是量词，表示不多的几个或一点儿。"}, {"text": "写", "is_correct": false, "explanation": "写 xiě（第三声）与 xiē 声调不同，意思是书写。"}, {"text": "鞋", "is_correct": false, "explanation": "鞋 xié（第二声）与 xiē 声调不同，意思是鞋子。"}, {"text": "谢", "is_correct": false, "explanation": "谢 xiè（第四声）与 xiē 声调不同，意思是感谢。"}, {"text": "虾", "is_correct": false, "explanation": "虾 xiā 的韵母是 ia，与 xiē 的 ie 不同，意思是虾。"}, {"text": "接", "is_correct": false, "explanation": "接 jiē 的声母是 j，与 xiē 的 x 不同，意思是接住、接收。"}], "explanations": {"些": "些 xiē（第一声）是量词，表示不多的几个或一点儿。", "写": "写 xiě（第三声）与 xiē 声调不同，意思是书写。", "鞋": "鞋 xié（第二声）与 xiē 声调不同，意思是鞋子。", "谢": "谢 xiè（第四声）与 xiē 声调不同，意思是感谢。", "虾": "虾 xiā 的韵母是 ia，与 xiē 的 ie 不同，意思是虾。", "接": "接 jiē 的声母是 j，与 xiē 的 x 不同，意思是接住、接收。"}, "sentence_index": null, "correct_answer": "些"}, "level_3": {"options": [{"text": "些", "is_correct": true, "explanation": "些是量词，与“一”连用表示不定的少量，正合“一些水果”。"}, {"text": "个", "is_correct": false, "explanation": "语义：“一个”指单个，与句中“有一些”的不定数量不符。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”用于长条形的东西，不用于水果。"}, {"text": "颗", "is_correct": false, "explanation": "搭配：“颗”用于粒状小物，如“一颗葡萄”，不用于泛指的水果。"}], "explanations": {"些": "些是量词，与“一”连用表示不定的少量，正合“一些水果”。", "个": "语义：“一个”指单个，与句中“有一些”的不定数量不符。", "条": "搭配：“条”用于长条形的东西，不用于水果。", "颗": "搭配：“颗”用于粒状小物，如“一颗葡萄”，不用于泛指的水果。"}, "sentence_index": 0, "correct_answer": "些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一些问题都没有。", "explanation": "这里应该用〈一点〉。“一点……都没有”是固定说法，“一些”不能这样用。"}, {"text": "他一些话都不说。", "explanation": "这里应该用〈一句〉。“一句话都不说”是固定说法，“一些”表示有几个，与“都不说”矛盾。"}, {"text": "他是我唯一的一些朋友。", "explanation": "这里应该用〈一个〉。“唯一”已表示只有一个，与“一些”的不定数量相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86629, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "些", "is_correct": true, "explanation": "些 xiē（第一声）是量词，表示不多的几个或一点儿。"}, {"text": "蟹", "is_correct": false, "explanation": "蟹 xiè（第四声）与 xiē 声调不同，意思是螃蟹。"}, {"text": "斜", "is_correct": false, "explanation": "斜 xié（第二声）与 xiē 声调不同，意思是倾斜。"}, {"text": "先", "is_correct": false, "explanation": "先 xiān 的韵母是 ian，与 xiē 的 ie 不同，意思是先、首先。"}, {"text": "切", "is_correct": false, "explanation": "切 qiē 的声母是 q，与 xiē 的 x 不同，意思是切割。"}], "explanations": {"些": "些 xiē（第一声）是量词，表示不多的几个或一点儿。", "蟹": "蟹 xiè（第四声）与 xiē 声调不同，意思是螃蟹。", "斜": "斜 xié（第二声）与 xiē 声调不同，意思是倾斜。", "先": "先 xiān 的韵母是 ian，与 xiē 的 ie 不同，意思是先、首先。", "切": "切 qiē 的声母是 q，与 xiē 的 x 不同，意思是切割。"}, "sentence_index": null, "correct_answer": "些"}, "level_3": {"options": [{"text": "些", "is_correct": true, "explanation": "些是量词，与“有一”连用表示不定的若干，正合“一些人”。"}, {"text": "位", "is_correct": false, "explanation": "语义：“位”限定单个人，与公园里多人跳舞的句意不符。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”指成双成对，与“一些人”的不定数量不合。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车，不用于人。"}], "explanations": {"些": "些是量词，与“有一”连用表示不定的若干，正合“一些人”。", "位": "语义：“位”限定单个人，与公园里多人跳舞的句意不符。", "对": "语义：“对”指成双成对，与“一些人”的不定数量不合。", "辆": "搭配：“辆”用于车，不用于人。"}, "sentence_index": 6, "correct_answer": "些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他俩是一些夫妻。", "explanation": "这里应该用〈对〉。“他俩”只有两人，是一对夫妻；“一些”指不定的几个，不能指一对。"}, {"text": "他一些手都很有力。", "explanation": "这里应该用〈双〉。两只手是成双的，应说“一双手”，不说“一些手”。"}, {"text": "他的一些心很善良。", "explanation": "这里应该用〈颗〉。心是单个的器官，应说“一颗善良的心”，不说“一些心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想喝一些了热水。", "corrected_sentence": "我想喝一些热水。", "error_description": "错误：“了”放在了“一些”和“热水”之间。“一些”后面不能加“了”，应说“我想喝一些热水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想再听一个些音乐。", "corrected_sentence": "我想再听一些音乐。", "error_description": "错误：“些”不能与量词“个”组合，“一个些”不成词，应说“一些音乐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
