INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86631, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "组合是把几样东西放在一起，变成一个新的。", "primary_collocate": null, "pronunciation": "zǔ hé", "ipa": "tsu˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我们把这些积木组合起来。", "target_word": "组合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些字母可以组合成一个新单词。", "target_word": "组合", "complexity_tier": "T3", "furigana": "zhè xiē zì mǔ kě yǐ zǔ hé chéng yí ge xīn dān cí。", "sentence_source": "generated"}, {"text": "孩子们把小木块组合成一座房子。", "target_word": "组合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以随便组合这几件衣服。", "target_word": "组合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些零件很容易组合。", "target_word": "组合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把五个字组合在一起，写成一句话。", "target_word": "组合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果把两种药组合起来用，就可能有危险。", "target_word": "组合", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "老师让我们用这些词组合句子。", "target_word": "组合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜欢把不同的颜色组合着用。", "target_word": "组合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几块板子组合后，变成了一张桌子。", "target_word": "组合", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "组合了", "label": "体标"}, {"form": "组合过", "label": "体标"}, {"form": "組合", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把几样东西放在一起，变成新的整体（动作）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c51f155-0521-4e71-90b5-132e48d69207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86631, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "组合", "is_correct": true, "explanation": "组合指把几样东西合成一个整体，与“起来”搭配，正合句意。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆散、拆除，与“组合起来”的合成意思相反。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与积木的合成无关。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”指猛然落下使破碎，不用于积木的合成。"}], "explanations": {"组合": "组合指把几样东西合成一个整体，与“起来”搭配，正合句意。", "拆": "语义：“拆”是拆散、拆除，与“组合起来”的合成意思相反。", "扔": "语义：“扔”是丢弃，与积木的合成无关。", "摔": "搭配：“摔”指猛然落下使破碎，不用于积木的合成。"}, "sentence_index": 0, "correct_answer": "组合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师把任务组合给每个学生。", "explanation": "这里应该用〈分配〉。“组合”指把几样东西合成一个整体，不能用于分派任务。"}, {"text": "他每天组合一份报告。", "explanation": "这里应该用〈撰写〉。“组合”指把几样东西合成一个整体，写报告要用“撰写”。"}, {"text": "她每天早上都组合头发。", "explanation": "这里应该用〈编〉。“组合”指把几样东西合成整体，把头发编成辫子要用“编”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86631, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "组合", "is_correct": true, "explanation": "组合指把几样东西合成一个整体，与“起来用”搭配，正合句意。"}, {"text": "分", "is_correct": false, "explanation": "语义：“分”是分开，与“把两种药合在一起用”的意思相反。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”指用刀割断，不用于药物的合用。"}, {"text": "隔", "is_correct": false, "explanation": "语义：“隔”指中间有阻隔，不表示把两种药合用。"}], "explanations": {"组合": "组合指把几样东西合成一个整体，与“起来用”搭配，正合句意。", "分": "语义：“分”是分开，与“把两种药合在一起用”的意思相反。", "切": "搭配：“切”指用刀割断，不用于药物的合用。", "隔": "语义：“隔”指中间有阻隔，不表示把两种药合用。"}, "sentence_index": 6, "correct_answer": "组合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们组合了一次活动。", "explanation": "这里应该用〈组织〉。“组合”指把几样东西合成整体，不能用于举办活动。"}, {"text": "我们要互相组合才能完成任务。", "explanation": "这里应该用〈配合〉。“互相组合”不这样说，表示彼此协作要用“配合”。"}, {"text": "他很快组合了这道数学题。", "explanation": "这里应该用〈解答〉。“组合”指把几样东西合成整体，解题要用“解答”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86631, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把花和叶子组合到一束礼物。", "corrected_sentence": "她把花和叶子组合成一束礼物。", "error_description": "“组合”后面接“成”表示结果，应说“组合成一束礼物”，“到”不能表示这种结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几根木条组合起很结实。", "corrected_sentence": "这几根木条组合起来很结实。", "error_description": "“组合”后面的趋向补语要用完整的“起来”，只说“起”不完整，应说“组合起来”，不说“组合起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
