INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86632, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由几个部分结合成整体；结合成的整体。", "primary_collocate": null, "pronunciation": "zǔ hé", "ipa": "tsu˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这个乐队的组合很特别。", "target_word": "组合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "红色和白色是很好的组合。", "target_word": "组合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们是我们班最好的组合。", "target_word": "组合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个套餐的组合很划算。", "target_word": "组合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个女子组合在中国很有名。", "target_word": "组合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包和牛奶，这个组合我每天都吃。", "target_word": "组合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两位新球员的组合让球队变强了。", "target_word": "组合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个组合由四个人组成，都是歌手。", "target_word": "组合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "黑色和金色的组合看起来很高级。", "target_word": "组合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种组合不常见，所以大家都很好奇。", "target_word": "组合", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个组合", "label": "量词"}, {"form": "組合", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由几个部分或几个人结合成的整体（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c51f155-0521-4e71-90b5-132e48d69207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "组合", "is_correct": true, "explanation": "组合指由几个人结合成的团体，正合“乐队”的语境。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单是餐馆的点菜单，与乐队无关。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是做菜的方法，与乐队无关。"}, {"text": "药方", "is_correct": false, "explanation": "语域：药方是医学用语，与乐队的语境不搭。"}], "explanations": {"组合": "组合指由几个人结合成的团体，正合“乐队”的语境。", "菜单": "语义：菜单是餐馆的点菜单，与乐队无关。", "食谱": "语义：食谱是做菜的方法，与乐队无关。", "药方": "语域：药方是医学用语，与乐队的语境不搭。"}, "sentence_index": 0, "correct_answer": "组合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的组合只有他一个人，很有名。", "explanation": "这里应该用〈歌手〉。组合指由两人以上结合成的团体，只有一人时应说“歌手”。"}, {"text": "我买了一首组合，很划算。", "explanation": "这里应该用〈个〉。“首”用于歌曲、诗词，组合不用“首”。"}, {"text": "这个乐队的一条组合很特别。", "explanation": "这里应该用〈个〉。“条”用于长条形的东西，组合是团体，应说“一个组合”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "组合", "is_correct": true, "explanation": "组合指由几个人结合成的团体，正合句中“球员”的语境。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料与球员无关，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能指人的结合，句意不通。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温与球员无关，句意不通。"}], "explanations": {"组合": "组合指由几个人结合成的团体，正合句中“球员”的语境。", "饮料": "语义：饮料与球员无关，句意不通。", "颜色": "语义：颜色不能指人的结合，句意不通。", "气温": "语义：气温与球员无关，句意不通。"}, "sentence_index": 6, "correct_answer": "组合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的组合很高。", "explanation": "这里应该用〈配置〉。电脑硬件的档次要用“配置”，“组合”指结合成的整体，不这样说。"}, {"text": "这个组合是一个苹果，很好吃。", "explanation": "这里应该用〈水果〉。组合指结合成的整体或团体，不能指一个苹果，应说“水果”。"}, {"text": "这个组合是一本字典，很厚。", "explanation": "这里应该用〈词典〉。组合指结合成的整体或团体，不能指一本字典，应说“词典”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条组合的表演很精彩。", "corrected_sentence": "这对组合的表演很精彩。", "error_description": "“组合”指两人或几人组成的团体，表示两人时用量词“对”，“条”用于长条形的东西，应说“这对组合”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个组合被三个人组成，都很年轻。", "corrected_sentence": "这个组合由三个人组成，都很年轻。", "error_description": "表示“组合由几个人构成”要用“由……组成”，“被”是被动标记，不能与“组成”搭配，应说“由三个人组成”，不说“被三个人组成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98658560-377a-4c2c-8c9d-f7f6d9318310') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
