INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86634, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担保；明确表示一定做到或一定不出问题。", "primary_collocate": null, "pronunciation": "bǎo zhèng", "ipa": "paʊ̯˨˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这家店保证产品的质量。", "target_word": "保证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生保证手术不会出问题。", "target_word": "保证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理保证三天内把货送到。", "target_word": "保证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店保证一周内可以退货。", "target_word": "保证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机要保证乘客的安全。", "target_word": "保证", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司保证所有菜都很新鲜。", "target_word": "保证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他保证过这台电脑没有问题。", "target_word": "保证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们保证按时修好路。", "target_word": "保证", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板保证了工资每月十号发。", "target_word": "保证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们保证让客人满意。", "target_word": "保证", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "保证了", "label": "体标"}, {"form": "保证过", "label": "体标"}, {"form": "保證", "label": "繁体"}, {"form": "保证金", "label": "复合"}], "register": "中性", "sense_fingerprint": "保证：动词，担保质量或结果不出问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a694cc8-f902-4891-9c84-c2b01ecc1500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86634, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "保证", "is_correct": true, "explanation": "正确答案：保证（bǎo zhèng），表示担保质量或结果不出问题。"}, {"text": "暴政", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，暴政指残暴的统治，与“担保质量”无关。"}, {"text": "保重", "is_correct": false, "explanation": "zhòng 与 zhèng 韵母不同（ong 与 eng），保重指注意身体，不是担保。"}, {"text": "保真", "is_correct": false, "explanation": "zhēn 与 zhèng 韵母和声调都不同（en 与 eng），保真指保持真实，不表示担保。"}], "explanations": {"保证": "正确答案：保证（bǎo zhèng），表示担保质量或结果不出问题。", "暴政": "bào（第四声）与 bǎo（第三声）声调不同，暴政指残暴的统治，与“担保质量”无关。", "保重": "zhòng 与 zhèng 韵母不同（ong 与 eng），保重指注意身体，不是担保。", "保真": "zhēn 与 zhèng 韵母和声调都不同（en 与 eng），保真指保持真实，不表示担保。"}, "sentence_index": null, "correct_answer": "保证"}, "level_3": {"options": [{"text": "保证", "is_correct": true, "explanation": "正确：保证表示担保，与“产品的质量”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用来说明对“产品的质量”的担保。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”接的是可以交付的物品，不能接“产品的质量”这种抽象的宾语。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”与“产品的质量”无关，句子意思不通。"}], "explanations": {"保证": "正确：保证表示担保，与“产品的质量”搭配，符合句意。", "吃": "语义：“吃”不能用来说明对“产品的质量”的担保。", "送": "搭配：“送”接的是可以交付的物品，不能接“产品的质量”这种抽象的宾语。", "喝": "语义：“喝”与“产品的质量”无关，句子意思不通。"}, "sentence_index": 0, "correct_answer": "保证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "根据发票，我保证他也许买过这台电脑。", "explanation": "这里应该用〈推断〉。保证是肯定的担保，与“也许”的不确定相矛盾；凭发票做出判断要说“推断”。"}, {"text": "这份检测报告保证产品说不定合格。", "explanation": "这里应该用〈显示〉。保证是肯定的担保，与“说不定”的不确定相矛盾；检测报告说明结果要用“显示”。"}, {"text": "这家店保证产品也许有问题。", "explanation": "这里应该用〈怀疑〉。保证是担保一定不出问题，对可能有问题的产品只能说“怀疑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保证", "is_correct": true, "explanation": "正确：保证过表示曾经担保，与“这台电脑没有问题”相符。"}, {"text": "哄", "is_correct": false, "explanation": "搭配：“哄”的对象是人或小孩，不能用来说明“这台电脑没有问题”的担保。"}, {"text": "通知", "is_correct": false, "explanation": "配价：“通知”要带受话的人，这里缺少受话对象，句子不成立。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”的对象是食物，不能接“这台电脑没有问题”这样的句子。"}], "explanations": {"保证": "正确：保证过表示曾经担保，与“这台电脑没有问题”相符。", "哄": "搭配：“哄”的对象是人或小孩，不能用来说明“这台电脑没有问题”的担保。", "通知": "配价：“通知”要带受话的人，这里缺少受话对象，句子不成立。", "品尝": "搭配：“品尝”的对象是食物，不能接“这台电脑没有问题”这样的句子。"}, "sentence_index": 6, "correct_answer": "保证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店保证产品的新鲜程度由天气决定。", "explanation": "这里应该用〈取决于〉。保证是担保一定不出问题，说质量随天气而定要用“取决于”。"}, {"text": "分析师保证股价也许会上涨。", "explanation": "这里应该用〈预测〉。保证是肯定的担保，与“也许”的不确定相矛盾；对股价走势只能做“预测”。"}, {"text": "我保证这家店的菜可能不好吃。", "explanation": "这里应该用〈估计〉。保证是担保一定不出问题，对可能不好吃的菜只能说“估计”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "商店保证着把货一周内送到。", "corrected_sentence": "商店保证把货一周内送到。", "error_description": "“保证”后面不能直接加“着”，应说成“商店保证把货一周内送到”。“着”表示持续状态，这里是承诺将来的事，错在“保证”的体标。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店保证得产品质量很好。", "corrected_sentence": "这家店保证产品质量很好。", "error_description": "“保证”后面不能直接带“得”字补语，应说成“这家店保证产品质量很好”，“得”是多余的，错在“保证”的搭配形式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
