INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86635, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "至于是说到另一件事。", "primary_collocate": null, "pronunciation": "zhì yú", "ipa": "tʂʅ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "我喜欢红色，至于蓝色，就一般。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果很好吃，至于香蕉，我不太爱吃。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先说工作，至于生活，下次再谈。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机票我来订，至于住的地方，你来找。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语很好，至于英语，就不太行了。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我看完了，至于那本，还没开始。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天先学生词，至于语法，明天再学。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我星期一有空，至于星期二，要问老板。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸去北京了，至于妈妈，她在家。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格没问题，至于质量，要再看看。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说完一件事后转到另一件事，用来引出新话题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad0f857-5768-4f5a-8c22-94fa3d0f839d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86635, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "至于", "is_correct": true, "explanation": "正确：至于 zhì yú 是介词，引出另一件事。"}, {"text": "治愈", "is_correct": false, "explanation": "治愈 zhìyù 与至于 zhì yú 第一音节相同，第二音节 yù（第四声）与 yú（第二声）声调不同，意思是治好病。"}, {"text": "迟于", "is_correct": false, "explanation": "迟于 chíyú 的声母是 ch，与 zh 不同，声调也不同，意思是比某个时间晚。"}, {"text": "终于", "is_correct": false, "explanation": "终于 zhōngyú 与 zhì yú 声母相同，韵母不同（ōng 与 ì），意思是最后。"}, {"text": "制约", "is_correct": false, "explanation": "制约 zhìyuē 第一音节相同，第二音节韵母 ü 与 üe 不同，声调也不同（yuē 第一声），意思是限制。"}], "explanations": {"至于": "正确：至于 zhì yú 是介词，引出另一件事。", "治愈": "治愈 zhìyù 与至于 zhì yú 第一音节相同，第二音节 yù（第四声）与 yú（第二声）声调不同，意思是治好病。", "迟于": "迟于 chíyú 的声母是 ch，与 zh 不同，声调也不同，意思是比某个时间晚。", "终于": "终于 zhōngyú 与 zhì yú 声母相同，韵母不同（ōng 与 ì），意思是最后。", "制约": "制约 zhìyuē 第一音节相同，第二音节韵母 ü 与 üe 不同，声调也不同（yuē 第一声），意思是限制。"}, "sentence_index": null, "correct_answer": "至于"}, "level_3": {"options": [{"text": "至于", "is_correct": true, "explanation": "正确：至于是介词，引出另一件事，这里转到「蓝色」。"}, {"text": "从", "is_correct": false, "explanation": "语义：从表示起点，句中是两种颜色的对照，「从蓝色」不表示转到另一件事。"}, {"text": "按", "is_correct": false, "explanation": "语义：按表示依照标准，「按蓝色」说不通，句中没有依据的意思。"}, {"text": "比", "is_correct": false, "explanation": "配价：比要求两项相比的结构，此处「红色」与「蓝色」的对照不用「比」来引出。"}], "explanations": {"至于": "正确：至于是介词，引出另一件事，这里转到「蓝色」。", "从": "语义：从表示起点，句中是两种颜色的对照，「从蓝色」不表示转到另一件事。", "按": "语义：按表示依照标准，「按蓝色」说不通，句中没有依据的意思。", "比": "配价：比要求两项相比的结构，此处「红色」与「蓝色」的对照不用「比」来引出。"}, "sentence_index": 0, "correct_answer": "至于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑得很快，至于赢了比赛。", "explanation": "这里应该用〈所以〉。〈至于〉只引出另一件事，不表示因果，说明结果要用「所以」。"}, {"text": "至于天气很好，我们去了公园。", "explanation": "这里应该用〈由于〉。〈至于〉只引出另一件事，不表示原因，说明原因要用「由于」。"}, {"text": "他工作很认真，至于效率很高。", "explanation": "这里应该用〈而且〉。〈至于〉只引出另一件事，不表示并列增加，说并列要用「而且」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86635, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "至于", "is_correct": true, "explanation": "正确：至于 zhì yú 是介词，引出另一件事。"}, {"text": "智育", "is_correct": false, "explanation": "智育 zhìyù 与至于 zhì yú 第一音节相同，第二音节 yù（第四声）与 yú（第二声）声调不同，意思是智力教育。"}, {"text": "志愿", "is_correct": false, "explanation": "志愿 zhìyuàn 第一音节相同，第二音节韵母由 ü 变为 üan，声调也不同（yuàn 第四声），意思是自愿或愿望。"}, {"text": "只有", "is_correct": false, "explanation": "只有 zhǐyǒu 第一音节声调不同（zhǐ 第三声），第二音节韵母 ü 与 ou 不同，意思是仅仅。"}], "explanations": {"至于": "正确：至于 zhì yú 是介词，引出另一件事。", "智育": "智育 zhìyù 与至于 zhì yú 第一音节相同，第二音节 yù（第四声）与 yú（第二声）声调不同，意思是智力教育。", "志愿": "志愿 zhìyuàn 第一音节相同，第二音节韵母由 ü 变为 üan，声调也不同（yuàn 第四声），意思是自愿或愿望。", "只有": "只有 zhǐyǒu 第一音节声调不同（zhǐ 第三声），第二音节韵母 ü 与 ou 不同，意思是仅仅。"}, "sentence_index": null, "correct_answer": "至于"}, "level_3": {"options": [{"text": "至于", "is_correct": true, "explanation": "正确：至于是介词，引出另一件事，这里转到「语法」。"}, {"text": "替", "is_correct": false, "explanation": "语义：替表示代替别人行动，「替语法」说不通，句中没有代替的意思。"}, {"text": "凭", "is_correct": false, "explanation": "语义：凭表示依据，「凭语法」说不通，句中没有依据的意思。"}, {"text": "在", "is_correct": false, "explanation": "配价：在后接地点，「语法」不是地点，无法与「在」构成介词短语。"}], "explanations": {"至于": "正确：至于是介词，引出另一件事，这里转到「语法」。", "替": "语义：替表示代替别人行动，「替语法」说不通，句中没有代替的意思。", "凭": "语义：凭表示依据，「凭语法」说不通，句中没有依据的意思。", "在": "配价：在后接地点，「语法」不是地点，无法与「在」构成介词短语。"}, "sentence_index": 6, "correct_answer": "至于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很累，至于睡着了。", "explanation": "这里应该用〈所以〉。〈至于〉只引出另一件事，不表示结果，说明结果要用「所以」。"}, {"text": "他学习很刻苦，至于考了第一名。", "explanation": "这里应该用〈所以〉。〈至于〉不表示因果，引出结果要用〈所以〉。"}, {"text": "他很聪明，至于很努力。", "explanation": "这里应该用〈而且〉。〈至于〉引出另一件事，不表示并列增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86635, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爱吃面，至于米饭，至于我不太爱吃。", "corrected_sentence": "我爱吃面，至于米饭，我不太爱吃。", "error_description": "「至于」重复：话题转到「米饭」后，第二个「至于」多余，应删去，说「我不太爱吃」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86635, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我先去北京，至于上海，至于下个月再去。", "corrected_sentence": "我先去北京，至于上海，下个月再去。", "error_description": "「至于」重复：引出「下个月」时多用了一个「至于」，应删去第二个，说「下个月再去」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
