INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86640, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "调整；配制。", "primary_collocate": null, "pronunciation": "tiáo", "ipa": "tʰiɑʊ˧˥", "syllable_count": 1, "sentences": [{"text": "请把闹钟调早一点。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把座位调到前面。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我调了一个新座位。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用水调了一碗面糊。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给孩子调了一杯蜂蜜水。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家在盘子里调颜色。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音太大了，把音量调小点。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把开会时间调到下午三点。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在碗里调蘸料，准备吃饺子。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把工作时间调了一下。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调了", "label": "体标"}, {"form": "调过", "label": "体标"}, {"form": "调整", "label": "复合"}], "register": "中性", "sense_fingerprint": "调整（时间、座位、音量）或把几种东西混合配制（调糖水、调颜色）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad0f857-5768-4f5a-8c22-94fa3d0f839d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86640, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调", "is_correct": true, "explanation": "正确：调 tiáo 表示调整或配制。"}, {"text": "跳", "is_correct": false, "explanation": "跳 tiào 与调 tiáo 声母和韵母相同，只有声调不同（第四声），意思是跳跃。"}, {"text": "挑", "is_correct": false, "explanation": "挑 tiāo 与调 tiáo 声母和韵母相同，只有声调不同（第一声），意思是挑选。"}, {"text": "桃", "is_correct": false, "explanation": "桃 táo 与调 tiáo 声调相同，只是少了介音 i，意思是桃子。"}], "explanations": {"调": "正确：调 tiáo 表示调整或配制。", "跳": "跳 tiào 与调 tiáo 声母和韵母相同，只有声调不同（第四声），意思是跳跃。", "挑": "挑 tiāo 与调 tiáo 声母和韵母相同，只有声调不同（第一声），意思是挑选。", "桃": "桃 táo 与调 tiáo 声调相同，只是少了介音 i，意思是桃子。"}, "sentence_index": null, "correct_answer": "调"}, "level_3": {"options": [{"text": "调", "is_correct": true, "explanation": "正确：调是动词，表示调整，这里把闹钟的时间调早。"}, {"text": "修", "is_correct": false, "explanation": "语义：修表示修理，句中说的是调整闹钟的时间，「修早一点」说不通。"}, {"text": "放", "is_correct": false, "explanation": "搭配：放不能与「早一点」这样的时间程度搭配，「放早一点」不通。"}, {"text": "开", "is_correct": false, "explanation": "搭配：开说的是打开闹钟，不能说「把闹钟开早一点」来表示调时间。"}], "explanations": {"调": "正确：调是动词，表示调整，这里把闹钟的时间调早。", "修": "语义：修表示修理，句中说的是调整闹钟的时间，「修早一点」说不通。", "放": "搭配：放不能与「早一点」这样的时间程度搭配，「放早一点」不通。", "开": "搭配：开说的是打开闹钟，不能说「把闹钟开早一点」来表示调时间。"}, "sentence_index": 0, "correct_answer": "调"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她调了一封信，然后寄出去。", "explanation": "这里应该用〈写〉。〈调〉不表示写作，要说「写了一封信」。"}, {"text": "他调了一个苹果，然后吃掉了。", "explanation": "这里应该用〈洗〉。〈调〉不表示清洗，要说「洗了一个苹果」。"}, {"text": "她调了一件衣服，然后晾干。", "explanation": "这里应该用〈洗〉。〈调〉不表示清洗，洗衣服要说「洗了一件衣服」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86640, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "调", "is_correct": true, "explanation": "正确：调 tiáo 表示调整或配制。"}, {"text": "掉", "is_correct": false, "explanation": "掉 diào 与调 tiáo 的声母不同（d 与 t），声调也不同，意思是落下。"}, {"text": "票", "is_correct": false, "explanation": "票 piào 与调 tiáo 的声母不同（p 与 t），声调也不同，意思是票据。"}, {"text": "桃", "is_correct": false, "explanation": "桃 táo 与调 tiáo 声调相同，只是少了介音 i，意思是桃子。"}], "explanations": {"调": "正确：调 tiáo 表示调整或配制。", "掉": "掉 diào 与调 tiáo 的声母不同（d 与 t），声调也不同，意思是落下。", "票": "票 piào 与调 tiáo 的声母不同（p 与 t），声调也不同，意思是票据。", "桃": "桃 táo 与调 tiáo 声调相同，只是少了介音 i，意思是桃子。"}, "sentence_index": null, "correct_answer": "调"}, "level_3": {"options": [{"text": "调", "is_correct": true, "explanation": "正确：调是动词，表示调整，这里把音量调小。"}, {"text": "罩", "is_correct": false, "explanation": "搭配：罩表示覆盖，不能与音量的程度搭配，「罩小点」说不通。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：剪表示切断，不能说「把音量剪小点」来表示降低音量。"}, {"text": "扎", "is_correct": false, "explanation": "搭配：扎表示刺入，「扎小点」与音量无关，句意说不通。"}], "explanations": {"调": "正确：调是动词，表示调整，这里把音量调小。", "罩": "搭配：罩表示覆盖，不能与音量的程度搭配，「罩小点」说不通。", "剪": "搭配：剪表示切断，不能说「把音量剪小点」来表示降低音量。", "扎": "搭配：扎表示刺入，「扎小点」与音量无关，句意说不通。"}, "sentence_index": 6, "correct_answer": "调"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把面包调得很脆。", "explanation": "这里应该用〈烤〉。〈调〉指调节或配制，不指加热食物，烤面包要说「烤得很脆」。"}, {"text": "她把钥匙调丢了。", "explanation": "这里应该用〈丢〉。〈调〉不表示遗失，要说「丢了钥匙」。"}, {"text": "他把桌子调得很干净。", "explanation": "这里应该用〈擦〉。〈调〉指调节，不指清洁物体，擦桌子要说「擦得很干净」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把音量调了大。", "corrected_sentence": "我把音量调大了。", "error_description": "「了」位置错误：补语「大」之后应接「了」，应说「调大了」，不能插在「调」和「大」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把闹钟调七点。", "corrected_sentence": "他把闹钟调到七点。", "error_description": "缺少补语「到」：应说「调到七点」，去掉「到」，句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bdd0f95-b0ee-45b8-8092-58409c57567e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
