INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86641, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86641, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年会是每一年大家聚在一起开的会。", "primary_collocate": null, "pronunciation": "nián huì", "ipa": "njɛn˧˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "年会的时候，同事们一起吃饭唱歌。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天下午开年会。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年会上有很多好吃的东西。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在年会上给大家发了红包。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们公司今年的年会在哪儿开？", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次参加年会，有点儿紧张。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年会结束以后，大家都回家了。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的年会我还唱过一首歌。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说今年年会要表演节目。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年会的节目是同事们自己准备的。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次年会", "label": "量词结构"}, {"form": "一场年会", "label": "量词结构"}, {"form": "公司年会", "label": "复合词"}, {"form": "年會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公司同事每年聚在一起吃饭、表演的聚会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df74260-6b71-43b4-8f1f-e506de1537f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86641, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年会", "is_correct": true, "explanation": "年会是同事每年聚在一起吃饭、表演的集会，正适合「一起吃饭唱歌」。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：「葬礼」是悼念场合，与「一起吃饭唱歌」的欢乐氛围不符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：「考试」是学习测试，同事不会在考试时一起吃饭唱歌。"}, {"text": "年夜饭", "is_correct": false, "explanation": "搭配：「年夜饭」指家人团圆的饭，不能与「同事们」一起搭配这样的场合。"}], "explanations": {"年会": "年会是同事每年聚在一起吃饭、表演的集会，正适合「一起吃饭唱歌」。", "葬礼": "语义：「葬礼」是悼念场合，与「一起吃饭唱歌」的欢乐氛围不符。", "考试": "语义：「考试」是学习测试，同事不会在考试时一起吃饭唱歌。", "年夜饭": "搭配：「年夜饭」指家人团圆的饭，不能与「同事们」一起搭配这样的场合。"}, "sentence_index": 0, "correct_answer": "年会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的年会每五年办一次，大家一起聚聚。", "explanation": "这里应该用〈同学会〉。年会是每年一次的集会，「每五年一次」的聚会不能说「年会」。"}, {"text": "这场年会在殡仪馆举行，亲人们都很悲伤。", "explanation": "这里应该用〈葬礼〉。年会是每一年大家聚在一起的会，不能用来指哀悼逝者的葬礼。"}, {"text": "为了庆祝拿到订单，公司每个月都办一次年会。", "explanation": "这里应该用〈庆功宴〉。年会一年只举行一次，每月办一次的庆祝不能叫年会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86641, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年会", "is_correct": true, "explanation": "年会是同事每年一次的聚会，结束以后大家可以各自回家。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「结束」不搭配「年龄」，年龄不能结束。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：「梦想」是心中的愿望，不会结束，也不能让大家回家。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：「眼泪」不是活动或时段，不能「结束以后」让大家回家。"}], "explanations": {"年会": "年会是同事每年一次的聚会，结束以后大家可以各自回家。", "年龄": "搭配：「结束」不搭配「年龄」，年龄不能结束。", "梦想": "语义：「梦想」是心中的愿望，不会结束，也不能让大家回家。", "眼泪": "语义：「眼泪」不是活动或时段，不能「结束以后」让大家回家。"}, "sentence_index": 6, "correct_answer": "年会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明的年会在家里举行，同学们都来了。", "explanation": "这里应该用〈生日派对〉。年会是大家每年一次聚在一起的会，不用于个人的生日聚会。"}, {"text": "学校每周一都举行年会。", "explanation": "这里应该用〈升旗仪式〉。年会一年只举行一次，不能每周举行。"}, {"text": "他们的年会在教堂举行，新郎新娘都很开心。", "explanation": "这里应该用〈婚礼〉。年会是每年一次的集会，不能用来指新人结婚的婚礼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86641, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司今年办了一条年会，大家都很高兴。", "corrected_sentence": "我们公司今年办了一场年会，大家都很高兴。", "error_description": "量词「条」用于细长的东西，年会的量词应为〈场〉或〈次〉，应说「办了一场年会」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86641, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司每年十二月都办一座年会。", "corrected_sentence": "我们公司每年十二月都办一场年会。", "error_description": "「座」用于山、楼等大型固定物，年会的量词应为〈场〉或〈次〉，应说「办一场年会」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
