INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86642, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86642, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年举行一次的集会，参加者多为同一机构或行业的人。", "primary_collocate": null, "pronunciation": "nián huì", "ipa": "njɛn˧˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "公司的年会在一月底举行。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行业的年会每年开一次。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他代表学校参加了学术年会。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年会上，经理介绍了今年的工作。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明年的年会准备在上海开。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们每年都会参加这个年会。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加年会的人都要先报名。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的年会有三百多人参加。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参加过两次这个协会的年会。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在年会上得了一个奖。", "target_word": "年会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次年会", "label": "量词结构"}, {"form": "一场年会", "label": "量词结构"}, {"form": "学术年会", "label": "复合词"}, {"form": "年會", "label": "繁体"}], "register": "正式", "sense_fingerprint": "机构或行业每年举行一次的正式集会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df74260-6b71-43b4-8f1f-e506de1537f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年会", "is_correct": true, "explanation": "年会指机构或行业每年一次的正式集会，公司可以在一月底举行。"}, {"text": "年假", "is_correct": false, "explanation": "搭配：「举行」用于集会、活动，「年假」是假期，不能举行。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」指人的岁数，不是可以在一月底举行的活动。"}, {"text": "年中", "is_correct": false, "explanation": "语义：「年中」指一年的中间时段，与「一月底」的时间相冲突。"}], "explanations": {"年会": "年会指机构或行业每年一次的正式集会，公司可以在一月底举行。", "年假": "搭配：「举行」用于集会、活动，「年假」是假期，不能举行。", "年龄": "语义：「年龄」指人的岁数，不是可以在一月底举行的活动。", "年中": "语义：「年中」指一年的中间时段，与「一月底」的时间相冲突。"}, "sentence_index": 0, "correct_answer": "年会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末晚上，我和几个朋友在家里开了一场年会。", "explanation": "这里应该用〈聚会〉。年会是机构或行业每年一次的集会，朋友私下的聚会不能说「年会」。"}, {"text": "他们俩的年会定在五月十八号，那天很多亲友都会来。", "explanation": "这里应该用〈婚礼〉。年会是机构的集会，不能用来指两个人的婚礼。"}, {"text": "我们公司每个季度都开一次年会，检查工作进度。", "explanation": "这里应该用〈季度总结会〉。年会一年只举行一次，每季度一次的会议应说「季度总结会」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年会", "is_correct": true, "explanation": "年会是每年一次的集会，参加者需要先报名，符合语境。"}, {"text": "年报", "is_correct": false, "explanation": "搭配：「参加」要搭配活动类名词，「年报」是报告书，不能参加。"}, {"text": "年底", "is_correct": false, "explanation": "语义：「年底」是时间点，不是可以参加的活动。"}, {"text": "年鉴", "is_correct": false, "explanation": "语义：「年鉴」是资料书，不是集会，不能去参加。"}], "explanations": {"年会": "年会是每年一次的集会，参加者需要先报名，符合语境。", "年报": "搭配：「参加」要搭配活动类名词，「年报」是报告书，不能参加。", "年底": "语义：「年底」是时间点，不是可以参加的活动。", "年鉴": "语义：「年鉴」是资料书，不是集会，不能去参加。"}, "sentence_index": 6, "correct_answer": "年会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个组织的年会每五年召开一次，代表们讨论重要问题。", "explanation": "这里应该用〈大会〉。年会一年只举行一次，「每五年一次」的会议应说「大会」。"}, {"text": "我们学校每学期都办一次年会，大家一起看节目。", "explanation": "这里应该用〈晚会〉。年会一年只举行一次，每学期一次的节目活动不能叫年会。"}, {"text": "这次展览的开幕年会很隆重，很多嘉宾都来了。", "explanation": "这里应该用〈晚宴〉。年会是每年一次的机构集会，一次展览的开幕宴会不能叫年会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司今年办了一把年会，大家都很高兴。", "corrected_sentence": "我们公司今年办了一场年会，大家都很高兴。", "error_description": "量词「把」用于有把手的器具，年会的量词应为〈场〉或〈次〉，应说「办了一场年会」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校每年都开一座年会，大家都很期待。", "corrected_sentence": "我们学校每年都开一次年会，大家都很期待。", "error_description": "「座」用于山、楼等大型固定物，年会的量词应为〈次〉或〈场〉，应说「开一次年会」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
