INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86644, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "代议制国家的立法机关。", "primary_collocate": null, "pronunciation": "yì huì", "ipa": "i˥˩ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "议会是这个国家的立法机关。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会负责制定和修改法律。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会议员由选民投票选出。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府的预算要先交给议会审查。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会已经批准了这项法案。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英国议会分为上院和下院。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总理要向议会报告工作。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会否决了政府提出的税收计划。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部法律在议会里争论了很久。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会选举每五年举行一次。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "议会制", "label": "复合"}, {"form": "議會", "label": "繁体"}], "register": "书面", "sense_fingerprint": "代议制国家制定法律的立法机关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b82dac-691c-4a8d-92f2-df09b4bddc7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "议会", "is_correct": true, "explanation": "议会就是国家的立法机关，符合句意。"}, {"text": "首都", "is_correct": false, "explanation": "语义：首都是城市，不是立法机关。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不可能是国家的立法机关。"}, {"text": "老窝", "is_correct": false, "explanation": "语域：“老窝”是口语，指巢穴或据点，不能用于正式的国家机构定义。"}], "explanations": {"议会": "议会就是国家的立法机关，符合句意。", "首都": "语义：首都是城市，不是立法机关。", "厨房": "语义：厨房是房间，不可能是国家的立法机关。", "老窝": "语域：“老窝”是口语，指巢穴或据点，不能用于正式的国家机构定义。"}, "sentence_index": 0, "correct_answer": "议会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家有一条议会，负责制定法律。", "explanation": "量词错误：议会是机构，应该用〈个〉。〈条〉多用于细长的东西，不能用于议会。"}, {"text": "议会负责抓捕罪犯。", "explanation": "这里应该用〈警察〉。议会负责制定法律，抓捕罪犯是警察的工作。"}, {"text": "议会判决了这起离婚案。", "explanation": "这里应该用〈法院〉。议会负责立法，判决案件是法院的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "议会", "is_correct": true, "explanation": "议会是接受总理报告的机构，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能接受报告。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能接受报告。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“向”后要接受报告的人或机构，窗户不能接受报告。"}], "explanations": {"议会": "议会是接受总理报告的机构，符合句意。", "石头": "语义：石头不能接受报告。", "天气": "语义：天气不能接受报告。", "窗户": "搭配：“向”后要接受报告的人或机构，窗户不能接受报告。"}, "sentence_index": 6, "correct_answer": "议会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我父亲是一名议会。", "explanation": "这里应该用〈议员〉。议会是机构，指人时要说〈议员〉。"}, {"text": "这个寺庙的议会每天早上念经。", "explanation": "这里应该用〈僧众〉。议会指国家的立法机关，寺庙里集体念经的是僧众，不能称为议会。"}, {"text": "这个议会在竞选中获得了最多的选票。", "explanation": "这里应该用〈政党〉。议会不参加竞选，获得选票的是政党或候选人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "不少国家都有一所议会。", "corrected_sentence": "不少国家都有一个议会。", "error_description": "量词错误：议会是机构，应说“一个议会”，不能用〈所〉。〈所〉多用于学校、医院等机构。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "总理要把议会提交预算。", "corrected_sentence": "总理要向议会提交预算。", "error_description": "介词错误：“提交”的对象是议会，应用“向”引出，不能用“把”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
