INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86646, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家、机关或个人依法拥有的支配和指挥他人的力量。", "primary_collocate": null, "pronunciation": "quán lì", "ipa": "tɕʰyɛn˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "国王有很大的权力。", "target_word": "权力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "法律给了警察一些权力。", "target_word": "权力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长的权力是人民给的。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板不能乱用手中的权力。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的权力属于人民。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官有判断案子的权力。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想拿到更大的权力。", "target_word": "权力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "权力太大，就容易出问题。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律也限制政府的权力。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长没有权力决定放假时间。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种权力", "label": "量词"}, {"form": "权力机关", "label": "复合"}, {"form": "權力", "label": "繁体"}], "register": "中性", "sense_fingerprint": "依法拥有的支配、指挥他人的力量（国家、机关或个人）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7ff3108-def9-4a18-b93a-70244681d64f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "权力", "is_correct": true, "explanation": "正确：指国王依法拥有的支配他人的力量，与“很大的”搭配，句意通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是国王可以拥有的力量或财产，填入后句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“很大的”不修饰身高，应说“很高”，“很大的身高”搭配不当。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是交易中的数额，不能说国王“有很大的价格”。"}], "explanations": {"权力": "正确：指国王依法拥有的支配他人的力量，与“很大的”搭配，句意通顺。", "颜色": "语义：颜色不是国王可以拥有的力量或财产，填入后句意不通。", "身高": "搭配：“很大的”不修饰身高，应说“很高”，“很大的身高”搭配不当。", "价格": "语义：价格是交易中的数额，不能说国王“有很大的价格”。"}, "sentence_index": 0, "correct_answer": "权力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每个人都有受教育的权力。", "explanation": "这里应该用“权利”。权力指支配、指挥他人的力量，权利指依法应享有的资格；受教育是个人应享有的资格，要用权利。"}, {"text": "他的学习权力很强。", "explanation": "这里应该用“能力”。权力是支配他人的力量，不能用来形容学习的本领；学习的本领要用能力。"}, {"text": "他承受着巨大的权力。", "explanation": "这里应该用“压力”。“承受”的对象是压力，不能说承受权力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "权力", "is_correct": true, "explanation": "正确：指可以支配他人的力量，能够“拿到”，并与“更大的”搭配。"}, {"text": "病", "is_correct": false, "explanation": "语义：“病”不是可以拿到、并且能“更大”的东西，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“拿到”不与“声音”搭配，应说“发出声音”或“提高声音”。"}, {"text": "鼻子", "is_correct": false, "explanation": "体貌：鼻子是身体的部位，不是可以拿到的东西，句子不成立。"}], "explanations": {"权力": "正确：指可以支配他人的力量，能够“拿到”，并与“更大的”搭配。", "病": "语义：“病”不是可以拿到、并且能“更大”的东西，句意不通。", "声音": "搭配：“拿到”不与“声音”搭配，应说“发出声音”或“提高声音”。", "鼻子": "体貌：鼻子是身体的部位，不是可以拿到的东西，句子不成立。"}, "sentence_index": 6, "correct_answer": "权力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的权力很大。", "explanation": "这里应该用“威力”。权力指支配他人的力量，机器的破坏力要用威力。"}, {"text": "这支球队的权力很强。", "explanation": "这里应该用“实力”。权力指支配他人的力量，球队的竞技水平要用实力。"}, {"text": "这辆汽车的权力很大。", "explanation": "这里应该用“动力”。权力指支配他人的力量，汽车的输出能力要用动力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在公司里拥有一个权力。", "corrected_sentence": "他在公司里拥有一种权力。", "error_description": "量词错误：“权力”是抽象名词，应用量词“种”，“个”不能修饰权力；正确说法是“一种权力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他掌握着一把特殊的权力。", "corrected_sentence": "他掌握着一种特殊的权力。", "error_description": "量词错误：“把”用于有柄的器具，不能修饰抽象的权力；应用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
