INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86647, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "适当是不多不少，刚刚好。", "primary_collocate": null, "pronunciation": "shì dàng", "ipa": "ʂʐ̩˥˩ taŋ˥˩", "syllable_count": 2, "sentences": [{"text": "做菜时盐要放得适当。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天适当运动，对身体好。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的温度很适当，不冷也不热。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭要适当，不要太多，也不要太少。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的大小很适当。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的长度很适当，读起来不累。", "target_word": "适当", "complexity_tier": "T3", "furigana": "zhè piān wén zhāng de cháng dù hěn shì dàng, dú qǐ lái bú lèi.", "sentence_source": "generated"}, {"text": "孩子玩手机的时间要适当。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面条煮的时间很适当，不硬也不软。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作和休息要安排得适当。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的灯光适当，不太亮也不太暗。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "适当地", "label": "状语形式"}, {"form": "適當", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数量、程度、时间等不多不少，恰到好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3410f726-dd8b-4348-a976-24df9c72ab9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86647, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "适当", "is_correct": true, "explanation": "适当：盐的用量不多不少，恰到好处，与语境相符。"}, {"text": "尖", "is_correct": false, "explanation": "语义：「尖」指形状锐利，与盐的用量无关，盐放得尖说不通。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：「亮」不用来形容盐的用量。"}, {"text": "脏", "is_correct": false, "explanation": "语义：「脏」指卫生状况，盐放得脏与做菜的语境不符。"}], "explanations": {"适当": "适当：盐的用量不多不少，恰到好处，与语境相符。", "尖": "语义：「尖」指形状锐利，与盐的用量无关，盐放得尖说不通。", "亮": "搭配：「亮」不用来形容盐的用量。", "脏": "语义：「脏」指卫生状况，盐放得脏与做菜的语境不符。"}, "sentence_index": 0, "correct_answer": "适当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事他处理得很适当，没有引起误会。", "explanation": "这里的「适当」是「恰当、得体」的意思，指处理方式合宜，与「不多不少」的义项不同。"}, {"text": "她讲话很适当，没有让大家尴尬。", "explanation": "这里的「适当」是「得体」的意思，指说话合宜，与「不多不少」的义项不同。"}, {"text": "这个地方很适当，适合作为会场。", "explanation": "这里的「适当」是「恰当、合宜」的意思，指地点合适，与「不多不少」的义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86647, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "适当", "is_correct": true, "explanation": "适当：时间安排不多不少，恰到好处，与「要」搭配。"}, {"text": "圆", "is_correct": false, "explanation": "语义：「圆」形容形状，时间不能说圆。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：「硬」不用于形容时间。"}, {"text": "绿", "is_correct": false, "explanation": "语义：「绿」指颜色，与玩手机的时间无关。"}], "explanations": {"适当": "适当：时间安排不多不少，恰到好处，与「要」搭配。", "圆": "语义：「圆」形容形状，时间不能说圆。", "硬": "搭配：「硬」不用于形容时间。", "绿": "语义：「绿」指颜色，与玩手机的时间无关。"}, "sentence_index": 6, "correct_answer": "适当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "参加面试，他的穿着很适当。", "explanation": "这里的「适当」是「恰当、得体」的意思，指穿着合适，与「不多不少」的义项不同。"}, {"text": "他的回答很适当，老师很满意。", "explanation": "这里的「适当」是「恰当、得体」的意思，指回答合宜，与「不多不少」的义项不同。"}, {"text": "他的脸色很适当。", "explanation": "这里应该用〈红润〉。脸色的好坏要用〈红润〉或〈苍白〉，适当不用来形容脸色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86647, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "煮饭时水要加得适当地。", "corrected_sentence": "煮饭时水要加得适当。", "error_description": "「加得适当地」应为「加得适当」。“得”后面的形容词作补语，不加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86647, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的用药剂量很适当地，不太多也不太少。", "corrected_sentence": "他的用药剂量很适当，不太多也不太少。", "error_description": "「很适当地」应为「很适当」。“适当”作谓语形容词时，句末不加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
