INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86651, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "永远是一直这样，不会结束。", "primary_collocate": null, "pronunciation": "yǒng yuǎn", "ipa": "jʊŋ˨˩ ɥɛn˨˩", "syllable_count": 2, "sentences": [{"text": "世界上没有永远不变的东西。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事永远不会结束。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他永远留在了这座小城。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望春天永远不走。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的笑容永远在我心里。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人能永远年轻。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路好像永远走不完。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们永远住在海边的小房子里。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子永远是父母的宝贝。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌我永远听不够。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "永永远远", "label": "重叠"}], "register": "中性", "sense_fingerprint": "副词；状态一直这样、不会结束或改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128e6c3e-0b01-402e-9083-229985605fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86651, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永远", "is_correct": true, "explanation": "正确。“永远”表示状态一直不变、不会结束，与“永远不变的东西”相符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快发生，与“不变”的持久状态无关，句子不通。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示立即，不能说明事物持续不变。"}, {"text": "刚刚", "is_correct": false, "explanation": "搭配：“刚刚”表示刚发生，不能修饰“不变的东西”这种长期状态。"}], "explanations": {"永远": "正确。“永远”表示状态一直不变、不会结束，与“永远不变的东西”相符。", "马上": "语义：“马上”表示很快发生，与“不变”的持久状态无关，句子不通。", "立刻": "语义：“立刻”表示立即，不能说明事物持续不变。", "刚刚": "搭配：“刚刚”表示刚发生，不能修饰“不变的东西”这种长期状态。"}, "sentence_index": 0, "correct_answer": "永远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场雨永远下了三天。", "explanation": "这里误把“永远”当成了“一连”（连续不断地持续若干时间）。“永远”没有终点，不能限定为“三天”。"}, {"text": "我永远去过那家店一次。", "explanation": "这里误把“永远”当成了“从来”（用于否定，表示一直没有过）。“永远”表示没有终点，不能与“去过一次”这样有限的次数搭配。"}, {"text": "他永远在下午五点吃完了饭。", "explanation": "这里误把“永远”当成了“正好”（恰好在某一时刻）。“永远”不能修饰在确定时间点完成的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "永远", "is_correct": true, "explanation": "正确。“永远”表示状态一直持续、没有终点，与“走不完”相符。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上发生，与“走不完”所描述的长久状态不符。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去，与描述现在状态的“好像……走不完”时态不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时，改变了“走不完”的持续含义，与“好像……永远走不完”的描述不符。"}], "explanations": {"永远": "正确。“永远”表示状态一直持续、没有终点，与“走不完”相符。", "立即": "语义：“立即”表示马上发生，与“走不完”所描述的长久状态不符。", "曾经": "语义：“曾经”指过去，与描述现在状态的“好像……走不完”时态不符。", "偶尔": "语义：“偶尔”表示有时，改变了“走不完”的持续含义，与“好像……永远走不完”的描述不符。"}, "sentence_index": 6, "correct_answer": "永远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他永远找到了工作。", "explanation": "这里误把“永远”当成了“终于”（经过努力后最终达到）。“永远”表示没有终点，不能表示“最后找到”。"}, {"text": "这次考试他永远考了满分。", "explanation": "这里误把“永远”当成了“竟然”（出乎意料）。“永远”表示没有终点，不能表示“竟然考了满分”的意外。"}, {"text": "你永远马上过来吧。", "explanation": "这里误把“永远”当成了表示“立即、很快”的词。“永远”没有时间终点，不能表示即刻过来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他永远了爱着这座小城。", "corrected_sentence": "他永远爱着这座小城。", "error_description": "助词位置错误：“了”不能插在副词“永远”与动词之间，须删去。正确的说法是“他永远爱着这座小城。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
